DECLARATIONS.update({'city_calculate_live_quotient_2': {'signature': 'state: SceneState, inputs: CityCalculateLiveQuotient2Input', 'returns': 'CityCalculateLiveQuotient2Result', 'flow': "checked_state(state)\nif type(inputs) is not CityCalculateLiveQuotient2Input:\n    raise ValueError('function-specific typed input required')\ninputs.validate(state)\nframe = first_replace(FirstDeploymentFrame.unobserved(), target_x=inputs.value, target_y=inputs.field, count=inputs.row, offset_y=inputs.member, choice=inputs.remaining, controller=inputs.descriptor.cursor())\nframe = city_calculate_live_quotient_2_fields(state, frame)\nreturn CityCalculateLiveQuotient2Result(destination=frame.roster, source=frame.candidates, descriptor=frame.controller, value=frame.target_x, field=frame.target_y, tile=frame.unit, row=frame.count, member=frame.offset_y, remaining=frame.choice, carry=bool(frame.status & 1), zero=bool(frame.status & 4), negative=bool(frame.status & 8), overflow=bool(frame.status & 2))"}})


# Entire sole _special_action_frame current field/body declaration.
DECLARATIONS.update({'_special_action_frame': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "checked_state(state)\nif type(frame) is not FirstDeploymentFrame:\n    raise ValueError('actual special-action field frame required')\nframe.validate(state)\nif any((value is None for value in (frame.target_x, frame.target_y, frame.unit, frame.count, frame.distance, frame.offset_x, frame.offset_y, frame.choice, frame.roster, frame.candidates, frame.controller, frame.scan, frame.opponent, frame.scratch, frame.auxiliary, frame.stack_cursor, frame.status))):\n    raise MovementContinuationBoundary(107678, frame, 'historical special-action projection lacks actual complete entry fields')\nreturn _movement_frame(state, frame)"}})


