DECLARATIONS.update({'city_resolve_readonly_state_5_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "checked_state(state)\nif type(frame) is not FirstDeploymentFrame:\n    raise ValueError('actual roster-count fields required')\nframe.validate(state, frame.stack_cursor is not None)\nif frame.target_x is None:\n    raise MovementContinuationBoundary(110428, frame, 'incoming D0 upper bits were not observed')\nselection = state.read(4294964950, 2)\nframe = _first_word(frame, 'target_x', selection)\nselection &= 2\nframe = _first_word(frame, 'target_x', selection)\nframe = _first_shift_word(frame, 'target_x', selection, 1)\npointer = state.read(110456 + selection * 2, 4)\nframe = first_replace(frame, roster=state.table_at(pointer).cursor())\nframe = _first_word(frame, 'target_x', 0)\nwhile True:\n    member = frame.roster.word()\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _first_memory_word(frame, member)\n    if member & 32768:\n        break\n    frame = _first_add_word(frame, 'target_x', low16(frame.target_x), 1)\nstate.sr = state.sr & 65504 | frame.status\nreturn frame.validate(state, frame.stack_cursor is not None)"}, '_resource_cost_frame': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, target: int', 'returns': 'FirstDeploymentFrame', 'flow': "checked_state(state)\nif type(frame) is not FirstDeploymentFrame:\n    raise ValueError('actual resource-cost fields required')\nframe.validate(state, frame.stack_cursor is not None)\nif any((value is None for value in (frame.target_x, frame.target_y, frame.unit, frame.count, frame.distance, frame.offset_x, frame.offset_y, frame.choice, frame.roster, frame.candidates, frame.controller, frame.scan, frame.opponent, frame.scratch, frame.auxiliary, frame.stack_cursor, frame.status))):\n    raise MovementContinuationBoundary(target, frame, 'historical resource interface did not observe full fields or entry SP')\nreturn _movement_frame(state, frame)"}, '_sample_battle_resource_cost_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, base_divisor: int, random_return: int, divide_instruction: int', 'returns': 'FirstDeploymentFrame', 'flow': "if base_divisor not in (20, 30, 40):\n    raise ValueError('original resource divisor base required')\nframe = sample_battle_action_random_fields(BattlePolicyMemory(state), frame, random_return)\nframe = _movement_move_long(state, frame, 'target_x', frame.target_x & 65535)\nframe = _movement_move_long(state, frame, 'target_y', frame.target_x)\nframe = _special_action_shift_long(state, frame, 'target_x', 2)\nframe = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y)\nframe = _special_action_shift_long(state, frame, 'target_x', 1)\nframe = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y)\nframe = _special_action_swap(state, frame, 'target_x')\nframe = _movement_add_word(state, frame, 'target_x', base_divisor)\nframe = first_replace(frame, roster=state.table_at(4294952960).cursor())\nframe = _movement_move(state, frame, 'target_y', state.read(4294964134, 2), 16)\nframe = _movement_fixed_shift_word(state, frame, 'target_y', 2)\nframe = _movement_move_long(state, frame, 'unit', frame.roster.long(low16(frame.target_y)))\ndivisor = low16(frame.target_x)\nif divisor == 0:\n    raise MovementContinuationBoundary(divide_instruction, frame, 'original DIVU requires its real exception fields')\nif frame.unit // divisor <= 65535:\n    frame = _movement_divu_word(state, frame, 'unit', divisor, divide_instruction)\nframe = _movement_move_long(state, frame, 'unit', frame.unit & 65535)\nstate.write(4294964126, 4, frame.unit)\nreturn _movement_test_long(state, frame, frame.unit)"}, 'city_calculate_live_quotient_7_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': 'frame = _resource_cost_frame(state, frame, 110524)\nreturn _sample_battle_resource_cost_fields(state, frame, 20, 110530, 110566)'}, 'city_calculate_live_quotient_8_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': 'frame = _resource_cost_frame(state, frame, 110580)\nreturn _sample_battle_resource_cost_fields(state, frame, 30, 110586, 110622)'}, 'city_calculate_live_quotient_9_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': 'frame = _resource_cost_frame(state, frame, 110636)\nreturn _sample_battle_resource_cost_fields(state, frame, 40, 110642, 110678)'}, 'city_coordinate_live_state_79_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 110464)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964948, 2), 16)\nframe = _movement_shift_word(state, frame, 'target_x')\ndisplacement = state.read(u32(110496 + s16(low16(frame.target_x))), 2)\nframe = _movement_move(state, frame, 'target_x', displacement, 16)\ntarget = u32(110524 + s16(displacement))\nstack = frame.stack_cursor.advance(-4)\nstack.set_long(0, 110478)\nentered = first_replace(frame, stack_cursor=stack)\nif target == 110524:\n    frame = city_calculate_live_quotient_7_fields(state, entered)\nelif target == 110580:\n    frame = city_calculate_live_quotient_8_fields(state, entered)\nelif target == 110636:\n    frame = city_calculate_live_quotient_9_fields(state, entered)\nelse:\n    raise MovementContinuationBoundary(target, entered, 'selected resource cost is not yet field-closed')\nreturned = frame.stack_cursor.long()\nif returned != 110478:\n    raise FirstDeploymentReturnBoundary(returned, frame, 110478)\nframe = first_replace(frame, stack_cursor=frame.stack_cursor.advance(4))\nframe = _movement_move(state, frame, 'target_x', state.read(4294964950, 2), 16)\nframe = _movement_fixed_shift_word(state, frame, 'target_x', 2)\npointer = state.read(u32(110508 + s16(low16(frame.target_x))), 4)\nframe = first_replace(frame, roster=state.table_at(pointer).cursor())\nframe = _movement_move_long(state, frame, 'target_x', frame.roster.long())\npreserved_x = frame.status & 16\nframe, difference = _movement_binary_flags(state, frame, frame.target_x, state.read(4294964126, 4), 32, True)\nframe = first_replace(frame, status=frame.status & 15 | preserved_x)\nstate.sr = state.sr & 65504 | frame.status\nreturn _resource_cost_frame(state, frame, 110464)"}, 'city_resolve_readonly_state_5': {'signature': 'state: SceneState, inputs: CityResolveReadonlyState5Input', 'returns': 'CityResolveReadonlyState5Result', 'flow': "checked_state(state)\nif type(inputs) is not CityResolveReadonlyState5Input:\n    raise ValueError('function-specific typed input required')\ninputs.validate(state)\nframe = first_replace(FirstDeploymentFrame.unobserved(), target_x=inputs.value)\nframe = city_resolve_readonly_state_5_fields(state, frame)\nreturn CityResolveReadonlyState5Result(destination=frame.roster, value=frame.target_x, carry=bool(frame.status & 1), zero=bool(frame.status & 4), negative=bool(frame.status & 8), overflow=bool(frame.status & 2)).validate(state)"}, 'city_coordinate_live_state_79': {'signature': 'state: SceneState, inputs: CityCoordinateLiveState79Input', 'returns': 'CityCoordinateLiveState79Result', 'flow': "checked_state(state)\nif type(inputs) is not CityCoordinateLiveState79Input:\n    raise ValueError('function-specific typed input required')\ninputs.validate(state)\nframe = first_replace(FirstDeploymentFrame.unobserved(), target_x=inputs.value)\nframe = city_coordinate_live_state_79_fields(state, frame)\nreturn CityCoordinateLiveState79Result(destination=frame.roster, value=frame.target_x, carry=bool(frame.status & 1), zero=bool(frame.status & 4), negative=bool(frame.status & 8), overflow=bool(frame.status & 2)).validate(state)"}, 'city_calculate_live_quotient_7': {'signature': 'state: SceneState, inputs: CityCalculateLiveQuotient7Input', 'returns': 'CityCalculateLiveQuotient7Result', 'flow': "checked_state(state)\nif type(inputs) is not CityCalculateLiveQuotient7Input:\n    raise ValueError('function-specific typed input required')\ninputs.validate(state)\nframe = city_calculate_live_quotient_7_fields(state, FirstDeploymentFrame.unobserved())\nreturn CityCalculateLiveQuotient7Result(destination=frame.roster, value=frame.target_x, field=frame.target_y, tile=frame.unit, carry=bool(frame.status & 1), zero=bool(frame.status & 4), negative=bool(frame.status & 8), overflow=bool(frame.status & 2)).validate(state)"}, 'city_calculate_live_quotient_8': {'signature': 'state: SceneState, inputs: CityCalculateLiveQuotient8Input', 'returns': 'CityCalculateLiveQuotient8Result', 'flow': "checked_state(state)\nif type(inputs) is not CityCalculateLiveQuotient8Input:\n    raise ValueError('function-specific typed input required')\ninputs.validate(state)\nframe = city_calculate_live_quotient_8_fields(state, FirstDeploymentFrame.unobserved())\nreturn CityCalculateLiveQuotient8Result(destination=frame.roster, value=frame.target_x, field=frame.target_y, tile=frame.unit, carry=bool(frame.status & 1), zero=bool(frame.status & 4), negative=bool(frame.status & 8), overflow=bool(frame.status & 2)).validate(state)"}, 'city_calculate_live_quotient_9': {'signature': 'state: SceneState, inputs: CityCalculateLiveQuotient9Input', 'returns': 'CityCalculateLiveQuotient9Result', 'flow': "checked_state(state)\nif type(inputs) is not CityCalculateLiveQuotient9Input:\n    raise ValueError('function-specific typed input required')\ninputs.validate(state)\nframe = city_calculate_live_quotient_9_fields(state, FirstDeploymentFrame.unobserved())\nreturn CityCalculateLiveQuotient9Result(destination=frame.roster, value=frame.target_x, field=frame.target_y, tile=frame.unit, carry=bool(frame.status & 1), zero=bool(frame.status & 4), negative=bool(frame.status & 8), overflow=bool(frame.status & 2)).validate(state)"}})

DECLARATIONS.update({'city_calculate_live_quotient_4': {'signature': 'state: SceneState, inputs: CityCalculateLiveQuotient4Input', 'returns': 'CityCalculateLiveQuotient4Result', 'flow': "checked_state(state)\nif type(inputs) is not CityCalculateLiveQuotient4Input:\n    raise ValueError('function-specific historical presentation input required')\ninputs.validate(state)\nconditions = int(inputs.carry) | (2 if inputs.overflow else 0) | (4 if inputs.zero else 0) | (8 if inputs.negative else 0)\nstate.sr = state.sr & 65520 | conditions\nframe = first_replace(FirstDeploymentFrame.unobserved(), target_x=inputs.value, target_y=inputs.field, unit=inputs.tile, count=inputs.row, distance=inputs.offset, choice=inputs.remaining, controller=inputs.descriptor.cursor())\nframe = city_calculate_live_quotient_4_fields(state, frame)\nreturn CityCalculateLiveQuotient4Result(destination=state.table_at(frame.roster.base), source=state.table_at(frame.candidates.base), descriptor=state.table_at(frame.controller.base), value=frame.target_x, field=frame.target_y, tile=frame.unit, row=frame.count, offset=frame.distance, remaining=frame.choice, carry=bool(state.sr & 1), zero=bool(state.sr & 4), negative=bool(state.sr & 8), overflow=bool(state.sr & 2)).validate(state)"}})

DECLARATIONS.update({'city_calculate_live_quotient_5': {'signature': 'state: SceneState, inputs: CityCalculateLiveQuotient5Input', 'returns': 'CityCalculateLiveQuotient5Result', 'flow': "checked_state(state)\nif type(inputs) is not CityCalculateLiveQuotient5Input:\n    raise ValueError('function-specific historical presentation input required')\ninputs.validate(state)\nconditions = int(inputs.carry) | (2 if inputs.overflow else 0) | (4 if inputs.zero else 0) | (8 if inputs.negative else 0)\nstate.sr = state.sr & 65520 | conditions\nframe = first_replace(FirstDeploymentFrame.unobserved(), target_x=inputs.value, target_y=inputs.field, unit=inputs.tile, distance=inputs.offset)\nframe = city_calculate_live_quotient_5_fields(state, frame)\nreturn CityCalculateLiveQuotient5Result(source=state.table_at(frame.candidates.base), value=frame.target_x, field=frame.target_y, tile=frame.unit, offset=frame.distance, carry=bool(state.sr & 1), zero=bool(state.sr & 4), negative=bool(state.sr & 8), overflow=bool(state.sr & 2)).validate(state)"}})

DECLARATIONS.update({'city_update_live_fields_11': {'signature': 'state: SceneState, inputs: CityUpdateLiveFields11Input', 'returns': 'CityUpdateLiveFields11Result', 'flow': "checked_state(state)\nif type(inputs) is not CityUpdateLiveFields11Input:\n    raise ValueError('function-specific historical presentation input required')\ninputs.validate(state)\nconditions = int(inputs.carry) | (2 if inputs.overflow else 0) | (4 if inputs.zero else 0) | (8 if inputs.negative else 0)\nstate.sr = state.sr & 65520 | conditions\nframe = first_replace(FirstDeploymentFrame.unobserved(), target_x=inputs.value)\nframe = city_update_live_fields_11_fields(state, frame)\nreturn CityUpdateLiveFields11Result(destination=state.table_at(frame.roster.base), value=frame.target_x, carry=bool(state.sr & 1), zero=bool(state.sr & 4), negative=bool(state.sr & 8), overflow=bool(state.sr & 2)).validate(state)"}})

DECLARATIONS.update({'_restorative_action_sixfold_draw_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, continuation, fresh_seed: bool', 'returns': 'FirstDeploymentFrame', 'flow': "frame = sample_battle_action_random_fields(BattlePolicyMemory(state), frame, continuation)\nif fresh_seed:\n    frame = _movement_move_long(state, frame, 'target_x', 0)\n    frame = _movement_move(state, frame, 'target_x', state.read(4294964764, 2), 16)\nelse:\n    frame = _movement_move_long(state, frame, 'target_x', frame.target_x & 65535)\nframe = _movement_move_long(state, frame, 'target_y', frame.target_x)\nframe = _special_action_shift_long(state, frame, 'target_x', 1)\nframe = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y)\nframe = _special_action_shift_long(state, frame, 'target_x', 1)\nframe = _special_action_swap(state, frame, 'target_x')\nif fresh_seed:\n    frame = _movement_add_word(state, frame, 'target_x', 5)\nreturn frame"}})

DECLARATIONS.update({'_restorative_action_positive_status_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _restorative_action_sixfold_draw_fields(state, frame, 109014, True)\nframe = first_replace(frame, roster=state.table_at(4294952192).cursor())\nframe = _movement_move(state, frame, 'target_y', state.read(4294964210, 2), 16)\nframe = _movement_move(state, frame, 'unit', frame.roster.byte(low16(frame.target_y)), 8)\nframe = _movement_add_byte(state, frame, 'unit', low8(frame.target_x))\nframe = _movement_compare(state, frame, low16(frame.unit), 99, 16)\nif not frame.status & 5:\n    frame = _movement_move(state, frame, 'unit', 99, 8)\nframe.roster.set_byte(low16(frame.target_y), low8(frame.unit))\nframe = _movement_test(state, frame, low8(frame.unit), 8)\nframe = _restorative_action_sixfold_draw_fields(state, frame, 109070, True)\nframe = _movement_move(state, frame, 'target_y', state.read(4294964134, 2), 16)\nframe = _movement_move(state, frame, 'unit', frame.roster.byte(low16(frame.target_y)), 8)\nframe = _movement_add_word(state, frame, 'unit', low16(frame.target_x))\nframe = _movement_compare(state, frame, low8(frame.unit), 99, 8)\nif not frame.status & 5:\n    frame = _movement_move(state, frame, 'unit', 99, 8)\nframe.roster.set_byte(low16(frame.target_y), low8(frame.unit))\nreturn _movement_test(state, frame, low8(frame.unit), 8)"}})

DECLARATIONS.update({'_restorative_action_positive_rewards_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = first_replace(frame, roster=state.table_at(4294950400).cursor(), candidates=state.table_at(4294950912).cursor())\nframe = _movement_move(state, frame, 'target_x', low16(frame.choice), 16)\nframe = _movement_shift_word(state, frame, 'target_x')\nframe = _movement_add_word(state, frame, 'target_x', low16(frame.choice))\nframe = _movement_move(state, frame, 'target_y', state.read(4294964210, 2), 16)\nframe = _movement_shift_word(state, frame, 'target_y')\nframe = _special_action_add_capped_word(state, frame, frame.roster, low16(frame.target_y), 'unit', low16(frame.target_x))\nframe = _movement_move(state, frame, 'unit', low16(frame.target_x), 16)\nframe = _movement_shift_word(state, frame, 'target_x')\nframe = _movement_add_word(state, frame, 'target_x', low16(frame.unit))\nframe = _movement_move_long(state, frame, 'target_x', frame.target_x & 65535)\nframe = _movement_divu_word(state, frame, 'target_x', 10, 109170)\nframe = _special_action_add_capped_word(state, frame, frame.candidates, low16(frame.target_y), 'unit', low16(frame.target_x))\nframe = _movement_move(state, frame, 'target_x', low16(frame.choice), 16)\nframe = _movement_move(state, frame, 'target_y', state.read(4294964134, 2), 16)\nframe = _movement_shift_word(state, frame, 'target_y')\nframe = _special_action_add_capped_word(state, frame, frame.roster, low16(frame.target_y), 'unit', low16(frame.target_x))\nframe = _first_right_word(frame, 'target_x', low16(frame.target_x), 1)\nstate.sr = state.sr & 65504 | frame.status\nreturn _special_action_add_capped_word(state, frame, frame.candidates, low16(frame.target_y), 'unit', low16(frame.target_x))"}})

DECLARATIONS.update({'_restorative_action_failed_status_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _restorative_action_sixfold_draw_fields(state, frame, 109272, False)\nframe = first_replace(frame, roster=state.table_at(4294952192).cursor())\nframe = _movement_move(state, frame, 'target_y', state.read(4294964210, 2), 16)\nframe = _movement_move(state, frame, 'unit', frame.roster.byte(low16(frame.target_y)), 8)\nframe, value = _movement_binary_flags(state, frame, low8(frame.unit), low8(frame.target_x), 8, True)\nframe = first_replace(frame, unit=replace_byte(frame.unit, value))\nif frame.status & 1:\n    frame = _movement_move(state, frame, 'unit', 0, 8)\nframe.roster.set_byte(low16(frame.target_y), low8(frame.unit))\nframe = _movement_test(state, frame, low8(frame.unit), 8)\nframe = _restorative_action_sixfold_draw_fields(state, frame, 109316, False)\nframe = _movement_move(state, frame, 'target_y', state.read(4294964134, 2), 16)\nframe = _movement_move(state, frame, 'unit', frame.roster.byte(low16(frame.target_y)), 8)\nframe, value = _movement_binary_flags(state, frame, low8(frame.unit), low8(frame.target_x), 8, True)\nframe = first_replace(frame, unit=replace_byte(frame.unit, value))\nif frame.status & 1:\n    frame = _movement_move(state, frame, 'unit', 0, 8)\nframe.roster.set_byte(low16(frame.target_y), low8(frame.unit))\nreturn _movement_test(state, frame, low8(frame.unit), 8)"}})

DECLARATIONS.update({'_restorative_action_failed_rewards_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = first_replace(frame, candidates=state.table_at(4294950400).cursor(), controller=state.table_at(4294950912).cursor(), roster=state.table_at(4294948352).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964134, 2), 16)\nframe = _movement_shift_word(state, frame, 'target_x')\nframe = _movement_move(state, frame, 'target_y', frame.roster.word(low16(frame.target_x)), 16)\nframe = _movement_move(state, frame, 'unit', state.read(4294964210, 2), 16)\nframe = _movement_shift_word(state, frame, 'unit')\nframe = _special_action_sub_word(state, frame, 'target_y', frame.roster.word(low16(frame.unit)))\nif not frame.status & 1:\n    frame = _movement_move(state, frame, 'target_y', low16(frame.target_y), 16)\n    frame = _movement_divu_word(state, frame, 'target_y', 10, 109390)\n    frame = _special_action_add_capped_word(state, frame, frame.candidates, low16(frame.unit), 'count', low16(frame.target_y))\nframe = sample_battle_action_random_fields(BattlePolicyMemory(state), frame, 109422)\nframe = _movement_move_long(state, frame, 'target_x', frame.target_x & 65535)\nframe = _movement_fixed_shift_word(state, frame, 'target_x', 4)\nframe = _special_action_swap(state, frame, 'target_x')\nframe = _movement_add_word(state, frame, 'target_x', 5)\nframe = _movement_move(state, frame, 'unit', state.read(4294964134, 2), 16)\nframe = _movement_shift_word(state, frame, 'unit')\nframe = _special_action_add_capped_word(state, frame, frame.controller, low16(frame.unit), 'distance', low16(frame.target_x))\nframe = sample_battle_action_random_fields(BattlePolicyMemory(state), frame, 109470)\nframe = _movement_move_long(state, frame, 'target_x', frame.target_x & 65535)\nframe = _movement_move_long(state, frame, 'target_y', frame.target_x)\nframe = _special_action_shift_long(state, frame, 'target_x', 1)\nframe = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y)\nframe = _special_action_shift_long(state, frame, 'target_x', 2)\nframe = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y)\nframe = _special_action_swap(state, frame, 'target_x')\nreturn _special_action_add_capped_word(state, frame, frame.candidates, low16(frame.unit), 'distance', low16(frame.target_x))"}})

DECLARATIONS.update({'city_calculate_live_quotient_4_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _special_action_frame(state, frame)\nframe = _special_action_call(state, frame, 108532, 108980)\nframe = _special_action_call(state, frame, 109516, 108984)\nframe = _special_action_call(state, frame, 108450, 108988)\nframe = _movement_test(state, frame, low16(frame.choice), 16)\nif frame.status & 4:\n    frame = _restorative_action_failed_status_fields(state, frame)\n    frame = _restorative_action_failed_rewards_fields(state, frame)\n    state.set_status_word(state.read_status_word() | 1)\nelse:\n    frame = _movement_move_long(state, frame, 'choice', frame.choice & 65535)\n    frame = _movement_divu_word(state, frame, 'choice', 100, 109000)\n    frame = _special_action_call(state, frame, 109572, 109008)\n    frame = _restorative_action_positive_status_fields(state, frame)\n    frame = _restorative_action_positive_rewards_fields(state, frame)\n    state.write(16740390, 2, 28)\n    frame = _movement_test(state, frame, 28, 16)\n    state.set_status_word(state.read_status_word() & 65534)\nframe = first_replace(frame, status=state.sr & 31)\nreturn _special_action_frame(state, frame)"}})

DECLARATIONS.update({'city_calculate_live_quotient_5_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _special_action_frame(state, frame)\nframe = _special_action_call(state, frame, 108294, 109520)\nframe = _movement_add_word(state, frame, 'distance', 5)\nframe = _movement_move(state, frame, 'distance', low16(frame.target_x), 16)\nframe = _special_action_call(state, frame, 107576, 109528)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964134, 2), 16)\nframe = _movement_fixed_shift_word(state, frame, 'target_x', 2)\nframe = first_replace(frame, candidates=state.table_at(4294943056).cursor())\nframe = _movement_move(state, frame, 'target_y', frame.candidates.word(low16(frame.target_x)), 16)\nframe = _first_right_word(frame, 'target_y', low16(frame.target_y), 7)\nstate.sr = state.sr & 65504 | frame.status\nframe = _movement_move(state, frame, 'unit', frame.candidates.word(low16(frame.target_x), 2), 16)\nframe = _first_right_word(frame, 'unit', low16(frame.unit), 7)\nstate.sr = state.sr & 65504 | frame.status\nframe, terrain = _deployment_terrain_lookup(BattlePolicyMemory(state), frame, low16(frame.target_y), low16(frame.unit), 109554)\nframe = _movement_compare(state, frame, low16(frame.target_x), 6, 16)\nif frame.status & 4:\n    frame = _movement_multiply_word(state, frame, 'distance', 12)\n    frame = _movement_divu_word(state, frame, 'distance', 10, 109564)\nframe = _movement_move(state, frame, 'target_x', low16(frame.distance), 16)\nreturn _special_action_frame(state, frame)"}})

DECLARATIONS.update({'city_update_live_fields_11_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "checked_state(state)\nif type(frame) is not FirstDeploymentFrame:\n    raise ValueError('actual target-status frame required')\nframe.validate(state, frame.stack_cursor is not None)\nframe = _first_word(frame, 'target_x', state.read(4294964134, 2))\nframe = first_replace(frame, roster=state.table_at(4294944340).cursor())\nframe.roster.set_byte(low16(frame.target_x), 130)\nstate.sr = state.sr & 65520 | 8\nframe = first_replace(frame, status=None if frame.status is None else frame.status & 16 | 8)\nframe = first_replace(frame, roster=state.table_at(4294944852).cursor())\nactor = state.read(4294964211, 1)\nframe.roster.set_byte(low16(frame.target_x), actor)\nconditions = (8 if actor & 128 else 0) | (4 if actor == 0 else 0)\nstate.sr = state.sr & 65520 | conditions\nframe = first_replace(frame, status=None if frame.status is None else frame.status & 16 | conditions)\nreturn frame.validate(state, frame.stack_cursor is not None)"}})

DECLARATIONS.update({'_special_action_call': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, target, continuation', 'returns': 'FirstDeploymentFrame', 'flow': 'uint(target, 32)\nuint(continuation, 32)\nstack = frame.stack_cursor.advance(-4)\nstack.set_long(0, continuation)\nentered = first_replace(frame, stack_cursor=stack)\nstate.sr = state.sr & 65504 | entered.status\nif target == 108532:\n    result = city_resolve_readonly_state_4_fields(state, entered)\nelif target == 108294:\n    result = sample_battle_special_status_factor_fields(BattlePresentationMemory(state), entered)\nelif target == 108450:\n    result = compute_battle_damage_potential_fields(BattlePresentationMemory(state), entered, entered.target_x)\nelif target == 108956:\n    result = city_update_live_fields_10_fields(state, entered)\nelif target == 107576:\n    result = _battle_action_map_fields(BattlePolicyMemory(state), entered)\nelif target == 109516:\n    result = city_calculate_live_quotient_5_fields(state, entered)\nelif target == 109572:\n    result = city_update_live_fields_11_fields(state, entered)\nelse:\n    result = state.service_at(target, entered)\nresult = _special_action_frame(state, result)\nstate.sr = state.sr & 65504 | result.status\nreturned = result.stack_cursor.long()\nresult = first_replace(result, stack_cursor=result.stack_cursor.advance(4))\nif returned != continuation:\n    raise FirstDeploymentReturnBoundary(returned, result, continuation)\nreturn result'}})

DECLARATIONS.update({'city_coordinate_live_state_76_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "checked_state(state)\nif type(frame) is not FirstDeploymentFrame:\n    raise ValueError('sole actual presentation fields required')\nframe.validate(state, frame.stack_cursor is not None)\nstate.write(16740390, 2, 65535)\nframe = _first_memory_word(frame, 65535)\nmode = state.read(4294964948, 2)\nframe = _first_word(frame, 'target_x', mode)\nframe = _first_shift_word(frame, 'target_x', mode, 1)\noffset = state.read(u32(107666 + s16(u16(mode << 1))), 2)\nframe = _first_word(frame, 'target_x', offset)\ntarget = u32(107678 + s16(offset))\nif frame.stack_cursor is not None:\n    stack = frame.stack_cursor.advance(-4)\n    stack.set_long(0, 107664)\n    frame = first_replace(frame, stack_cursor=stack)\nif frame.status is not None:\n    state.sr = state.sr & 65504 | frame.status\nif target == 107678:\n    from .business_city import city_calculate_live_quotient_2_fields\n    returned = city_calculate_live_quotient_2_fields(state, frame)\nelif target == 108568:\n    returned = city_calculate_live_quotient_3_fields(state, frame)\nelif target == 108976:\n    returned = city_calculate_live_quotient_4_fields(state, frame)\nelse:\n    raise Boundary('original dynamic presentation target is not field-closed: ' + str(target))\nif type(returned) is not FirstDeploymentFrame:\n    raise Boundary('presentation child must return genuine current full fields')\nreturned.validate(state, frame.stack_cursor is not None)\nif returned.stack_cursor is not None:\n    actual = returned.stack_cursor.long()\n    if actual != 107664:\n        raise Boundary('original internal presentation return slot changed to ' + str(actual))\n    returned = first_replace(returned, stack_cursor=returned.stack_cursor.advance(4))\nif returned.status is not None:\n    state.sr = state.sr & 65504 | returned.status\nreturn returned.validate(state, frame.stack_cursor is not None)"}})

