DECLARATIONS.update({'city_coordinate_live_state_83': {'signature': 'state: SceneState, inputs: CityCoordinateLiveState83Input', 'returns': 'CityCoordinateLiveState83Result', 'flow': "checked_state(state)\nif type(inputs) is not CityCoordinateLiveState83Input:\n    raise ValueError('function-specific historical presentation input required')\ninputs.validate(state)\nconditions = int(inputs.carry) | (2 if inputs.overflow else 0) | (4 if inputs.zero else 0) | (8 if inputs.negative else 0)\nstate.sr = state.sr & 65520 | conditions\nframe = first_replace(FirstDeploymentFrame.unobserved(), target_x=inputs.value, target_y=inputs.field, unit=inputs.tile)\nframe = city_coordinate_live_state_83_fields(state, frame)\nreturn CityCoordinateLiveState83Result(destination=state.table_at(frame.roster.base), value=frame.target_x, field=frame.target_y, tile=frame.unit, carry=bool(state.sr & 1), zero=bool(state.sr & 4), negative=bool(state.sr & 8), overflow=bool(state.sr & 2)).validate(state)"}})

DECLARATIONS.update({'city_scale_live_record_value_3_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 110692)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964134, 2), 16)\nframe = _movement_shift_word(state, frame, 'target_x')\nframe = first_replace(frame, roster=state.table_at(4294947840).cursor())\nframe = _movement_move(state, frame, 'unit', frame.roster.word(low16(frame.target_x)), 16)\nframe = first_replace(frame, roster=state.table_at(4294948352).cursor())\nframe = _movement_add_word(state, frame, 'unit', frame.roster.word(low16(frame.target_x)))\nframe = sample_battle_action_random_fields(BattlePolicyMemory(state), frame, 110720)\nframe = _movement_move_long(state, frame, 'target_x', frame.target_x & 65535)\nframe = _movement_move_long(state, frame, 'target_y', frame.target_x)\nframe = _special_action_shift_long(state, frame, 'target_x', 2)\nframe = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y)\nframe = _special_action_swap(state, frame, 'target_x')\nframe = _movement_add_word(state, frame, 'target_x', 8)\nframe = _movement_multiply_word(state, frame, 'unit', low16(frame.target_x))\nstate.write(4294964126, 4, frame.unit)\nreturn _movement_test_long(state, frame, frame.unit)"}})

DECLARATIONS.update({'_battle_command_call_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, target, continuation', 'returns': 'FirstDeploymentFrame', 'flow': "if target not in (110770, 110852, 110904, 44040):\n    raise ValueError('closed original command/list child required')\nframe = _resource_cost_frame(state, frame, target)\nstack = frame.stack_cursor.advance(-4)\nstack.set_long(0, uint(continuation, 32))\nentered = first_replace(frame, stack_cursor=stack)\nstate.sr = state.sr & 65504 | entered.status\nif target == 110770:\n    result = city_select_live_state_19_fields(state, entered)\nelif target == 110852:\n    result = city_coordinate_live_state_82_fields(state, entered)\nelif target == 110904:\n    result = city_coordinate_live_state_83_fields(state, entered)\nelse:\n    result = state.service_at(44040, entered)\nresult = _resource_cost_frame(state, result, target)\nactual = result.stack_cursor.long()\nif actual != continuation:\n    raise FirstDeploymentReturnBoundary(actual, result, continuation)\nreturned = first_replace(result, stack_cursor=result.stack_cursor.advance(4))\nstate.sr = state.sr & 65504 | returned.status\nreturn returned"}})

DECLARATIONS.update({'city_select_live_state_19_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "from .business_highbank import _position_strategy_status\nchecked_state(state)\nif type(frame) is not FirstDeploymentFrame:\n    raise ValueError('actual roster-tag fields required')\nframe.validate(state, frame.stack_cursor is not None)\nif frame.roster is None or frame.candidates is None or frame.target_x is None or (frame.target_y is None):\n    raise MovementContinuationBoundary(110770, frame, 'actual tag/source views and D0/D1 required')\nwhile True:\n    member = frame.candidates.next_word()\n    frame = _first_word(frame, 'target_y', member)\n    frame = _position_strategy_status(state, frame, member, 16)\n    if member & 32768:\n        return frame\n    member &= 255\n    frame = _first_word(frame, 'target_y', member)\n    frame = _position_strategy_status(state, frame, member, 16)\n    label = low8(frame.target_x)\n    frame.roster.set_byte(member, label)\n    frame = _position_strategy_status(state, frame, label, 8)"}})

DECLARATIONS.update({'city_coordinate_live_state_80_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 110744)\nframe = first_replace(frame, roster=state.table_at(4294942800).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964874, 2), 16)\nframe = first_replace(frame, candidates=state.table_at(4294944080).cursor())\nframe = _battle_command_call_fields(state, frame, 110770, 110760)\nframe = first_replace(frame, candidates=state.table_at(4294944164).cursor())\nreturn _battle_command_call_fields(state, frame, 110770, 110768)"}})

DECLARATIONS.update({'city_coordinate_live_state_81_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 110786)\nselected = bool(state.read(4294964133, 1) & 4)\nframe = first_replace(frame, status=frame.status & 27 | (0 if selected else 4))\nstate.sr = state.sr & 65504 | frame.status\nif not selected:\n    return frame\nframe = _battle_command_call_fields(state, frame, 110852, 110800)\nframe = _battle_command_call_fields(state, frame, 110904, 110804)\nframe = first_replace(frame, roster=state.table_at(110826).cursor())\nframe = _movement_move(state, frame, 'target_x', 48, 16)\nframe = _movement_move(state, frame, 'target_y', 232, 16)\nframe = _movement_move(state, frame, 'unit', 0, 16)\nreturn _battle_command_call_fields(state, frame, 44040, 110824)"}})

DECLARATIONS.update({'city_coordinate_live_state_82_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 110852)\nframe = first_replace(frame, roster=state.table_at(110888).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964000, 2), 16)\nframe = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 248, 16)\nif frame.status & 4:\n    frame = first_replace(frame, roster=frame.roster.advance(8))\nframe = _movement_move(state, frame, 'target_x', 72, 16)\nframe = _movement_move(state, frame, 'target_y', 240, 16)\nframe = _movement_move(state, frame, 'unit', 0, 16)\nreturn _battle_command_call_fields(state, frame, 44040, 110886)"}})

DECLARATIONS.update({'city_coordinate_live_state_83_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 110904)\nframe = first_replace(frame, roster=state.table_at(110988).cursor())\nframe = _movement_test(state, frame, state.read(4294965112, 2), 16)\nif not frame.status & 4:\n    selected = bool(state.read(4294964001, 1) & 8)\n    frame = first_replace(frame, status=frame.status & 27 | (0 if selected else 4))\n    state.sr = state.sr & 65504 | frame.status\n    if selected:\n        frame = first_replace(frame, roster=frame.roster.advance(8))\nframe = _movement_move(state, frame, 'target_x', 88, 16)\nframe = _movement_move(state, frame, 'target_y', 248, 16)\nframe = _movement_move(state, frame, 'unit', 0, 16)\nframe = _battle_command_call_fields(state, frame, 44040, 110944)\nframe = _movement_test(state, frame, state.read(4294965112, 2), 16)\nif not frame.status & 4:\n    frame = _movement_compare(state, frame, state.read(4294965116, 2), 16442, 16)\n    if frame.status & 4:\n        state.read(4294965112, 2)\n        state.write(4294965112, 2, 0)\n        frame = _movement_test(state, frame, 0, 16)\nelse:\n    frame = _movement_compare(state, frame, state.read(4294965116, 2), 16441, 16)\n    if frame.status & 4:\n        state.write(4294965112, 2, 1)\n        frame = _movement_test(state, frame, 1, 16)\nreturn frame"}})

DECLARATIONS.update({'city_coordinate_live_state_79_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 110464)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964948, 2), 16)\nframe = _movement_shift_word(state, frame, 'target_x')\ndisplacement = state.read(u32(110496 + s16(low16(frame.target_x))), 2)\nframe = _movement_move(state, frame, 'target_x', displacement, 16)\ntarget = u32(110524 + s16(displacement))\nstack = frame.stack_cursor.advance(-4)\nstack.set_long(0, 110478)\nentered = first_replace(frame, stack_cursor=stack)\nif target == 110524:\n    frame = city_calculate_live_quotient_7_fields(state, entered)\nelif target == 110580:\n    frame = city_calculate_live_quotient_8_fields(state, entered)\nelif target == 110636:\n    frame = city_calculate_live_quotient_9_fields(state, entered)\nelif target == 110692:\n    frame = city_scale_live_record_value_3_fields(state, entered)\nelse:\n    raise MovementContinuationBoundary(target, entered, 'selected resource cost is not yet field-closed')\nreturned = frame.stack_cursor.long()\nif returned != 110478:\n    raise FirstDeploymentReturnBoundary(returned, frame, 110478)\nframe = first_replace(frame, stack_cursor=frame.stack_cursor.advance(4))\nframe = _movement_move(state, frame, 'target_x', state.read(4294964950, 2), 16)\nframe = _movement_fixed_shift_word(state, frame, 'target_x', 2)\npointer = state.read(u32(110508 + s16(low16(frame.target_x))), 4)\nframe = first_replace(frame, roster=state.table_at(pointer).cursor())\nframe = _movement_move_long(state, frame, 'target_x', frame.roster.long())\npreserved_x = frame.status & 16\nframe, difference = _movement_binary_flags(state, frame, frame.target_x, state.read(4294964126, 4), 32, True)\nframe = first_replace(frame, status=frame.status & 15 | preserved_x)\nstate.sr = state.sr & 65504 | frame.status\nreturn _resource_cost_frame(state, frame, 110464)"}})

