DECLARATIONS.update({'_battle_command_call_fields': {'flow': 'if target not in (110770, 110852, 110904, 44040):\n'
                                         "    raise ValueError('closed original command/list child "
                                         "required')\n"
                                         'frame = _resource_cost_frame(state, frame, target)\n'
                                         'stack = frame.stack_cursor.advance(-4)\n'
                                         'stack.set_long(0, uint(continuation, 32))\n'
                                         'entered = first_replace(frame, stack_cursor=stack)\n'
                                         'state.sr = state.sr & 65504 | entered.status\n'
                                         'if target == 110770:\n'
                                         '    result = city_select_live_state_19_fields(state, entered)\n'
                                         'elif target == 110852:\n'
                                         '    result = city_coordinate_live_state_82_fields(state, entered)\n'
                                         'elif target == 110904:\n'
                                         '    result = city_coordinate_live_state_83_fields(state, entered)\n'
                                         'else:\n'
                                         '    from .services import SpritePacketMemory, '
                                         'append_live_command_sprite_fields\n'
                                         '    result = '
                                         'append_live_command_sprite_fields(SpritePacketMemory(state), '
                                         'entered)\n'
                                         'result = _resource_cost_frame(state, result, target)\n'
                                         'actual = result.stack_cursor.long()\n'
                                         'if actual != continuation:\n'
                                         '    raise FirstDeploymentReturnBoundary(actual, result, '
                                         'continuation)\n'
                                         'returned = first_replace(result, '
                                         'stack_cursor=result.stack_cursor.advance(4))\n'
                                         'state.sr = state.sr & 65504 | returned.status\n'
                                         'return returned',
                                 'returns': 'FirstDeploymentFrame',
                                 'signature': 'state: SceneState, frame: FirstDeploymentFrame, target, '
                                              'continuation'}})

DECLARATIONS.update({'city_coordinate_live_state_84': {'signature': 'state: SceneState, inputs: CityCoordinateLiveState84Input', 'returns': 'CityCoordinateLiveState84Result', 'flow': "checked_state(state)\nif type(inputs) is not CityCoordinateLiveState84Input:\n    raise ValueError('function-specific historical presentation input required')\ninputs.validate(state)\nconditions = int(inputs.carry) | (2 if inputs.overflow else 0) | (4 if inputs.zero else 0) | (8 if inputs.negative else 0)\nstate.sr = state.sr & 65520 | conditions\nframe = first_replace(FirstDeploymentFrame.unobserved(), target_x=inputs.value, target_y=inputs.field, unit=inputs.tile)\nframe = city_coordinate_live_state_84_fields(state, frame)\nreturn CityCoordinateLiveState84Result(destination=state.table_at(frame.roster.base), source=state.table_at(frame.candidates.base), value=frame.target_x, field=frame.target_y, tile=frame.unit, carry=bool(state.sr & 1), zero=bool(state.sr & 4), negative=bool(state.sr & 8), overflow=bool(state.sr & 2)).validate(state)"}})

DECLARATIONS.update({'city_process_counted_records_13': {'signature': 'state: SceneState, inputs: CityProcessCountedRecords13Input', 'returns': 'CityProcessCountedRecords13Result', 'flow': "checked_state(state)\nif type(inputs) is not CityProcessCountedRecords13Input:\n    raise ValueError('function-specific historical presentation input required')\ninputs.validate(state)\nconditions = int(inputs.carry) | (2 if inputs.overflow else 0) | (4 if inputs.zero else 0) | (8 if inputs.negative else 0)\nstate.sr = state.sr & 65520 | conditions\nframe = first_replace(FirstDeploymentFrame.unobserved(), target_x=inputs.value, unit=inputs.tile)\nframe = city_process_counted_records_13_fields(state, frame)\nreturn CityProcessCountedRecords13Result(destination=state.table_at(frame.roster.base), source=state.table_at(frame.candidates.base), value=frame.target_x, tile=frame.unit, carry=bool(state.sr & 1), zero=bool(state.sr & 4), negative=bool(state.sr & 8), overflow=bool(state.sr & 2)).validate(state)"}})

DECLARATIONS.update({'city_process_counted_records_14': {'signature': 'state: SceneState, inputs: CityProcessCountedRecords14Input', 'returns': 'CityProcessCountedRecords14Result', 'flow': "checked_state(state)\nif type(inputs) is not CityProcessCountedRecords14Input:\n    raise ValueError('function-specific historical presentation input required')\ninputs.validate(state)\nconditions = int(inputs.carry) | (2 if inputs.overflow else 0) | (4 if inputs.zero else 0) | (8 if inputs.negative else 0)\nstate.sr = state.sr & 65520 | conditions\nframe = first_replace(FirstDeploymentFrame.unobserved(), target_x=inputs.value, target_y=inputs.field, unit=inputs.tile)\nframe = city_process_counted_records_14_fields(state, frame)\nreturn CityProcessCountedRecords14Result(destination=state.table_at(frame.roster.base), value=frame.target_x, field=frame.target_y, tile=frame.unit, carry=bool(state.sr & 1), zero=bool(state.sr & 4), negative=bool(state.sr & 8), overflow=bool(state.sr & 2)).validate(state)"}})

DECLARATIONS.update({'_deployment_menu_bit': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, value, bit: int', 'returns': 'FirstDeploymentFrame', 'flow': "if bit not in (1, 4, 6, 14):\n    raise ValueError('closed deployment flag bits required')\nuint(value, 32)\nstatus = frame.status & 27 | (0 if value & 1 << bit else 4)\nstate.sr = state.sr & 65504 | status\nreturn first_replace(frame, status=status)"}})

DECLARATIONS.update({'execute_deployment_menu_fields': {'signature': 'state: SceneState, target: int, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, target)\nif target == 111004:\n    return city_coordinate_live_state_84_fields(state, frame)\nif target == 111078:\n    return city_process_counted_records_13_fields(state, frame)\nif target == 111120:\n    return city_process_counted_records_14_fields(state, frame)\nif target == 111174:\n    return deploy_selected_group_fields(state, frame)\nif target == 111202:\n    return count_selected_deployment_fields(state, frame)\nif target == 111226:\n    return initialize_selected_assignment_fields(state, frame)\nif target == 111292:\n    return transfer_selected_group_resources_fields(state, frame)\nif target == 111630:\n    return selected_troop_weights_fields(state, frame)\nif target == 111688:\n    return split_group_resource_share_fields(state, frame)\nif target == 111730:\n    return remove_deployed_group_members_fields(state, frame)\nif target == 111850:\n    return refresh_object_attribute_average_fields(state, frame)\nif target == 111890:\n    return submit_deployment_queue_fields(state, frame)\nif target == 111992:\n    return clear_original_tail_coordinate_fields(state, frame)\nraise MovementContinuationBoundary(target, frame, 'deployment menu target not owned by this family')"}})

DECLARATIONS.update({'_deployment_menu_call_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, target: int, continuation: int', 'returns': 'FirstDeploymentFrame', 'flow': 'frame = _resource_cost_frame(state, frame, target)\nstack = frame.stack_cursor.advance(-4)\nstack.set_long(0, uint(continuation, 32))\nentered = first_replace(frame, stack_cursor=stack)\nif target == 218976:\n    result = signed_divmod_fields(state, entered)\nelse:\n    result = execute_deployment_menu_fields(state, target, entered)\nresult = _resource_cost_frame(state, result, target)\nreturned = result.stack_cursor.long()\nif returned != continuation:\n    raise FirstDeploymentReturnBoundary(returned, result, continuation)\nreturn first_replace(result, stack_cursor=result.stack_cursor.advance(4))'}})

DECLARATIONS.update({'city_process_counted_records_13_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 111078)\npointer = state.read(16726060, 4)\nframe = first_replace(frame, roster=state.table_at(pointer).cursor(), candidates=state.table_at(4294964480).cursor())\nframe = _movement_move(state, frame, 'target_x', frame.roster.byte(), 8)\nframe = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 15, 16)\nstate.write(4294964790, 2, low16(frame.target_x))\nframe = _movement_test(state, frame, low16(frame.target_x), 16)\nframe = _movement_adjust_word(state, frame, 'target_x', -1)\nframe = _movement_move(state, frame, 'unit', 0, 16)\nframe = first_replace(frame, roster=frame.roster.advance(13))\nwhile True:\n    member = frame.roster.byte()\n    frame = first_replace(frame, roster=frame.roster.advance(1))\n    frame = _movement_move(state, frame, 'unit', member, 8)\n    frame.candidates.set_word(0, low16(frame.unit))\n    frame = first_replace(frame, candidates=frame.candidates.advance(2))\n    frame = _movement_test(state, frame, low16(frame.unit), 16)\n    frame = first_replace(frame, target_x=replace_word(frame.target_x, u16(low16(frame.target_x) - 1)))\n    if low16(frame.target_x) == 65535:\n        break\nframe.candidates.set_word(0, 65535)\nreturn _movement_test(state, frame, 65535, 16)"}})

DECLARATIONS.update({'city_process_counted_records_14_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 111120)\nframe = first_replace(frame, roster=state.table_at(4294964263).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964114, 2), 16)\nframe = _movement_move(state, frame, 'target_y', frame.roster.byte(low16(frame.target_x)), 8)\nframe = _movement_compare(state, frame, low8(frame.target_y), state.read(4294964087, 1), 8)\nif frame.status & 4:\n    frame = _deployment_menu_bit(state, frame, frame.target_x, 6)\n    frame = first_replace(frame, target_x=frame.target_x | 64)\nframe = first_replace(frame, roster=state.table_at(4294943056).cursor())\nframe = _movement_move(state, frame, 'target_y', 0, 16)\nframe = _movement_move(state, frame, 'unit', 255, 16)\nwhile True:\n    frame = first_replace(frame, roster=frame.roster.advance(-1))\n    frame = _movement_compare(state, frame, low8(frame.target_x), frame.roster.byte(), 8)\n    if frame.status & 4:\n        frame = _movement_adjust_word(state, frame, 'target_y', 1)\n    frame = first_replace(frame, unit=replace_word(frame.unit, u16(low16(frame.unit) - 1)))\n    if low16(frame.unit) == 65535:\n        break\nframe = _movement_move(state, frame, 'target_x', 10, 16)\nreturn _special_action_sub_word(state, frame, 'target_x', low16(frame.target_y))"}})

DECLARATIONS.update({'city_coordinate_live_state_84_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': 'frame = _resource_cost_frame(state, frame, 111004)\nframe = _deployment_menu_call_fields(state, frame, 111078, 111008)\nframe = _deployment_menu_call_fields(state, frame, 111120, 111012)\nframe = _movement_test(state, frame, low16(frame.target_x), 16)\nif frame.status & 4:\n    return frame\nfor address, value, clear in ((4294964870, low16(frame.target_x), False), (4294964736, 64, False), (4294964754, 518, False), (4294964066, 8, False), (4294964074, 0, True), (4294964824, 0, True), (4294964078, 0, True), (4294964088, 1, False), (4294964822, 1, False), (4294964868, 0, True)):\n    if clear:\n        state.read(address, 2)\n    state.write(address, 2, value)\n    frame = _movement_test(state, frame, value, 16)\nreturn frame'}})

DECLARATIONS.update({'count_selected_deployment_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 111202)\nframe = first_replace(frame, candidates=state.table_at(4294964480).cursor())\nframe = _movement_move(state, frame, 'choice', 0, 16)\nwhile True:\n    member = frame.candidates.word()\n    frame = first_replace(frame, candidates=frame.candidates.advance(2))\n    frame = _movement_move(state, frame, 'target_x', member, 16)\n    if frame.status & 8:\n        return frame\n    frame = _deployment_menu_bit(state, frame, frame.target_x, 14)\n    if not frame.status & 4:\n        frame = _movement_adjust_word(state, frame, 'choice', 1)"}})

DECLARATIONS.update({'initialize_selected_assignment_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 111226)\nframe = first_replace(frame, candidates=state.table_at(4294942800).cursor(), controller=state.table_at(4294964480), opponent=state.table_at(4294943056))\nframe = _movement_move(state, frame, 'target_x', frame.roster.byte(0, 4), 8)\nframe = first_replace(frame, scan=state.table_at(4294964263).cursor())\nframe = _movement_move(state, frame, 'target_y', state.read(4294964114, 2), 16)\nframe = _movement_compare(state, frame, low8(frame.target_x), frame.scan.byte(low16(frame.target_y)), 8)\nif frame.status & 4:\n    frame = _deployment_menu_bit(state, frame, frame.target_y, 6)\n    frame = first_replace(frame, target_y=frame.target_y | 64)\nwhile True:\n    member = frame.controller.word()\n    frame = first_replace(frame, controller=frame.controller.advance(2))\n    frame = _movement_move(state, frame, 'target_x', member, 16)\n    if frame.status & 8:\n        return frame\n    frame = _deployment_menu_bit(state, frame, frame.target_x, 14)\n    if frame.status & 4:\n        continue\n    frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 255, 16)\n    label = low8(frame.target_y)\n    frame.candidates.set_byte(low16(frame.target_x), label)\n    frame = _movement_test(state, frame, label, 8)\n    frame = _movement_fixed_shift_word(state, frame, 'target_x', 2)\n    frame.opponent.long(low16(frame.target_x))\n    frame.opponent.set_long(low16(frame.target_x), 0)\n    frame = _movement_test_long(state, frame, 0)"}})

DECLARATIONS.update({'selected_troop_weights_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 111630)\nframe = first_replace(frame, candidates=state.table_at(4294964480).cursor(), controller=state.table_at(4294952960))\nframe = _movement_move_long(state, frame, 'offset_x', 0)\nframe = _movement_move_long(state, frame, 'offset_y', 0)\nwhile True:\n    member = frame.candidates.word()\n    frame = first_replace(frame, candidates=frame.candidates.advance(2))\n    frame = _movement_move(state, frame, 'unit', member, 16)\n    if frame.status & 8:\n        break\n    frame = _movement_move(state, frame, 'count', low16(frame.unit), 16)\n    frame = _movement_fixed_shift_word(state, frame, 'count', 2)\n    frame = _deployment_menu_bit(state, frame, frame.unit, 14)\n    if not frame.status & 4:\n        frame = _movement_arithmetic_long(state, frame, 'offset_x', frame.controller.long(low16(frame.count)))\n        frame = _movement_arithmetic_long(state, frame, 'offset_x', 100)\n    frame = _movement_arithmetic_long(state, frame, 'offset_y', frame.controller.long(low16(frame.count)))\n    frame = _movement_arithmetic_long(state, frame, 'offset_y', 100)\nframe = _first_right_word(frame, 'offset_x', low16(frame.offset_x), 5)\nstate.sr = state.sr & 65504 | frame.status\nframe = _first_right_word(frame, 'offset_y', low16(frame.offset_y), 5)\nstate.sr = state.sr & 65504 | frame.status\nreturn frame"}})

DECLARATIONS.update({'split_group_resource_share_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 111688)\nframe = _movement_move_long(state, frame, 'count', frame.unit)\noriginal = frame.unit\nshifted = original >> 5\nframe = first_replace(frame, unit=shifted, status=(17 if original & 16 else 0) | (4 if shifted == 0 else 0))\nstate.sr = state.sr & 65504 | frame.status\nframe = _movement_move(state, frame, 'target_y', low16(frame.unit), 16)\nframe = _movement_multiply_word(state, frame, 'target_y', low16(frame.offset_x))\nframe = _special_action_swap(state, frame, 'unit')\nframe = _movement_multiply_word(state, frame, 'unit', low16(frame.offset_x))\nframe = _special_action_swap(state, frame, 'unit')\nframe = _movement_arithmetic_long(state, frame, 'target_y', frame.unit)\nframe = _movement_move_long(state, frame, 'unit', frame.offset_y)\nframe = _deployment_menu_call_fields(state, frame, 218976, 111712)\nframe = _movement_move_long(state, frame, 'unit', frame.count)\nframe = _movement_move_long(state, frame, 'unit', frame.unit & 31)\nframe = _movement_fixed_shift_word(state, frame, 'unit', 1, True)\nframe = _first_shift_word(frame, 'target_y', low16(frame.target_y), 5)\nstate.sr = state.sr & 65504 | frame.status\nframe = _movement_arithmetic_long(state, frame, 'target_y', frame.unit)\nreturn _movement_arithmetic_long(state, frame, 'count', frame.target_y, True)"}})

DECLARATIONS.update({'transfer_selected_group_resources_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 111292)\nframe = _movement_compare(state, frame, low16(frame.choice), state.read(4294964790, 2), 16)\nif frame.status & 4:\n    frame = _movement_load_packed_resource(state, frame, 'target_x', 5)\n    state.write(4294964126, 4, frame.target_x)\n    frame = _movement_test_long(state, frame, frame.target_x)\n    frame = _movement_load_packed_resource(state, frame, 'target_x', 9)\n    state.write(4294964154, 4, frame.target_x)\n    frame = _movement_test_long(state, frame, frame.target_x)\nelse:\n    frame = _deployment_menu_call_fields(state, frame, 111630, 111304)\n    for first, destination, continuation in ((5, 4294964126, 111330), (9, 4294964154, 111382)):\n        frame = _movement_load_packed_resource(state, frame, 'unit', first)\n        frame = _deployment_menu_call_fields(state, frame, 111688, continuation)\n        state.write(destination, 4, frame.target_y)\n        frame = _movement_test_long(state, frame, frame.target_y)\n        frame = _movement_store_packed_resource(state, frame, 'count', first)\nframe = _movement_move(state, frame, 'target_x', frame.roster.byte(0, 4), 8)\nframe = first_replace(frame, scan=state.table_at(4294964263).cursor())\nframe = _movement_move(state, frame, 'target_y', state.read(4294964114, 2), 16)\nframe = _movement_compare(state, frame, low8(frame.target_x), frame.scan.byte(low16(frame.target_y)), 8)\nowned = bool(frame.status & 4)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964114, 2), 16)\nframe = _movement_fixed_shift_word(state, frame, 'target_x', 1 if owned else 2)\ngold, food = (4294959100, 4294959260) if owned else (4294962564, 4294962724)\nfor base, staged in ((gold, 4294964126), (food, 4294964154)):\n    frame = first_replace(frame, candidates=state.table_at(base).cursor())\n    frame = _movement_move_long(state, frame, 'target_y', frame.candidates.long(low16(frame.target_x)))\n    frame = _movement_arithmetic_long(state, frame, 'target_y', state.read(staged, 4))\n    frame = _first_compare_long(frame, frame.target_y, 999999)\n    state.sr = state.sr & 65504 | frame.status\n    if not frame.status & 5:\n        frame = _movement_move_long(state, frame, 'target_y', 999999)\n    frame.candidates.set_long(low16(frame.target_x), frame.target_y)\n    frame = _movement_test_long(state, frame, frame.target_y)\nreturn frame"}})

DECLARATIONS.update({'remove_deployed_group_members_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 111730)\nframe = _movement_compare(state, frame, low16(frame.choice), state.read(4294964790, 2), 16)\nwhole = bool(frame.status & 4)\nframe = _movement_move(state, frame, 'target_x', frame.roster.byte(), 8)\nframe = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 15, 16)\nframe = first_replace(frame, candidates=frame.roster.advance(s16(low16(frame.target_x)) + 13))\nif not whole:\n    frame = first_replace(frame, controller=state.table_at(frame.roster.base + 13), scan=state.table_at(4294964480).cursor())\n    frame = _movement_move(state, frame, 'target_x', 0, 16)\n    while True:\n        member = frame.scan.word()\n        frame = first_replace(frame, scan=frame.scan.advance(2))\n        frame = _movement_move(state, frame, 'target_y', member, 16)\n        if frame.status & 8:\n            break\n        frame = _deployment_menu_bit(state, frame, frame.target_y, 14)\n        if not frame.status & 4:\n            continue\n        frame.controller.set_byte(0, low8(frame.target_y))\n        frame = first_replace(frame, controller=frame.controller.advance(1))\n        frame = _movement_test(state, frame, low8(frame.target_y), 8)\n        frame = _movement_adjust_word(state, frame, 'target_x', 1)\n    frame = _deployment_menu_bit(state, frame, frame.target_x, 4)\n    frame = first_replace(frame, target_x=frame.target_x | 16)\n    frame.roster.set_byte(0, low8(frame.target_x))\n    frame = _movement_test(state, frame, low8(frame.target_x), 8)\nwhile True:\n    frame = _movement_move(state, frame, 'target_x', frame.candidates.byte(), 8)\n    frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 15, 16)\n    if frame.status & 4:\n        break\n    frame = _movement_add_word(state, frame, 'target_x', 12)\n    while True:\n        copied = frame.candidates.byte()\n        frame = first_replace(frame, candidates=frame.candidates.advance(1))\n        if whole:\n            frame.roster.set_byte(0, copied)\n            frame = first_replace(frame, roster=frame.roster.advance(1))\n        else:\n            frame.controller.set_byte(0, copied)\n            frame = first_replace(frame, controller=frame.controller.advance(1))\n        frame = _movement_test(state, frame, copied, 8)\n        frame = first_replace(frame, target_x=replace_word(frame.target_x, u16(low16(frame.target_x) - 1)))\n        if low16(frame.target_x) == 65535:\n            break\ndestination = frame.roster if whole else frame.controller\ndestination.byte()\ndestination.set_byte(0, 0)\nframe = _movement_test(state, frame, 0, 8)\nif whole:\n    return frame\nreturn _deployment_menu_call_fields(state, frame, 111850, 111810)"}})

DECLARATIONS.update({'refresh_object_attribute_average_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 111850)\nframe = _movement_move(state, frame, 'target_x', frame.roster.byte(), 8)\nframe = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 15, 16)\nframe = _movement_move(state, frame, 'target_y', low16(frame.target_x), 16)\nframe, reduced = _movement_binary_flags(state, frame, low8(frame.target_y), 1, 8, True)\nframe = first_replace(frame, target_y=replace_byte(frame.target_y, reduced), candidates=state.table_at(4294951936).cursor())\nframe = _movement_move_long(state, frame, 'unit', 0)\nframe = _movement_move(state, frame, 'count', 0, 16)\nwhile True:\n    frame = _movement_move(state, frame, 'count', frame.roster.byte(low16(frame.target_y), 13), 8)\n    frame = _movement_add_byte(state, frame, 'unit', frame.candidates.byte(low16(frame.count)))\n    frame = first_replace(frame, target_y=replace_word(frame.target_y, u16(low16(frame.target_y) - 1)))\n    if low16(frame.target_y) == 65535:\n        break\nframe = _movement_divu_word(state, frame, 'unit', low16(frame.target_x), 111882)\nframe.roster.set_byte(0, low8(frame.unit), 3)\nreturn _movement_test(state, frame, low8(frame.unit), 8)"}})

DECLARATIONS.update({'clear_original_tail_coordinate_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 111992)\nframe = first_replace(frame, roster=state.table_at(4294953984).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964874, 2), 16)\nframe = _movement_move(state, frame, 'target_y', 255, 16)\nframe = first_replace(frame, candidates=state.table_at(4294943056).cursor())\nframe = _movement_compare(state, frame, low8(frame.target_x), frame.roster.byte(low16(frame.target_y)), 8)\nif frame.status & 4:\n    frame = _movement_move(state, frame, 'unit', low16(frame.target_y), 16)\n    frame = _movement_fixed_shift_word(state, frame, 'unit', 2)\n    frame.candidates.long(low16(frame.unit))\n    frame.candidates.set_long(low16(frame.unit), 0)\n    frame = _movement_test_long(state, frame, 0)\nreturn first_replace(frame, target_y=replace_word(frame.target_y, 65535))"}})

DECLARATIONS.update({'submit_deployment_queue_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 111890)\nstack = frame.stack_cursor.advance(-4)\nstack.set_long(0, frame.roster.base)\nframe = first_replace(frame, stack_cursor=stack)\nframe = _movement_test_long(state, frame, frame.roster.base)\nframe = _movement_compare(state, frame, state.read(4294964754, 2), 521, 16)\nskip = False\nif frame.status & 4:\n    frame = _movement_compare(state, frame, state.read(4294964066, 2), 5, 16)\n    skip = bool(frame.status & 4)\nif not skip:\n    frame = _movement_move(state, frame, 'target_x', state.read(4294964114, 2), 16)\n    frame = first_replace(frame, candidates=state.table_at(4294961719).cursor())\n    frame = _deployment_menu_bit(state, frame, frame.candidates.byte(low16(frame.target_x)), 1)\n    if frame.status & 4:\n        frame.candidates.set_byte(low16(frame.target_x), 2)\n        frame = _movement_test(state, frame, 2, 8)\n        frame = _movement_move(state, frame, 'target_x', frame.roster.byte(0, 13), 8)\n        frame = first_replace(frame, candidates=state.table_at(16723968).cursor())\n        frame = first_replace(frame, candidates=frame.candidates.advance(s16(state.read(16726054, 2))))\n        for kind in (0, 1, 2, 3, 4, 5):\n            if kind == 0:\n                value = 0\n            elif kind == 1:\n                value = low8(frame.target_x)\n            elif kind == 2:\n                value = frame.roster.byte(0, 3)\n            elif kind == 3:\n                value = 128\n            elif kind == 4:\n                value = state.read(4294964115, 1)\n            else:\n                frame.candidates.byte()\n                value = 0\n            frame.candidates.set_byte(0, value)\n            frame = first_replace(frame, candidates=frame.candidates.advance(1))\n            frame = _movement_test(state, frame, value, 8)\n        frame.candidates.set_byte(0, 255)\n        frame = _movement_test(state, frame, 255, 8)\n        frame, counter = _movement_binary_flags(state, frame, state.read(16726054, 2), 6, 16)\n        state.write(16726054, 2, counter)\n        frame = _deployment_menu_call_fields(state, frame, 111992, 111988)\npointer = frame.stack_cursor.long()\nreturn first_replace(frame, roster=state.table_at(pointer).cursor(), stack_cursor=frame.stack_cursor.advance(4))"}})

