DECLARATIONS.update({'city_process_counted_records_15_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 112030)\nframe = _movement_test(state, frame, state.read(4294964102, 2), 16)\nif not frame.status & 4:\n    return frame\nframe = first_replace(frame, roster=state.table_at(state.read(16726060, 4)).cursor())\nfor target, continuation in ((111202, 112048), (111226, 112052), (111292, 112056), (111730, 112060)):\n    frame = _deployment_menu_call_fields(state, frame, target, continuation)\nfor address, value, source, clear in ((4294965106, 0, None, True), (4294964874, 0, 4294964114, False), (4294944248, 65535, None, False), (4294964754, 1024, None, False), (4294964066, 0, None, True), (4294964050, 0, None, True)):\n    if clear:\n        state.read(address, 2)\n    if source is not None:\n        value = state.read(source, 2)\n    state.write(address, 2, value)\n    frame = _movement_test(state, frame, value, 16)\nframe = _movement_move(state, frame, 'target_x', 31, 16)\nframe = first_replace(frame, roster=state.table_at(4294966016).cursor(), candidates=state.table_at(4294966144).cursor())\nwhile True:\n    copied = frame.roster.word()\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame.candidates.set_word(0, copied)\n    frame = first_replace(frame, candidates=frame.candidates.advance(2))\n    frame = _movement_test(state, frame, copied, 16)\n    frame = first_replace(frame, target_x=replace_word(frame.target_x, u16(low16(frame.target_x) - 1)))\n    if low16(frame.target_x) == 65535:\n        break\nfor address in (4294944080, 4294944164):\n    state.write(address, 2, 65535)\n    frame = _movement_test(state, frame, 65535, 16)\nstate.read(4294964074, 2)\nstate.write(4294964074, 2, 0)\nframe = _movement_test(state, frame, 0, 16)\nreturn _deployment_menu_call_fields(state, frame, 110744, 112130)"}})

