DECLARATIONS.update({'deployment_force_carry_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 112908)\nframe = first_replace(frame, roster=state.table_at(state.read(16726060, 4)).cursor())\nframe = _movement_move(state, frame, 'target_x', frame.roster.byte(0, 4), 8)\nfound = False\nfor address in (4294964859, 4294964861, 4294964863):\n    frame = _movement_compare(state, frame, low8(frame.target_x), state.read(address, 1), 8)\n    if frame.status & 4:\n        found = True\n        break\nif not found:\n    frame = _read_current_deployment_group_fields(state, frame)\n    frame = _movement_move(state, frame, 'target_x', frame.roster.byte(0, 4), 8)\n    for address in (4294964859, 4294964861, 4294964863):\n        frame = _movement_compare(state, frame, low8(frame.target_x), state.read(address, 1), 8)\n        if frame.status & 4:\n            found = True\n            break\nactual_sr = state.read_status_word()\nactual_sr = actual_sr & 65534 if found else actual_sr | 1\nstate.set_status_word(actual_sr)\nreturn first_replace(frame, status=actual_sr & 31)"}})

DECLARATIONS.update({'prepare_battle_mode_header_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 112546)\nframe = first_replace(frame, roster=state.table_at(4294953984).cursor(), candidates=state.table_at(4294964263).cursor())\nframe = _movement_move(state, frame, 'choice', 0, 16)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964210, 2), 16)\nstate.write(4294964994, 2, low16(frame.target_x))\nframe = _movement_test(state, frame, low16(frame.target_x), 16)\nframe = _movement_move(state, frame, 'target_y', frame.roster.byte(low16(frame.target_x)), 8)\nframe = _movement_move(state, frame, 'target_y', low16(frame.target_y) & 63, 16)\nframe = _movement_move(state, frame, 'target_y', frame.candidates.byte(low16(frame.target_y)), 8)\nstate.write(4294964876, 2, low16(frame.target_y))\nframe = _movement_test(state, frame, low16(frame.target_y), 16)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964134, 2), 16)\nstate.write(4294964998, 2, low16(frame.target_x))\nframe = _movement_test(state, frame, low16(frame.target_x), 16)\nframe = _movement_move(state, frame, 'unit', frame.roster.byte(low16(frame.target_x)), 8)\nframe = _movement_move(state, frame, 'unit', low16(frame.unit) & 63, 16)\nframe = _movement_move(state, frame, 'unit', frame.candidates.byte(low16(frame.unit)), 8)\nstate.write(4294964878, 2, low16(frame.unit))\nframe = _movement_test(state, frame, low16(frame.unit), 16)\nframe = _movement_move(state, frame, 'count', 0, 16)\nfor carrier, increment in (('target_y', 8), ('unit', 2)):\n    for address in (4294964859, 4294964861, 4294964863):\n        frame = _movement_compare(state, frame, low8(frame.carrier(carrier)), state.read(address, 1), 8)\n        if frame.status & 4:\n            break\n        frame = _movement_add_word(state, frame, 'count', increment)\nvalue = state.read(u32(112690 + s16(low16(frame.count))), 1)\nstate.write(4294934746, 1, value)\nframe = _movement_test(state, frame, value, 8)\nstate.read(4294934820, 1)\nstate.write(4294934820, 1, 0)\nframe = _movement_test(state, frame, 0, 8)\nvalue = state.read(u32(112691 + s16(low16(frame.count))), 1)\nstate.write(4294934821, 1, value)\nreturn _movement_test(state, frame, value, 8)"}})

DECLARATIONS.update({'prepare_battle_terrain_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 112720)\nframe = _read_current_deployment_group_fields(state, frame)\nframe = _movement_move(state, frame, 'target_x', 0, 16)\nframe = _movement_move(state, frame, 'target_x', frame.roster.byte(0, 1), 8)\nframe = _movement_move(state, frame, 'target_y', low16(frame.target_x), 16)\nframe = _movement_fixed_shift_word(state, frame, 'target_x', 3)\nframe = _movement_add_word(state, frame, 'target_x', low16(frame.target_y))\nframe = _movement_fixed_shift_word(state, frame, 'target_x', 3)\nframe = _movement_move(state, frame, 'target_y', 0, 16)\nframe = _movement_move(state, frame, 'target_y', frame.roster.byte(0, 2), 8)\nframe = _movement_add_word(state, frame, 'target_x', low16(frame.target_y))\nframe = first_replace(frame, roster=state.table_at(976368).cursor())\nframe = _movement_move(state, frame, 'target_y', 0, 16)\nframe = _movement_move(state, frame, 'target_y', frame.roster.byte(low16(frame.target_x)), 8)\nframe = first_replace(frame, roster=state.table_at(112784).cursor())\nterrain = frame.roster.byte(low16(frame.target_y))\nstate.write(4294934747, 1, terrain)\nreturn _movement_test(state, frame, terrain, 8)"}})

DECLARATIONS.update({'choose_battle_order_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 112790)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964134, 2), 16)\nframe = _movement_move(state, frame, 'choice', state.read(4294964210, 2), 16)\nframe = _movement_test(state, frame, state.read(4294934821, 1), 8)\nif not frame.status & 4:\n    frame = first_replace(frame, target_x=frame.choice, choice=frame.target_x)\nreturn frame"}})

DECLARATIONS.update({'maximum_three_live_lookup_attributes_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 129236)\nframe = _movement_move(state, frame, 'target_y', low16(frame.target_x), 16)\nframe = _movement_shift_word(state, frame, 'target_y')\nframe = _movement_add_word(state, frame, 'target_y', low16(frame.target_x))\nframe = first_replace(frame, auxiliary=state.table_at(129296))\nframe = _movement_move(state, frame, 'count', 0, 16)\nframe = _movement_move(state, frame, 'unit', 0, 16)\nframe = _movement_move(state, frame, 'unit', frame.scratch.byte(low16(frame.target_y)), 8)\nframe = _movement_move(state, frame, 'count', frame.auxiliary.byte(low16(frame.unit)), 8)\nfor displacement in (1, 2):\n    frame = first_replace(frame, auxiliary=frame.auxiliary.advance(4))\n    frame = _movement_move(state, frame, 'unit', frame.scratch.byte(low16(frame.target_y), displacement), 8)\n    frame = _movement_compare(state, frame, low8(frame.count), frame.auxiliary.byte(low16(frame.unit)), 8)\n    if frame.status & 1:\n        frame = _movement_move(state, frame, 'count', frame.auxiliary.byte(low16(frame.unit)), 8)\nreturn frame"}})

DECLARATIONS.update({'compact_active_deployment_queue_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 112812)\nframe = _read_current_deployment_group_fields(state, frame)\nframe = _movement_move(state, frame, 'target_x', frame.roster.byte(0, 13), 8)\nframe = first_replace(frame, roster=state.table_at(16723968).cursor())\nwhile True:\n    frame = _movement_test(state, frame, frame.roster.byte(), 8)\n    if frame.status & 8:\n        return frame\n    frame = _movement_compare(state, frame, low8(frame.target_x), frame.roster.byte(0, 1), 8)\n    if frame.status & 4:\n        break\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    while True:\n        value = frame.roster.byte()\n        frame = first_replace(frame, roster=frame.roster.advance(1))\n        frame = _movement_test(state, frame, value, 8)\n        if frame.status & 4:\n            break\nframe = _movement_compare(state, frame, frame.roster.byte(0, 3), 144, 8)\nif not frame.status & 4:\n    return frame\nframe = first_replace(frame, roster=state.table_at(16726450).cursor())\nframe = first_replace(frame, roster=frame.roster.advance(s16(state.read(16726962, 2))))\nwhile True:\n    value = frame.roster.byte()\n    frame = first_replace(frame, roster=frame.roster.advance(1))\n    frame = _movement_test(state, frame, value, 8)\n    if frame.status & 4:\n        return frame\n    value = frame.roster.byte()\n    frame = first_replace(frame, roster=frame.roster.advance(1))\n    frame = _movement_compare(state, frame, low8(frame.target_x), value, 8)\n    if frame.status & 4:\n        break\nwhile True:\n    copied = frame.roster.byte()\n    frame = first_replace(frame, roster=frame.roster.advance(1))\n    frame.roster.advance(-3).set_byte(0, copied)\n    frame = _movement_test(state, frame, copied, 8)\n    if frame.status & 4:\n        return frame\n    copied = frame.roster.byte()\n    frame = first_replace(frame, roster=frame.roster.advance(1))\n    frame.roster.advance(-3).set_byte(0, copied)\n    frame = _movement_test(state, frame, copied, 8)"}})

DECLARATIONS.update({'prepare_both_battle_sides_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 112322)\nframe = _deployment_menu_call_fields(state, frame, 112546, 112326)\nframe = _deployment_menu_call_fields(state, frame, 112720, 112330)\nframe = _deployment_menu_call_fields(state, frame, 112790, 112334)\nframe = first_replace(frame, roster=state.table_at(4294953984).cursor(), candidates=state.table_at(4294964263).cursor(), controller=state.table_at(4294960704))\nfor selected, destination in (('target_x', 4294934748), ('choice', 4294934750)):\n    frame = _movement_move(state, frame, 'target_y', 0, 16)\n    frame = _movement_move(state, frame, 'target_y', frame.roster.byte(low16(frame.carrier(selected))), 8)\n    frame = _movement_move(state, frame, 'target_y', low16(frame.target_y) & 63, 16)\n    frame = _movement_move(state, frame, 'target_y', frame.candidates.byte(low16(frame.target_y)), 8)\n    frame = _movement_shift_word(state, frame, 'target_y')\n    leader = frame.controller.word(low16(frame.target_y))\n    state.write(destination, 2, leader)\n    frame = _movement_test(state, frame, leader, 16)\nframe = first_replace(frame, roster=state.table_at(4294952960).cursor(), candidates=state.table_at(4294952192).cursor(), controller=state.table_at(4294947840), scan=state.table_at(4294947328).cursor(), opponent=state.table_at(4294950912), scratch=state.table_at(4294961800))\nfor side, selected_address, attribute_address, maximum_address, ratio_address, troop_address, award_address, capacity_address, continuation in ((0, 4294934752, 4294934785, 4294934792, 4294934788, 4294934796, 4294934800, 4294934756, 112436), (1, 4294934754, 4294934787, 4294934794, 4294934790, 4294934798, 4294934802, 4294934758, 112498)):\n    if side:\n        frame = _movement_move(state, frame, 'target_x', low16(frame.choice), 16)\n    state.write(selected_address, 2, low16(frame.target_x))\n    frame = _movement_test(state, frame, low16(frame.target_x), 16)\n    attribute = frame.candidates.byte(low16(frame.target_x))\n    state.write(attribute_address, 1, attribute)\n    frame = _movement_test(state, frame, attribute, 8)\n    frame = _deployment_menu_call_fields(state, frame, 129236, continuation)\n    state.write(maximum_address, 2, low16(frame.count))\n    frame = _movement_test(state, frame, low16(frame.count), 16)\n    frame = _movement_shift_word(state, frame, 'target_x')\n    for source, destination in ((frame.controller, ratio_address), (frame.scan, troop_address), (frame.opponent, award_address)):\n        value = source.word(low16(frame.target_x))\n        state.write(destination, 2, value)\n        frame = _movement_test(state, frame, value, 16)\n    frame = _movement_shift_word(state, frame, 'target_x')\n    value = frame.roster.word(low16(frame.target_x), 2)\n    state.write(capacity_address, 2, value)\n    frame = _movement_test(state, frame, value, 16)\nreturn _deployment_menu_call_fields(state, frame, 112812, 112544)"}})

DECLARATIONS.update({'execute_deployment_menu_fields': {'signature': 'state: SceneState, target: int, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, target)\nif target == 111004:\n    return city_coordinate_live_state_84_fields(state, frame)\nif target == 111078:\n    return city_process_counted_records_13_fields(state, frame)\nif target == 111120:\n    return city_process_counted_records_14_fields(state, frame)\nif target == 111174:\n    return deploy_selected_group_fields(state, frame)\nif target == 111202:\n    return count_selected_deployment_fields(state, frame)\nif target == 111226:\n    return initialize_selected_assignment_fields(state, frame)\nif target == 111292:\n    return transfer_selected_group_resources_fields(state, frame)\nif target == 111630:\n    return selected_troop_weights_fields(state, frame)\nif target == 111688:\n    return split_group_resource_share_fields(state, frame)\nif target == 111730:\n    return remove_deployed_group_members_fields(state, frame)\nif target == 111850:\n    return refresh_object_attribute_average_fields(state, frame)\nif target == 111890:\n    return submit_deployment_queue_fields(state, frame)\nif target == 111992:\n    return clear_original_tail_coordinate_fields(state, frame)\nif target == 110744:\n    return city_coordinate_live_state_80_fields(state, frame)\nif target == 112030:\n    return city_process_counted_records_15_fields(state, frame)\nif target == 112132:\n    return city_process_counted_records_16_fields(state, frame)\nif target == 112322:\n    return prepare_both_battle_sides_fields(state, frame)\nif target == 112546:\n    return prepare_battle_mode_header_fields(state, frame)\nif target == 112720:\n    return prepare_battle_terrain_fields(state, frame)\nif target == 112790:\n    return choose_battle_order_fields(state, frame)\nif target == 112812:\n    return compact_active_deployment_queue_fields(state, frame)\nif target == 112908:\n    return deployment_force_carry_fields(state, frame)\nif target == 114656:\n    return city_process_counted_records_16_alternate_1_fields(state, frame)\nif target == 129236:\n    return maximum_three_live_lookup_attributes_fields(state, frame)\nraise MovementContinuationBoundary(target, frame, 'deployment menu target not owned by this family')"}})


# Entire current sole _settlement_add_memory_award_fields function.
DECLARATIONS.update({'_settlement_add_memory_award_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, address: int', 'returns': 'FirstDeploymentFrame', 'flow': 'previous = state.read(address, 2)\nframe, value = _movement_binary_flags(state, frame, previous, low16(frame.target_y), 16)\nstate.write(address, 2, value)\nreturn frame'}})


# Entire current sole _settlement_call_fields function.
DECLARATIONS.update({'_settlement_call_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, target: int, continuation: int', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, target)\nstack = frame.stack_cursor.advance(-4)\nstack.set_long(0, uint(continuation, 32))\nentered = first_replace(frame, stack_cursor=stack)\nstate.sr = state.sr & 65504 | entered.status\nif target == 113052:\n    result = battle_loss_ratio_fields(state, entered)\nelif target == 113110:\n    result = settle_defender_scaled_loss_fields(state, entered)\nelif target == 113538:\n    result = settle_attacker_heavy_loss_fields(state, entered)\nelif target == 113700:\n    result = settle_battle_loss_awards_fields(state, entered)\nelif target == 113766:\n    result = transfer_settlement_attacker_fields(state, entered)\nelif target == 113876:\n    result = transfer_settlement_defender_fields(state, entered)\nelif target == 114388:\n    result = settle_defender_heavy_loss_fields(state, entered)\nelif target == 114536:\n    result = settle_attacker_light_loss_fields(state, entered)\nelif target == 218976:\n    result = signed_divmod_fields(state, entered)\nelif target == 33748:\n    from ..high_level_battle_ai.business_formation import first_deployment_random_fields\n    result = first_deployment_random_fields(BattlePolicyMemory(state), entered)\nelse:\n    raise MovementContinuationBoundary(target, entered, 'settlement member child requires its real full fields and nonlocal return')\nresult = _resource_cost_frame(state, result, target)\nstate.sr = state.sr & 65504 | result.status\nactual = result.stack_cursor.long()\nif actual != continuation:\n    raise FirstDeploymentReturnBoundary(actual, result, continuation)\nreturn first_replace(result, stack_cursor=result.stack_cursor.advance(4))"}})


# Entire current sole _settlement_capacity_loss_fields function.
DECLARATIONS.update({'_settlement_capacity_loss_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, officer_address: int, divisor: int, divide_address: int, award_address: int, award_divide: int', 'returns': 'FirstDeploymentFrame', 'flow': "frame = first_replace(frame, roster=state.table_at(4294952960).cursor())\nframe = _movement_move(state, frame, 'target_y', state.read(officer_address, 2), 16)\nframe = _movement_fixed_shift_word(state, frame, 'target_y', 2)\noffset = low16(frame.target_y)\nframe = _movement_move(state, frame, 'count', frame.roster.word(offset, 2), 16)\nframe = _movement_multiply_word(state, frame, 'target_x', low16(frame.count))\nframe = _movement_divu_word(state, frame, 'target_x', divisor, divide_address)\nframe, remaining = _movement_binary_flags(state, frame, low16(frame.count), low16(frame.target_x), 16, True)\nframe = first_replace(frame, count=replace_word(frame.count, remaining))\nframe = _settlement_store_word_fields(state, frame, frame.roster, offset, remaining, 2)\nframe = _movement_move_long(state, frame, 'target_x', frame.target_x & 65535)\nframe = _movement_divu_word(state, frame, 'target_x', 100, award_divide)\nreturn _settlement_store_word_fields(state, frame, state.table_at(award_address), 0, low16(frame.target_x))"}})


# Entire current sole _settlement_heavy_removal_fields function.
DECLARATIONS.update({'_settlement_heavy_removal_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, attacker: bool', 'returns': 'FirstDeploymentFrame', 'flow': "selector, remaining = ('target_y', 'count') if attacker else ('count', 'target_y')\nframe = _movement_compare(state, frame, low16(frame.carrier(remaining)), 10, 16)\nif not frame.status & 5:\n    return frame\nframe = _settlement_store_word_fields(state, frame, frame.roster, low16(frame.carrier(selector)), 0, clear=True)\nif attacker:\n    frame = first_replace(frame, controller=state.table_at(4294938624), scan=state.table_at(4294963134).cursor())\n    frame = _movement_move(state, frame, 'target_x', state.read(4294963142, 2), 16)\n    displacement = frame.scan.word(low16(frame.target_x))\n    frame = first_replace(frame, controller=frame.controller.advance(s16(displacement)))\n    frame = _movement_move(state, frame, 'target_x', state.read(4294964134, 2), 16)\n    frame = _settlement_call_fields(state, frame, 113232, 113694)\n    return _settlement_add_memory_award_fields(state, frame, 4294963130)\nframe = first_replace(frame, controller=state.table_at(state.read(16726060, 4)))\nframe = _movement_move(state, frame, 'target_x', state.read(4294964210, 2), 16)\nframe = _settlement_call_fields(state, frame, 113232, 114530)\nreturn _settlement_add_memory_award_fields(state, frame, 4294963128)"}})


# Entire current sole _settlement_random_rate_fields function.
DECLARATIONS.update({'_settlement_random_rate_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, multiplier: int, base: int=0', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _movement_move_long(state, frame, 'target_x', frame.target_x & 65535)\nif multiplier == 61:\n    frame = _movement_multiply_word(state, frame, 'target_x', 61)\nelse:\n    frame = _movement_move_long(state, frame, 'target_y', frame.target_x)\n    if multiplier == 31:\n        frame = _settlement_shift_sample_long_fields(state, frame, 'target_x', 5)\n        frame = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y, True)\n    elif multiplier == 51:\n        frame = _settlement_shift_sample_long_fields(state, frame, 'target_x', 1)\n        frame = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y)\n        frame = _settlement_shift_sample_long_fields(state, frame, 'target_x', 3)\n        frame = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y)\n        frame = _settlement_shift_sample_long_fields(state, frame, 'target_x', 1)\n        frame = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y)\n    elif multiplier == 60:\n        frame = _settlement_shift_sample_long_fields(state, frame, 'target_x', 6)\n        frame = _settlement_shift_sample_long_fields(state, frame, 'target_y', 2)\n        frame = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y, True)\n    else:\n        raise ValueError('actual settlement random rate required')\nframe = _movement_move_long(state, frame, 'target_x', swap_words(frame.target_x))\nif base:\n    frame = _movement_add_word(state, frame, 'target_x', uint(base, 16))\nreturn frame"}})


# Entire current sole _settlement_shift_sample_long_fields function.
DECLARATIONS.update({'_settlement_shift_sample_long_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, name: str, count: int', 'returns': 'FirstDeploymentFrame', 'flow': "if count in (1, 2):\n    return _special_action_shift_long(state, frame, name, count)\nif count not in (3, 5, 6):\n    raise ValueError('actual settlement sample LONG shift required')\noriginal = frame.carrier(name)\nvalue = u32(original << count)\ncarry = bool(original & 1 << 32 - count)\nstatus = (17 if carry else 0) | (8 if value & 2147483648 else 0) | (4 if value == 0 else 0)\nstate.sr = state.sr & 65504 | status\nreturn first_replace(frame, **{name: value}, status=status)"}})


# Entire current sole _settlement_store_word_fields function.
DECLARATIONS.update({'_settlement_store_word_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, view, offset: int, value, displacement: int=0, clear: bool=False', 'returns': 'FirstDeploymentFrame', 'flow': 'uint(value, 16)\nif clear:\n    view.word(offset, displacement)\nview.set_word(offset, value, displacement)\nreturn _movement_test(state, frame, value, 16)'}})


# Entire current sole _settlement_transfer_gates_fields function.
DECLARATIONS.update({'_settlement_transfer_gates_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, defender: bool', 'returns': 'FirstDeploymentFrame', 'flow': "officer = 4294964210 if defender else 4294964134\nframe = first_replace(frame, roster=state.table_at(4294953984).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(officer, 2), 16)\nframe = _movement_move(state, frame, 'target_x', frame.roster.byte(low16(frame.target_x)), 8)\nframe = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 63, 16)\nframe = first_replace(frame, roster=state.table_at(4294964263).cursor())\nframe = _movement_move(state, frame, 'target_x', frame.roster.byte(low16(frame.target_x)), 8)\nframe = _movement_shift_word(state, frame, 'target_x')\nframe = first_replace(frame, roster=state.table_at(4294960704).cursor())\nframe = _movement_move(state, frame, 'target_x', frame.roster.word(low16(frame.target_x)), 16)\nframe = _movement_compare(state, frame, low16(frame.target_x), state.read(4294964134, 2), 16)\nif frame.status & 4:\n    return frame\noffsets = state.table_at(4294963134)\nif defender:\n    frame = first_replace(frame, roster=state.table_at(4294938624).cursor(), controller=offsets)\n    frame = _movement_move(state, frame, 'target_x', state.read(4294963142, 2), 16)\n    frame = first_replace(frame, roster=frame.roster.advance(s16(frame.controller.word(low16(frame.target_x)))))\n    frame = first_replace(frame, candidates=state.table_at(state.read(16726060, 4)).cursor())\nelse:\n    frame = first_replace(frame, roster=state.table_at(state.read(16726060, 4)).cursor(), candidates=state.table_at(4294938624).cursor(), controller=offsets)\n    frame = _movement_move(state, frame, 'target_x', state.read(4294963142, 2), 16)\n    frame = first_replace(frame, candidates=frame.candidates.advance(s16(frame.controller.word(low16(frame.target_x)))))\nframe = _movement_move(state, frame, 'target_x', frame.roster.byte(), 8)\nframe = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 15, 16)\nframe = _movement_compare(state, frame, low16(frame.target_x), 10, 16)\nif not frame.status & 1:\n    return frame\nframe = first_replace(frame, controller=state.table_at(4294947328))\nframe = _movement_move(state, frame, 'target_y', state.read(officer, 2), 16)\nframe = _movement_shift_word(state, frame, 'target_y')\nframe = _movement_move(state, frame, 'unit', frame.controller.word(low16(frame.target_y)), 16)\nif frame.status & 4:\n    return frame\nframe = _movement_compare(state, frame, low16(frame.unit), 25, 16)\nif not frame.status & 1:\n    return frame\nreturn _settlement_call_fields(state, frame, 113986, 113984 if defender else 113874)"}})


# Entire current sole _settlement_troop_loss_fields function.
DECLARATIONS.update({'_settlement_troop_loss_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, officer_address: int, selector: str, quantity: str, division_address: int, keep_one: bool', 'returns': 'FirstDeploymentFrame', 'flow': "frame = first_replace(frame, roster=state.table_at(4294947328).cursor())\nframe = _movement_move(state, frame, selector, state.read(officer_address, 2), 16)\nframe = _movement_shift_word(state, frame, selector)\noffset = low16(frame.carrier(selector))\nframe = _movement_move(state, frame, quantity, frame.roster.word(offset), 16)\nframe = _movement_multiply_word(state, frame, 'target_x', low16(frame.carrier(quantity)))\nframe = _movement_divu_word(state, frame, 'target_x', 100, division_address)\nframe, remaining = _movement_binary_flags(state, frame, low16(frame.carrier(quantity)), low16(frame.target_x), 16, True)\nframe = first_replace(frame, **{quantity: replace_word(frame.carrier(quantity), remaining)})\nif keep_one and remaining == 0:\n    frame = _movement_move(state, frame, quantity, 1, 16)\nreturn _settlement_store_word_fields(state, frame, frame.roster, offset, low16(frame.carrier(quantity)))"}})


