DECLARATIONS.update({'terrain_cell_query_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 82594)\nstack = frame.stack_cursor.advance(-4)\nstack.set_long(0, frame.target_x)\nframe = first_replace(frame, stack_cursor=stack)\nframe = _movement_test_long(state, frame, frame.target_x)\nframe = _movement_move(state, frame, 'unit', low16(frame.target_x), 16)\nframe = _movement_fixed_shift_word(state, frame, 'unit', 3)\nframe = _movement_add_word(state, frame, 'target_x', low16(frame.unit))\nframe = _movement_fixed_shift_word(state, frame, 'target_x', 3)\nframe = _movement_add_word(state, frame, 'target_x', low16(frame.target_y))\nframe = first_replace(frame, controller=state.table_at(976368))\nframe = _movement_move(state, frame, 'unit', 0, 16)\nframe = _movement_move(state, frame, 'unit', frame.controller.byte(low16(frame.target_x)), 8)\nframe = first_replace(frame, controller=state.table_at(26378))\nframe = _movement_move(state, frame, 'count', 0, 16)\nframe = _movement_move(state, frame, 'count', frame.controller.byte(low16(frame.unit)), 8)\nrestored = frame.stack_cursor.long()\nframe = first_replace(frame, stack_cursor=frame.stack_cursor.advance(4))\nreturn _movement_move_long(state, frame, 'target_x', restored)"}})

DECLARATIONS.update({'settle_group_at_city_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 119740)\npointer = state.read(16726060, 4)\nframe = _movement_test_long(state, frame, pointer)\nif pointer == 0:\n    return frame\nframe = first_replace(frame, roster=state.table_at(state.read(16726060, 4)).cursor())\nframe = _movement_move(state, frame, 'target_x', 0, 16)\nframe = _movement_move(state, frame, 'target_x', frame.roster.byte(0, 1), 8)\nframe = _movement_move(state, frame, 'target_y', 0, 16)\nframe = _movement_move(state, frame, 'target_y', frame.roster.byte(0, 2), 8)\nframe = _deployment_menu_call_fields(state, frame, 82594, 119774)\nframe = _movement_test(state, frame, low8(frame.count), 8)\nif not low8(frame.count) & 128:\n    return frame\nframe = _deployment_menu_call_fields(state, frame, 119820, 119784)\nframe = _movement_move(state, frame, 'target_x', frame.roster.byte(), 8)\nframe = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 15, 16)\nframe = _movement_adjust_word(state, frame, 'target_x', -1)\nframe = first_replace(frame, candidates=state.table_at(4294953984).cursor())\nframe = _movement_move(state, frame, 'target_y', 0, 16)\nwhile True:\n    frame = _movement_move(state, frame, 'target_y', frame.roster.byte(low16(frame.target_x), 13), 8)\n    frame.candidates.set_byte(low16(frame.target_y), low8(frame.count))\n    frame = _movement_test(state, frame, low8(frame.count), 8)\n    remaining = u16(low16(frame.target_x) - 1)\n    frame = first_replace(frame, target_x=replace_word(frame.target_x, remaining))\n    if remaining == 65535:\n        break\nframe = _deployment_menu_call_fields(state, frame, 119884, 119814)\nreturn _deployment_menu_call_fields(state, frame, 119992, 119818)"}})

DECLARATIONS.update({'locate_group_city_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 119820)\nframe = _movement_move(state, frame, 'target_x', 0, 16)\nframe = _movement_move(state, frame, 'target_x', frame.roster.byte(0, 1), 8)\nframe = _movement_fixed_shift_word(state, frame, 'target_x', 4)\nframe = _movement_add_word(state, frame, 'target_x', 8)\nframe = _movement_move(state, frame, 'target_y', 0, 16)\nframe = _movement_move(state, frame, 'target_y', frame.roster.byte(0, 2), 8)\nframe = _movement_fixed_shift_word(state, frame, 'target_y', 4)\nframe = _movement_move(state, frame, 'unit', low16(frame.target_y), 16)\nframe = _special_action_sub_word(state, frame, 'unit', 16)\nframe = first_replace(frame, candidates=state.table_at(871114).cursor())\nframe = _movement_move(state, frame, 'count', 1, 16)\nwhile True:\n    frame = _movement_compare(state, frame, low16(frame.target_x), frame.candidates.word(0, 2), 16)\n    if frame.status & 4:\n        frame = _movement_compare(state, frame, low16(frame.target_y), frame.candidates.word(), 16)\n        if frame.status & 4:\n            return frame\n        frame = _movement_compare(state, frame, low16(frame.unit), frame.candidates.word(0, 2), 16)\n        if frame.status & 4:\n            return frame\n    frame = first_replace(frame, candidates=frame.candidates.advance(4))\n    frame = _movement_adjust_word(state, frame, 'count', 1)"}})

DECLARATIONS.update({'credit_packed_group_resources_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 119884)\nframe = _movement_fixed_shift_word(state, frame, 'count', 2)\nfor first, resource in ((5, 4294959100), (9, 4294959260)):\n    frame = _movement_load_packed_resource(state, frame, 'target_x', first)\n    frame = first_replace(frame, candidates=state.table_at(resource).cursor())\n    frame = _movement_move_long(state, frame, 'target_y', frame.candidates.long(low16(frame.count)))\n    frame = _movement_arithmetic_long(state, frame, 'target_y', frame.target_x)\n    frame = _first_compare_long(frame, frame.target_y, 999999)\n    state.sr = state.sr & 65504 | frame.status\n    if frame.target_y > 999999:\n        frame = _movement_move_long(state, frame, 'target_y', 999999)\n    frame.candidates.set_long(low16(frame.count), frame.target_y)\n    frame = _movement_test_long(state, frame, frame.target_y)\nreturn frame"}})

DECLARATIONS.update({'erase_group_packet_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 119992)\nframe = _movement_move(state, frame, 'target_x', frame.roster.byte(), 8)\nframe = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 15, 16)\nframe = first_replace(frame, candidates=frame.roster.at(low16(frame.target_x), 13).cursor())\nframe = _movement_move(state, frame, 'target_x', frame.candidates.byte(), 8)\nframe = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 15, 16)\nif low16(frame.target_x):\n    frame = _movement_add_word(state, frame, 'target_x', 12)\n    while True:\n        value = frame.candidates.byte()\n        frame = first_replace(frame, candidates=frame.candidates.advance(1))\n        frame.roster.set_byte(0, value)\n        frame = first_replace(frame, roster=frame.roster.advance(1))\n        frame = _movement_test(state, frame, value, 8)\n        remaining = u16(low16(frame.target_x) - 1)\n        frame = first_replace(frame, target_x=replace_word(frame.target_x, remaining))\n        if remaining == 65535:\n            break\nframe.roster.byte()\nframe.roster.set_byte(0, 0)\nreturn _movement_test(state, frame, 0, 8)"}})

DECLARATIONS.update({'adjust_battle_losing_loyalty_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 120026)\nframe = sample_battle_action_random_fields(BattlePolicyMemory(state), frame, 120032)\nframe = _movement_move_long(state, frame, 'target_x', frame.target_x & 65535)\nframe = _movement_move_long(state, frame, 'target_y', frame.target_x)\nframe = _special_action_shift_long(state, frame, 'target_x', 1)\nframe = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y)\nframe = _special_action_swap(state, frame, 'target_x')\nframe = _movement_adjust_word(state, frame, 'target_x', 1)\nframe = first_replace(frame, roster=state.table_at(4294952192).cursor())\nframe = _movement_compare(state, frame, state.read(4294934804, 2), 5, 16)\nif frame.status & 4:\n    actor_port = 4294934754\nelse:\n    frame = _movement_compare(state, frame, state.read(4294934804, 2), 4, 16)\n    if not frame.status & 4:\n        return frame\n    actor_port = 4294934752\nframe = _movement_move(state, frame, 'target_y', state.read(actor_port, 2), 16)\nframe = _movement_move(state, frame, 'unit', 0, 16)\nframe = _movement_move(state, frame, 'unit', frame.roster.byte(low16(frame.target_y)), 8)\nframe = _special_action_sub_word(state, frame, 'unit', low16(frame.target_x))\nif frame.status & 1:\n    frame = _movement_move(state, frame, 'unit', 0, 16)\nframe.roster.set_byte(low16(frame.target_y), low8(frame.unit))\nreturn _movement_test(state, frame, low8(frame.unit), 8)"}})

DECLARATIONS.update({'rebuild_city_links_from_primary_roster_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 120130)\nframe = first_replace(frame, roster=state.table_at(4294942800).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964874, 2), 16)\nframe = _movement_move(state, frame, 'target_y', 255, 16)\nwhile True:\n    frame = _movement_move(state, frame, 'unit', frame.roster.byte(low16(frame.target_y)), 8)\n    frame = _movement_move(state, frame, 'unit', low16(frame.unit) & 63, 16)\n    frame = _movement_compare(state, frame, low16(frame.unit), low16(frame.target_x), 16)\n    if frame.status & 4:\n        frame.roster.byte(low16(frame.target_y))\n        frame.roster.set_byte(low16(frame.target_y), 0)\n        frame = _movement_test(state, frame, 0, 8)\n    remaining = u16(low16(frame.target_y) - 1)\n    frame = first_replace(frame, target_y=replace_word(frame.target_y, remaining))\n    if remaining == 65535:\n        break\nframe = first_replace(frame, candidates=state.table_at(4294944080).cursor())\nwhile True:\n    frame = _movement_move(state, frame, 'unit', frame.candidates.word(), 16)\n    frame = first_replace(frame, candidates=frame.candidates.advance(2))\n    if frame.status & 8:\n        return frame\n    frame = _movement_move(state, frame, 'unit', low16(frame.unit) & 255, 16)\n    frame.roster.set_byte(low16(frame.unit), low8(frame.target_x))\n    frame = _movement_test(state, frame, low8(frame.target_x), 8)"}})

DECLARATIONS.update({'initialize_prebattle_head_bytes_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 120186)\nframe = first_replace(frame, roster=state.table_at(4294960704).cursor(), candidates=state.table_at(4294951680).cursor())\nframe = _movement_move(state, frame, 'target_x', 15, 16)\nwhile True:\n    frame = _movement_move(state, frame, 'target_y', frame.roster.word(), 16)\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    if not frame.status & 8:\n        frame.candidates.set_byte(low16(frame.target_y), 100)\n        frame = _movement_test(state, frame, 100, 8)\n    remaining = u16(low16(frame.target_x) - 1)\n    frame = first_replace(frame, target_x=replace_word(frame.target_x, remaining))\n    if remaining == 65535:\n        return frame"}})

DECLARATIONS.update({'classify_duel_object_result_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 120216)\nframe = first_replace(frame, roster=state.table_at(16740432).cursor(), candidates=state.table_at(16740512).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(16740592, 1), 8)\nframe = _movement_move(state, frame, 'target_y', state.read(16740593, 1), 8)\nframe = _movement_move(state, frame, 'unit', state.read(4294934752, 2), 16)\nframe = _movement_compare(state, frame, low16(frame.unit), frame.roster.word(0, 26), 16)\nif not frame.status & 4:\n    frame = first_replace(frame, roster=frame.candidates, candidates=frame.roster, target_x=frame.target_y, target_y=frame.target_x)\nframe = _movement_test(state, frame, frame.roster.word(0, 28), 16)\nif frame.status & 4:\n    outcome = 3\nelse:\n    frame = _movement_test(state, frame, frame.candidates.word(0, 28), 16)\n    if frame.status & 4:\n        outcome = 2\n    else:\n        frame = _movement_compare(state, frame, low8(frame.target_x), 1, 8)\n        if frame.status & 4:\n            outcome = 4\n        else:\n            frame = _movement_compare(state, frame, low8(frame.target_y), 1, 8)\n            if frame.status & 4:\n                outcome = 5\n            else:\n                frame = _movement_test(state, frame, low8(frame.target_x), 8)\n                if not frame.status & 4:\n                    outcome = 6\n                else:\n                    frame = _movement_test(state, frame, low8(frame.target_y), 8)\n                    if frame.status & 4:\n                        return frame\n                    outcome = 7\nstate.write(4294934804, 2, outcome)\nreturn _movement_test(state, frame, outcome, 16)"}})

DECLARATIONS.update({'execute_deployment_menu_fields': {'signature': 'state: SceneState, target: int, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, target)\nif target == 111004:\n    return city_coordinate_live_state_84_fields(state, frame)\nif target == 111078:\n    return city_process_counted_records_13_fields(state, frame)\nif target == 111120:\n    return city_process_counted_records_14_fields(state, frame)\nif target == 111174:\n    return deploy_selected_group_fields(state, frame)\nif target == 111202:\n    return count_selected_deployment_fields(state, frame)\nif target == 111226:\n    return initialize_selected_assignment_fields(state, frame)\nif target == 111292:\n    return transfer_selected_group_resources_fields(state, frame)\nif target == 111630:\n    return selected_troop_weights_fields(state, frame)\nif target == 111688:\n    return split_group_resource_share_fields(state, frame)\nif target == 111730:\n    return remove_deployed_group_members_fields(state, frame)\nif target == 111850:\n    return refresh_object_attribute_average_fields(state, frame)\nif target == 111890:\n    return submit_deployment_queue_fields(state, frame)\nif target == 111992:\n    return clear_original_tail_coordinate_fields(state, frame)\nif target == 110744:\n    return city_coordinate_live_state_80_fields(state, frame)\nif target == 112030:\n    return city_process_counted_records_15_fields(state, frame)\nif target == 112132:\n    return city_process_counted_records_16_fields(state, frame)\nif target == 112322:\n    return prepare_both_battle_sides_fields(state, frame)\nif target == 112546:\n    return prepare_battle_mode_header_fields(state, frame)\nif target == 112720:\n    return prepare_battle_terrain_fields(state, frame)\nif target == 112790:\n    return choose_battle_order_fields(state, frame)\nif target == 112812:\n    return compact_active_deployment_queue_fields(state, frame)\nif target == 112908:\n    return deployment_force_carry_fields(state, frame)\nif target == 114656:\n    return city_process_counted_records_16_alternate_1_fields(state, frame)\nif target == 129236:\n    return maximum_three_live_lookup_attributes_fields(state, frame)\nif target == 113000:\n    return settle_complete_battle_fields(state, frame)\nif target == 199284:\n    from ..high_level_gameplay_flow.contexts_services import SceneRefreshMemory\n    from ..high_level_gameplay_flow.business_services import present_gameplay_message_fields\n    return present_gameplay_message_fields(SceneRefreshMemory(state), frame)\nif target == 82594:\n    return terrain_cell_query_fields(state, frame)\nif target == 119740:\n    return settle_group_at_city_fields(state, frame)\nif target == 119820:\n    return locate_group_city_fields(state, frame)\nif target == 119884:\n    return credit_packed_group_resources_fields(state, frame)\nif target == 119992:\n    return erase_group_packet_fields(state, frame)\nif target == 120026:\n    return adjust_battle_losing_loyalty_fields(state, frame)\nif target == 120130:\n    return rebuild_city_links_from_primary_roster_fields(state, frame)\nif target == 120186:\n    return initialize_prebattle_head_bytes_fields(state, frame)\nif target == 120216:\n    return classify_duel_object_result_fields(state, frame)\nraise MovementContinuationBoundary(target, frame, 'deployment menu target not owned by this family')"}})


# Entire current sole _settlement_average_member_attributes_fields function.
DECLARATIONS.update({'_settlement_average_member_attributes_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, source: bool, initialize_attributes: bool, divide_address: int', 'returns': 'FirstDeploymentFrame', 'flow': "packet = frame.candidates if source else frame.roster\nframe = _movement_move(state, frame, 'target_x', packet.byte(), 8)\nframe = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 15, 16)\nif initialize_attributes:\n    frame = first_replace(frame, controller=state.table_at(4294951936))\nframe = _movement_move(state, frame, 'target_y', low16(frame.target_x), 16)\nframe = _movement_adjust_word(state, frame, 'target_y', -1)\nframe = _movement_move(state, frame, 'unit', 0, 16)\nframe = _movement_move(state, frame, 'count', 0, 16)\nwhile True:\n    frame = _movement_move(state, frame, 'unit', packet.byte(low16(frame.target_y), 13), 8)\n    frame = _movement_move(state, frame, 'unit', frame.controller.byte(low16(frame.unit)), 8)\n    frame = _movement_add_word(state, frame, 'count', low16(frame.unit))\n    frame = first_replace(frame, target_y=replace_word(frame.target_y, u16(low16(frame.target_y) - 1)))\n    if low16(frame.target_y) == 65535:\n        break\nframe = _movement_move_long(state, frame, 'count', frame.count & 65535)\nframe = _movement_divu_word(state, frame, 'count', low16(frame.target_x), divide_address)\nreturn _settlement_write_byte_fields(state, frame, packet, low8(frame.count), displacement=3)"}})


# Entire current sole _settlement_call_fields function.
DECLARATIONS.update({'_settlement_call_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, target: int, continuation: int', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, target)\nstack = frame.stack_cursor.advance(-4)\nstack.set_long(0, uint(continuation, 32))\nentered = first_replace(frame, stack_cursor=stack)\nstate.sr = state.sr & 65504 | entered.status\nfrom .contexts_city import SettlementNonlocalReturn\ntry:\n    if target == 113052:\n        result = battle_loss_ratio_fields(state, entered)\n    elif target == 113110:\n        result = settle_defender_scaled_loss_fields(state, entered)\n    elif target == 113538:\n        result = settle_attacker_heavy_loss_fields(state, entered)\n    elif target == 113700:\n        result = settle_battle_loss_awards_fields(state, entered)\n    elif target == 113766:\n        result = transfer_settlement_attacker_fields(state, entered)\n    elif target == 113876:\n        result = transfer_settlement_defender_fields(state, entered)\n    elif target == 114388:\n        result = settle_defender_heavy_loss_fields(state, entered)\n    elif target == 114536:\n        result = settle_attacker_light_loss_fields(state, entered)\n    elif target == 113232:\n        result = remove_settlement_member_fields(state, entered)\n    elif target == 113436:\n        result = finish_settlement_removal_fields(state, entered)\n    elif target == 113986:\n        result = transfer_settlement_members_fields(state, entered)\n    elif target == 114274:\n        result = synchronize_settlement_member_queues_fields(state, entered)\n    elif target == 218976:\n        result = signed_divmod_fields(state, entered)\n    elif target == 33748:\n        from ..high_level_battle_ai.business_formation import first_deployment_random_fields\n        result = first_deployment_random_fields(BattlePolicyMemory(state), entered)\n    else:\n        raise MovementContinuationBoundary(target, entered, 'settlement member child requires its real full fields and nonlocal return')\nexcept SettlementNonlocalReturn as completed:\n    if completed.continuation != continuation:\n        raise\n    result = _resource_cost_frame(state, completed.context, target)\n    state.sr = state.sr & 65504 | result.status\n    return result\nresult = _resource_cost_frame(state, result, target)\nstate.sr = state.sr & 65504 | result.status\nactual = result.stack_cursor.long()\nif actual != continuation:\n    raise FirstDeploymentReturnBoundary(actual, result, continuation)\nreturn first_replace(result, stack_cursor=result.stack_cursor.advance(4))"}})


# Entire current sole _settlement_change_header_byte_fields function.
DECLARATIONS.update({'_settlement_change_header_byte_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, view, decrement: bool', 'returns': 'FirstDeploymentFrame', 'flow': 'previous = view.byte()\nframe, value = _movement_binary_flags(state, frame, previous, 1, 8, decrement)\nview.set_byte(0, value)\nreturn frame'}})


# Entire current sole _settlement_compact_pair_member_fields function.
DECLARATIONS.update({'_settlement_compact_pair_member_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': 'while True:\n    for first in (True, False):\n        value = frame.roster.byte()\n        frame = first_replace(frame, roster=frame.roster.advance(1))\n        frame = _settlement_write_byte_fields(state, frame, frame.roster, value, displacement=-3)\n        if first and value == 0:\n            return frame'}})


# Entire current sole _settlement_detach_transferred_member_fields function.
DECLARATIONS.update({'_settlement_detach_transferred_member_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "source = frame.candidates\nframe = _movement_move(state, frame, 'choice', 0, 16)\nframe = _settlement_store_word_fields(state, frame, state.table_at(4294965062), 0, 0, clear=True)\nframe = _settlement_write_byte_fields(state, frame, state.table_at(4294965063), source.byte(0, 13))\nframe = _movement_move(state, frame, 'unit', source.byte(), 8)\nframe = _movement_move(state, frame, 'unit', low16(frame.unit) & 15, 16)\nframe = _movement_compare(state, frame, low16(frame.unit), 1, 16)\nif not frame.status & 4:\n    frame = _movement_move(state, frame, 'count', 0, 16)\n    while True:\n        frame = _movement_adjust_word(state, frame, 'unit', -1)\n        frame = _movement_compare(state, frame, low8(frame.target_y), source.byte(low16(frame.count), 13), 8)\n        if frame.status & 4:\n            break\n        frame = _movement_adjust_word(state, frame, 'count', 1)\n    while True:\n        frame = _movement_adjust_word(state, frame, 'unit', -1)\n        if frame.status & 8:\n            break\n        frame = _settlement_write_byte_fields(state, frame, source, source.byte(low16(frame.count), 14), low16(frame.count), 13)\n    frame = _settlement_store_word_fields(state, frame, state.table_at(4294965060), 0, 0, clear=True)\n    frame = _settlement_write_byte_fields(state, frame, state.table_at(4294965061), source.byte(0, 13))\n    frame = _movement_move(state, frame, 'unit', source.byte(), 8)\n    frame = _movement_move(state, frame, 'unit', low16(frame.unit) & 15, 16)\n    offset = s16(low16(frame.unit))\n    frame = first_replace(frame, controller=source.advance(offset + 13), scan=source.advance(offset + 12))\n    frame = _settlement_change_header_byte_fields(state, frame, source, True)\nelse:\n    frame = first_replace(frame, controller=source.advance(s16(low16(frame.unit)) + 13), scan=source.cursor())\n    frame = _movement_move(state, frame, 'choice', 1, 16)\n    frame = _settlement_store_word_fields(state, frame, state.table_at(4294965060), 0, 65535)\nreturn frame"}})


# Entire current sole _settlement_insert_transferred_member_fields function.
DECLARATIONS.update({'_settlement_insert_transferred_member_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _movement_fixed_shift_word(state, frame, 'target_y', 1, True)\nframe = first_replace(frame, controller=frame.roster.advance(s16(low16(frame.target_x)) + 13))\nframe = _movement_move(state, frame, 'unit', frame.controller.byte(), 8)\nwhile True:\n    frame = _movement_move(state, frame, 'count', low16(frame.unit), 16)\n    frame = _movement_move(state, frame, 'count', low16(frame.count) & 15, 16)\n    if frame.status & 4:\n        break\n    frame = _movement_add_word(state, frame, 'count', 12)\n    while True:\n        frame = _movement_move(state, frame, 'distance', frame.controller.byte(0, 1), 8)\n        frame = _settlement_write_byte_fields(state, frame, frame.controller, low8(frame.unit), displacement=1)\n        frame = _movement_move(state, frame, 'unit', low8(frame.distance), 8)\n        frame = first_replace(frame, controller=frame.controller.advance(1))\n        frame = first_replace(frame, count=replace_word(frame.count, u16(low16(frame.count) - 1)))\n        if low16(frame.count) == 65535:\n            break\nframe = _settlement_write_byte_fields(state, frame, frame.controller, 0, displacement=1, clear=True)\nframe = _settlement_write_byte_fields(state, frame, frame.roster, low8(frame.target_y), low16(frame.target_x), 13)\nframe = _settlement_change_header_byte_fields(state, frame, frame.roster, False)\nframe = _first_compare_long(frame, frame.candidates.base, frame.roster.base)\nstate.sr = state.sr & 65504 | frame.status\nif not frame.status & 1:\n    source = frame.candidates.base\n    frame, low_pointer = _movement_binary_flags(state, frame, low16(source), 1, 16)\n    frame = first_replace(frame, candidates=state.table_at(replace_word(source, low_pointer)).cursor())\nreturn frame"}})


# Entire current sole _settlement_relabel_active_member_fields function.
DECLARATIONS.update({'_settlement_relabel_active_member_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, replacement: int, skip_negative: bool', 'returns': 'FirstDeploymentFrame', 'flow': 'while True:\n    header = frame.roster.byte()\n    frame = first_replace(frame, roster=frame.roster.advance(1))\n    frame = _movement_test(state, frame, header, 8)\n    if header & 128:\n        if skip_negative:\n            continue\n        return frame\n    member = frame.roster.byte()\n    frame = first_replace(frame, roster=frame.roster.advance(1))\n    frame = _movement_compare(state, frame, low8(frame.target_x), member, 8)\n    if frame.status & 4:\n        return _settlement_write_byte_fields(state, frame, frame.roster, state.read(replacement, 1), displacement=-1)\n    while True:\n        token = frame.roster.byte()\n        frame = first_replace(frame, roster=frame.roster.advance(1))\n        frame = _movement_test(state, frame, token, 8)\n        if token == 0:\n            break'}})


# Entire current sole _settlement_seek_pair_member_fields function.
DECLARATIONS.update({'_settlement_seek_pair_member_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'tuple', 'flow': 'while True:\n    token = frame.roster.byte()\n    frame = first_replace(frame, roster=frame.roster.advance(1))\n    frame = _movement_test(state, frame, token, 8)\n    if token == 0:\n        return (frame, False)\n    member = frame.roster.byte()\n    frame = first_replace(frame, roster=frame.roster.advance(1))\n    frame = _movement_compare(state, frame, low8(frame.target_x), member, 8)\n    if frame.status & 4:\n        return (frame, True)'}})


# Entire current sole _settlement_slide_member_tail_fields function.
DECLARATIONS.update({'_settlement_slide_member_tail_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, source_name: str, destination_name: str', 'returns': 'FirstDeploymentFrame', 'flow': "while True:\n    source = frame.scan if source_name == 'scan' else frame.controller\n    frame = _movement_move(state, frame, 'unit', source.byte(), 8)\n    frame = _movement_move(state, frame, 'unit', low16(frame.unit) & 15, 16)\n    if frame.status & 4:\n        break\n    frame = _movement_add_word(state, frame, 'unit', 12)\n    while True:\n        source = frame.scan if source_name == 'scan' else frame.controller\n        destination = frame.scan if destination_name == 'scan' else frame.controller\n        value = source.byte()\n        frame = first_replace(frame, **{source_name: source.advance(1)})\n        destination.set_byte(0, value)\n        frame = first_replace(frame, **{destination_name: destination.advance(1)})\n        frame = _movement_test(state, frame, value, 8)\n        frame = first_replace(frame, unit=replace_word(frame.unit, u16(low16(frame.unit) - 1)))\n        if low16(frame.unit) == 65535:\n            break\ndestination = frame.scan if destination_name == 'scan' else frame.controller\nreturn _settlement_write_byte_fields(state, frame, destination, 0, clear=True)"}})


# Entire current sole _settlement_write_byte_fields function.
DECLARATIONS.update({'_settlement_write_byte_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, view, value, offset: int=0, displacement: int=0, clear: bool=False', 'returns': 'FirstDeploymentFrame', 'flow': 'uint(value, 8)\nif clear:\n    view.byte(offset, displacement)\nview.set_byte(offset, value, displacement)\nreturn _movement_test(state, frame, value, 8)'}})


# Entire current sole finish_settlement_removal_fields function.
DECLARATIONS.update({'finish_settlement_removal_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "from .services import _movement_restore_longs\nfrom .contexts_city import SettlementNonlocalReturn\nframe = _resource_cost_frame(state, frame, 113436)\nframe = _movement_move(state, frame, 'target_x', state.read(4294965060, 2), 16)\nframe = first_replace(frame, roster=state.table_at(16726450).cursor())\nframe = first_replace(frame, roster=frame.roster.advance(s16(state.read(16726962, 2))))\nframe = _movement_test(state, frame, state.read(4294965062, 2), 16)\nremoved_packet = bool(frame.status & 8)\nframe, found = _settlement_seek_pair_member_fields(state, frame)\nif found:\n    if removed_packet:\n        frame = _settlement_compact_pair_member_fields(state, frame)\n    else:\n        frame = _settlement_write_byte_fields(state, frame, frame.roster, state.read(4294965063, 1), displacement=-1)\n        frame = first_replace(frame, roster=state.table_at(16723968).cursor())\n        frame = _settlement_relabel_active_member_fields(state, frame, 4294965063, True)\nframe = _movement_restore_longs(state, frame, ('target_x', 'roster'))\ncontinuation = frame.stack_cursor.long()\nframe = first_replace(frame, stack_cursor=frame.stack_cursor.advance(4))\nframe = _resource_cost_frame(state, frame, 113536)\nstate.sr = state.sr & 65504 | frame.status\nraise SettlementNonlocalReturn(continuation, frame)"}})


# Entire current sole remove_settlement_member_fields function.
DECLARATIONS.update({'remove_settlement_member_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 113232)\nframe = _settlement_store_word_fields(state, frame, state.table_at(4294965060), 0, low16(frame.target_x))\nframe = first_replace(frame, roster=state.table_at(4294950912).cursor(), candidates=state.table_at(4294953984).cursor())\nframe = _movement_move(state, frame, 'count', frame.candidates.byte(low16(frame.target_x)), 8)\nframe = _settlement_write_byte_fields(state, frame, frame.candidates, 255, low16(frame.target_x))\nframe = _movement_shift_word(state, frame, 'target_x')\nframe = _movement_move(state, frame, 'target_y', frame.roster.word(low16(frame.target_x)), 16)\nframe = _movement_move_long(state, frame, 'target_y', frame.target_y & 65535)\nframe = _movement_divu_word(state, frame, 'target_y', 5, 113266)\nframe = _movement_fixed_shift_word(state, frame, 'target_x', 1, True)\nframe = first_replace(frame, roster=state.table_at(4294964263).cursor())\nframe = _movement_move(state, frame, 'count', frame.roster.byte(low16(frame.count)), 8)\nframe = _movement_move(state, frame, 'count', low16(frame.count) & 255, 16)\nframe = _movement_shift_word(state, frame, 'count')\nframe = first_replace(frame, roster=state.table_at(4294960704).cursor())\nframe = _movement_compare(state, frame, low16(frame.target_x), frame.roster.word(low16(frame.count)), 16)\nif frame.status & 4:\n    frame = _movement_add_word(state, frame, 'target_y', 30)\nframe = first_replace(frame, roster=state.table_at(4294952704).cursor())\nframe = _deployment_menu_bit(state, frame, frame.roster.byte(low16(frame.target_x)), 4)\nif not frame.status & 4:\n    frame = _movement_add_word(state, frame, 'target_y', 20)\npacket = frame.controller\nframe = _movement_move(state, frame, 'unit', packet.byte(), 8)\nframe = _movement_move(state, frame, 'unit', low8(frame.unit) & 15, 8)\nframe = _movement_compare(state, frame, low16(frame.unit), 1, 16)\nif not frame.status & 4:\n    frame = _movement_move(state, frame, 'count', 0, 16)\n    while True:\n        frame = _movement_adjust_word(state, frame, 'unit', -1)\n        frame = _movement_compare(state, frame, low8(frame.target_x), packet.byte(low16(frame.count), 13), 8)\n        if frame.status & 4:\n            break\n        frame = _movement_adjust_word(state, frame, 'count', 1)\n    while True:\n        frame = _movement_adjust_word(state, frame, 'unit', -1)\n        if frame.status & 8:\n            break\n        frame = _settlement_write_byte_fields(state, frame, packet, packet.byte(low16(frame.count), 14), low16(frame.count), 13)\n        frame = _movement_adjust_word(state, frame, 'count', 1)\n    frame = _movement_move(state, frame, 'unit', packet.byte(), 8)\n    frame = _movement_move(state, frame, 'unit', low8(frame.unit) & 15, 8)\n    frame = _settlement_change_header_byte_fields(state, frame, packet, True)\n    frame = _settlement_write_byte_fields(state, frame, state.table_at(4294965062), 0, clear=True)\n    frame = _settlement_write_byte_fields(state, frame, state.table_at(4294965063), packet.byte(0, 13))\n    offset = s16(low16(frame.unit))\n    frame = first_replace(frame, scan=packet.advance(offset + 13).cursor(), controller=packet.advance(offset + 12))\nelse:\n    frame = _settlement_store_word_fields(state, frame, state.table_at(4294965062), 0, 65535)\n    frame = first_replace(frame, scan=packet.advance(s16(low16(frame.unit)) + 13).cursor())\nframe = _settlement_slide_member_tail_fields(state, frame, 'scan', 'controller')\nreturn _settlement_call_fields(state, frame, 113436, 113434)"}})


# Entire current sole synchronize_settlement_member_queues_fields function.
DECLARATIONS.update({'synchronize_settlement_member_queues_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "from .services import _movement_save_longs, _movement_restore_longs\nframe = _resource_cost_frame(state, frame, 114274)\nframe = _movement_save_longs(state, frame, ('target_x', 'roster'))\nframe = _movement_move(state, frame, 'target_x', state.read(4294965062, 2), 16)\nframe = _movement_compare(state, frame, low16(frame.target_x), state.read(4294965060, 2), 16)\nif not frame.status & 4:\n    frame = first_replace(frame, roster=state.table_at(16726450).cursor())\n    frame = first_replace(frame, roster=frame.roster.advance(s16(state.read(16726962, 2))))\n    frame = _movement_test(state, frame, low16(frame.choice), 16)\n    removed_packet = not bool(frame.status & 4)\n    frame, found = _settlement_seek_pair_member_fields(state, frame)\n    if found:\n        if removed_packet:\n            frame = _settlement_compact_pair_member_fields(state, frame)\n        else:\n            frame = _settlement_write_byte_fields(state, frame, frame.roster, state.read(4294965061, 1), displacement=-1)\n            frame = first_replace(frame, roster=state.table_at(16723968).cursor())\n            frame = _settlement_relabel_active_member_fields(state, frame, 4294965061, False)\nreturn _movement_restore_longs(state, frame, ('target_x', 'roster'))"}})


