DECLARATIONS.update({'city_coordinate_live_state_97': {'signature': 'state: SceneState, inputs: CityCoordinateLiveState97Input', 'returns': 'CityCoordinateLiveState97Result', 'flow': "checked_state(state)\nif type(inputs) is not CityCoordinateLiveState97Input:\n    raise ValueError('function-specific historical duel-menu input required')\ninputs.validate(state)\nconditions = int(inputs.carry) | (2 if inputs.overflow else 0) | (4 if inputs.zero else 0) | (8 if inputs.negative else 0)\nstate.sr = state.sr & 65520 | conditions\nframe = first_replace(FirstDeploymentFrame.unobserved(), target_x=inputs.value)\nframe = update_duel_city_selection_fields(state, frame)\nreturn CityCoordinateLiveState97Result(value=frame.target_x, carry=bool(state.sr & 1), zero=bool(state.sr & 4), negative=bool(state.sr & 8), overflow=bool(state.sr & 2)).validate(state)"}})

DECLARATIONS.update({'_duel_menu_write_word_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, address: int, value, clear: bool=False', 'returns': 'FirstDeploymentFrame', 'flow': 'return _settlement_store_word_fields(state, frame, state.table_at(address), 0, value, clear=clear)'}})

DECLARATIONS.update({'_duel_menu_change_word_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, address: int, amount: int', 'returns': 'FirstDeploymentFrame', 'flow': "if address not in (4294964066, 4294964744, 4294954962) or amount not in (-1, 1, 2):\n    raise ValueError('closed duel-menu counter update required')\nold = state.read(address, 2)\nframe, changed = _movement_binary_flags(state, frame, old, -amount if amount < 0 else amount, 16, amount < 0)\nstate.write(address, 2, changed)\nreturn frame"}})

DECLARATIONS.update({'_duel_menu_byte_bit_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, address: int, bit: int, clear: bool=False', 'returns': 'FirstDeploymentFrame', 'flow': "if (address, bit) not in ((4294964739, 4), (4294964739, 5), (4294964001, 3), (4294964951, 1), (4294964132, 6)):\n    raise ValueError('closed duel-menu BYTE flag required')\nvalue = state.read(address, 1)\nstatus = frame.status & 27 | (0 if value & 1 << bit else 4)\nstate.sr = state.sr & 65504 | status\nframe = first_replace(frame, status=status)\nif clear:\n    if (address, bit) != (4294964132, 6):\n        raise ValueError('only original result flag is cleared')\n    state.write(address, 1, value & ~(1 << bit))\nreturn frame"}})

DECLARATIONS.update({'_duel_menu_dispatch_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, city_menu: bool', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _movement_move(state, frame, 'target_x', state.read(4294964066, 2), 16)\nframe = _movement_fixed_shift_word(state, frame, 'target_x', 1)\ntable, base, continuation = (121260, 121278, 121258) if city_menu else (120388, 120408, 120386)\nrelative = state.read(u32(table + s16(low16(frame.target_x))), 2)\nframe = _movement_move(state, frame, 'target_x', relative, 16)\nreturn _deployment_menu_call_fields(state, frame, u32(base + s16(relative)), continuation)"}})

DECLARATIONS.update({'_duel_menu_candidate_roster_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, exclude_committed: bool', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _duel_menu_write_word_fields(state, frame, 4294964106, state.read(4294964754, 2))\nframe = _duel_menu_write_word_fields(state, frame, 4294964144, 1)\nframe = _duel_menu_write_word_fields(state, frame, 4294964754, 1034)\nframe = _duel_menu_write_word_fields(state, frame, 4294964066, 0, True)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964950, 2), 16)\nframe = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 2, 16)\nframe = _movement_fixed_shift_word(state, frame, 'target_x', 1)\npointer_table = 121270 if exclude_committed else 120484\npointer = state.read(u32(pointer_table + s16(low16(frame.target_x))), 4)\nframe = first_replace(frame, roster=state.table_at(pointer).cursor(), candidates=state.table_at(4294944248).cursor(), controller=state.table_at(4294944340 if exclude_committed else 4294944596).cursor(), scan=state.table_at(16727234).cursor())\nwhile True:\n    member = frame.roster.word()\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _movement_move(state, frame, 'target_x', member, 16)\n    if frame.status & 8:\n        break\n    frame = _movement_compare(state, frame, low16(frame.target_x), 256, 16)\n    if not frame.status & 1:\n        continue\n    if exclude_committed:\n        frame = _movement_test(state, frame, frame.controller.byte(low16(frame.target_x)), 8)\n        if not frame.status & 4:\n            continue\n    frame = _movement_test(state, frame, frame.scan.byte(low16(frame.target_x)), 8)\n    if not frame.status & 4:\n        continue\n    frame.candidates.set_word(0, low16(frame.target_x))\n    frame = first_replace(frame, candidates=frame.candidates.advance(2))\n    frame = _movement_test(state, frame, low16(frame.target_x), 16)\nframe.candidates.set_word(0, 65535)\nframe = first_replace(frame, candidates=frame.candidates.advance(2))\nreturn _movement_test(state, frame, 65535, 16)"}})

DECLARATIONS.update({'_duel_menu_request_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, message: int, continuation: int', 'returns': 'FirstDeploymentFrame', 'flow': "if (message, continuation) not in ((272, 120544), (270, 120630), (271, 121034), (261, 121392)):\n    raise ValueError('closed original duel-menu message required')\nframe = _duel_menu_write_word_fields(state, frame, 4294964176, state.read(4294964134, 2))\nframe = _movement_move(state, frame, 'target_x', message, 16)\nframe = _duel_menu_write_word_fields(state, frame, 4294946688, low16(frame.target_x))\nframe = _deployment_menu_call_fields(state, frame, 423666, continuation)\nreturn _duel_menu_write_word_fields(state, frame, 4294964818, 1)"}})

