DECLARATIONS.update({'advance_duel_confirmation_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 120686)\nframe = _deployment_menu_call_fields(state, frame, 120774, 120690)\nframe = _deployment_menu_call_fields(state, frame, 120812, 120694)\nframe = _movement_test(state, frame, state.read(4294954962, 2), 16)\nif not frame.status & 4:\n    frame = _duel_menu_change_word_fields(state, frame, 4294954962, -1)\n    frame = _movement_compare(state, frame, state.read(4294954962, 2), 8, 16)\n    if not frame.status & 5:\n        frame = _duel_menu_write_word_fields(state, frame, 4294954962, 8)\nelse:\n    frame = _duel_menu_byte_bit_fields(state, frame, 4294964739, 5)\n    if not frame.status & 4:\n        frame = _movement_move(state, frame, 'target_x', 172, 16)\n        frame = _deployment_menu_call_fields(state, frame, 32906, 120746)\n        return _duel_menu_change_word_fields(state, frame, 4294964066, 1)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964739, 4)\nif not frame.status & 4:\n    frame = _duel_menu_write_word_fields(state, frame, 4294964948, 1)\n    frame = _duel_menu_change_word_fields(state, frame, 4294964066, 1)\nreturn frame"}})

