DECLARATIONS.update({'draw_duel_confirmation_cursor_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 120812)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964739, 5)\nif not frame.status & 4:\n    return frame\nframe = _movement_move(state, frame, 'target_x', state.read(4294964738, 1), 8)\nframe = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 3, 16)\nif frame.status & 4:\n    frame = _duel_menu_byte_bit_fields(state, frame, 4294964001, 3)\n    if not frame.status & 4:\n        return frame\nframe = first_replace(frame, roster=state.table_at(120878).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964948, 2), 16)\nframe = _movement_move(state, frame, 'target_y', low16(frame.target_x), 16)\nframe = _movement_fixed_shift_word(state, frame, 'target_x', 1)\nframe = _movement_add_word(state, frame, 'target_x', low16(frame.target_y))\nframe = _movement_fixed_shift_word(state, frame, 'target_x', 3)\nframe = _movement_add_word(state, frame, 'target_x', 72)\nframe = _movement_move(state, frame, 'target_y', 136, 16)\nframe = _movement_move(state, frame, 'unit', 0, 16)\nreturn _battle_command_call_fields(state, frame, 44040, 120876)"}})

