DECLARATIONS.update({'test_duel_city_assignment_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 121166)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964874, 2), 16)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964951, 1)\nif frame.status & 4:\n    frame = first_replace(frame, roster=state.table_at(4294942759).cursor())\n    frame = _movement_move(state, frame, 'target_y', 0, 16)\n    frame = _movement_move(state, frame, 'target_y', frame.roster.byte(low16(frame.target_x)), 8)\n    frame = first_replace(frame, roster=state.table_at(4294944080).cursor())\nelse:\n    frame = first_replace(frame, roster=state.table_at(4294964318).cursor())\n    frame = _movement_fixed_shift_word(state, frame, 'target_x', 1)\n    frame = _movement_move(state, frame, 'target_y', frame.roster.word(low16(frame.target_x)), 16)\n    frame = first_replace(frame, roster=state.table_at(4294944164).cursor())\nwhile True:\n    member = frame.roster.word()\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _movement_move(state, frame, 'target_x', member, 16)\n    if frame.status & 8:\n        scene = 1031\n        break\n    frame = _movement_compare(state, frame, low16(frame.target_x), low16(frame.target_y), 16)\n    if frame.status & 4:\n        scene = 1032\n        break\nframe = _duel_menu_write_word_fields(state, frame, 4294964754, scene)\nreturn _duel_menu_write_word_fields(state, frame, 4294964066, 0, True)"}})

