DECLARATIONS.update({'city_select_live_state_31': {'signature': 'state: SceneState, inputs: CitySelectLiveState31Input', 'returns': 'CitySelectLiveState31Result', 'flow': "checked_state(state)\nif type(inputs) is not CitySelectLiveState31Input:\n    raise ValueError('function-specific historical duel-commit input required')\ninputs.validate(state)\nconditions = int(inputs.carry) | (2 if inputs.overflow else 0) | (4 if inputs.zero else 0) | (8 if inputs.negative else 0)\nstate.sr = state.sr & 65520 | conditions\nframe = first_replace(FirstDeploymentFrame.unobserved(), target_x=inputs.value)\nframe = move_duel_menu_cursor_fields(state, frame)\nreturn CitySelectLiveState31Result(value=frame.target_x, carry=bool(state.sr & 1), zero=bool(state.sr & 4), negative=bool(state.sr & 8), overflow=bool(state.sr & 2)).validate(state)"}})

DECLARATIONS.update({'city_coordinate_live_state_126': {'signature': 'state: SceneState, inputs: CityCoordinateLiveState126Input', 'returns': 'CityCoordinateLiveState126Result', 'flow': "checked_state(state)\nif type(inputs) is not CityCoordinateLiveState126Input:\n    raise ValueError('function-specific historical duel-commit input required')\ninputs.validate(state)\nconditions = int(inputs.carry) | (2 if inputs.overflow else 0) | (4 if inputs.zero else 0) | (8 if inputs.negative else 0)\nstate.sr = state.sr & 65520 | conditions\nframe = first_replace(FirstDeploymentFrame.unobserved(), target_x=inputs.value, target_y=inputs.field, unit=inputs.tile, roster=inputs.destination.cursor())\nframe = draw_duel_menu_cursor_fields(state, frame)\nreturn CityCoordinateLiveState126Result(destination=state.table_at(frame.roster.base), value=frame.target_x, field=frame.target_y, tile=frame.unit, carry=bool(state.sr & 1), zero=bool(state.sr & 4), negative=bool(state.sr & 8), overflow=bool(state.sr & 2)).validate(state)"}})

DECLARATIONS.update({'city_coordinate_live_state_99_alternate_1': {'signature': 'state: SceneState, inputs: CityCoordinateLiveState99Alternate1Input', 'returns': 'CityCoordinateLiveState99Alternate1Result', 'flow': "checked_state(state)\nif type(inputs) is not CityCoordinateLiveState99Alternate1Input:\n    raise ValueError('function-specific historical duel-commit input required')\ninputs.validate(state)\nconditions = int(inputs.carry) | (2 if inputs.overflow else 0) | (4 if inputs.zero else 0) | (8 if inputs.negative else 0)\nstate.sr = state.sr & 65520 | conditions\nframe = first_replace(FirstDeploymentFrame.unobserved(), target_x=inputs.value, target_y=inputs.field, unit=inputs.tile, count=inputs.row, distance=inputs.offset, offset_x=inputs.limit, offset_y=inputs.member, choice=inputs.remaining, candidates=inputs.source.cursor(), scratch=inputs.roster.cursor(), stack_cursor=inputs.stack_cursor)\nframe = commit_duel_city_order_alternate_fields(state, frame)\nreturn CityCoordinateLiveState99Alternate1Result(destination=state.table_at(frame.roster.base), source=state.table_at(frame.candidates.base), roster=state.table_at(frame.scratch.base), value=frame.target_x, field=frame.target_y, tile=frame.unit, row=frame.count, offset=frame.distance, limit=frame.offset_x, member=frame.offset_y, remaining=frame.choice, carry=bool(state.sr & 1), zero=bool(state.sr & 4), negative=bool(state.sr & 8), overflow=bool(state.sr & 2)).validate(state)"}})

DECLARATIONS.update({'_duel_commit_shift_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, carrier: str, amount: int, right: bool=False', 'returns': 'FirstDeploymentFrame', 'flow': "if amount not in (1, 2, 3, 7):\n    raise ValueError('closed duel movement shift required')\nif right:\n    frame = _first_right_word(frame, carrier, low16(frame.carrier(carrier)), amount)\nelse:\n    frame = _first_shift_word(frame, carrier, low16(frame.carrier(carrier)), amount)\nstate.sr = state.sr & 65504 | frame.status\nreturn frame"}})

DECLARATIONS.update({'_duel_commit_sub_word_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, carrier: str, source, negate: bool=False', 'returns': 'FirstDeploymentFrame', 'flow': 'value = low16(frame.carrier(carrier))\nframe, result = _movement_binary_flags(state, frame, 0 if negate else value, value if negate else source, 16, True)\nreturn first_replace(frame, **{carrier: replace_word(frame.carrier(carrier), result)})'}})

DECLARATIONS.update({'_duel_commit_bit_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, carrier: str, bit: int, change: int=0', 'returns': 'FirstDeploymentFrame', 'flow': "if (carrier, bit) not in (('target_x', 0), ('target_x', 1), ('target_x', 2), ('target_x', 3), ('distance', 31)):\n    raise ValueError('closed duel LONG bit operation required')\nvalue = frame.carrier(carrier)\nstatus = frame.status & 27 | (0 if value & 1 << bit else 4)\nstate.sr = state.sr & 65504 | status\nframe = first_replace(frame, status=status)\nif change:\n    if carrier != 'distance' or change not in (-1, 1):\n        raise ValueError('only the original bit31 marker is changed')\n    value = value & ~(1 << bit) if change < 0 else value | 1 << bit\n    frame = first_replace(frame, distance=value)\nreturn frame"}})

DECLARATIONS.update({'_duel_vector_sector_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, left: str, right: str, result: str', 'returns': 'FirstDeploymentFrame', 'flow': "if (left, right, result) not in (('count', 'distance', 'target_x'), ('offset_y', 'choice', 'target_y')):\n    raise ValueError('closed duel vector sector layout required')\nframe = _movement_test(state, frame, low16(frame.carrier(left)), 16)\nif not frame.status & 8:\n    frame = _movement_test(state, frame, low16(frame.carrier(right)), 16)\n    if not frame.status & 8:\n        frame = _movement_move(state, frame, result, 1, 16)\n        frame = _movement_compare(state, frame, low16(frame.carrier(left)), low16(frame.carrier(right)), 16)\n        if not frame.status & 1:\n            frame = _movement_adjust_word(state, frame, result, 1)\n    else:\n        frame = _movement_move(state, frame, result, 2, 16)\n        frame = _duel_commit_sub_word_fields(state, frame, right, 0, True)\n        frame = _movement_compare(state, frame, low16(frame.carrier(left)), low16(frame.carrier(right)), 16)\n        if frame.status & 1:\n            frame = _movement_adjust_word(state, frame, result, 1)\nelse:\n    frame = _movement_test(state, frame, low16(frame.carrier(right)), 16)\n    frame = _movement_move(state, frame, result, 0, 16)\n    if not low16(frame.carrier(right)) & 32768:\n        frame = _duel_commit_sub_word_fields(state, frame, left, 0, True)\n        frame = _movement_compare(state, frame, low16(frame.carrier(left)), low16(frame.carrier(right)), 16)\n        if frame.status & 1:\n            frame = _movement_adjust_word(state, frame, result, 1)\n    else:\n        frame = _movement_compare(state, frame, low16(frame.carrier(left)), low16(frame.carrier(right)), 16)\n        if not frame.status & 5:\n            frame = _movement_move(state, frame, result, 3, 16)\nreturn frame"}})

DECLARATIONS.update({'_duel_clear_motion_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame.controller.long(low16(frame.target_x))\nframe.controller.set_long(low16(frame.target_x), 0)\nframe = _movement_test_long(state, frame, 0)\nframe = _duel_commit_shift_fields(state, frame, 'target_x', 2, True)\nframe = _settlement_write_byte_fields(state, frame, frame.scan, 0, low16(frame.target_x), clear=True)\nreturn _duel_commit_shift_fields(state, frame, 'target_x', 2)"}})

DECLARATIONS.update({'_duel_velocity_asr_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, carrier: str, amount: int', 'returns': 'FirstDeploymentFrame', 'flow': "if carrier not in ('offset_x', 'offset_y', 'choice') or amount not in (1, 3, 4):\n    raise ValueError('original duel velocity ASR required')\noriginal = low16(frame.carrier(carrier))\nvalue = u16(s16(original) >> amount)\ncarry = bool(original & 1 << amount - 1)\nstatus = (17 if carry else 0) | (8 if value & 32768 else 0) | (4 if value == 0 else 0)\nstate.sr = state.sr & 65504 | status\nreturn first_replace(frame, **{carrier: replace_word(frame.carrier(carrier), value)}, status=status)"}})

DECLARATIONS.update({'_duel_velocity_fraction_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, extra_shift: int', 'returns': 'FirstDeploymentFrame', 'flow': "if extra_shift not in (3, 4):\n    raise ValueError('original terrain fraction required')\nfor carrier in ('offset_y', 'choice'):\n    frame = _movement_move(state, frame, 'offset_x', low16(frame.carrier(carrier)), 16)\n    frame = _duel_velocity_asr_fields(state, frame, carrier, 1)\n    frame = _duel_velocity_asr_fields(state, frame, 'offset_x', extra_shift)\n    frame = _movement_add_word(state, frame, carrier, low16(frame.offset_x))\nreturn frame"}})

DECLARATIONS.update({'_duel_nearest_border_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, coordinate: str, distance: str, border: str, first: int, second: int, maximum: int', 'returns': 'FirstDeploymentFrame', 'flow': 'frame = _movement_move(state, frame, distance, low16(frame.carrier(coordinate)), 16)\nframe = _duel_commit_sub_word_fields(state, frame, distance, frame.auxiliary.word(0, first))\nif not frame.status & 1:\n    frame = _movement_compare(state, frame, low16(frame.carrier(distance)), maximum, 16)\n    if not frame.status & 5:\n        frame = _movement_move(state, frame, distance, 65535, 16)\n        return frame\n    frame = _movement_compare(state, frame, low16(frame.carrier(distance)), 3968, 16)\n    if frame.status & 5:\n        return _movement_move(state, frame, border, frame.auxiliary.word(0, first), 16)\n    frame = _movement_move(state, frame, border, 7936, 16)\n    frame = _duel_commit_sub_word_fields(state, frame, border, low16(frame.carrier(distance)))\n    frame = _movement_move(state, frame, distance, low16(frame.carrier(border)), 16)\n    return _movement_move(state, frame, border, frame.auxiliary.word(0, second), 16)\nreturn _movement_move(state, frame, distance, 65535, 16)'}})

DECLARATIONS.update({'update_duel_city_order_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 121552)\nframe = _deployment_menu_call_fields(state, frame, 125792, 121556)\nframe = _deployment_menu_call_fields(state, frame, 125942, 121560)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964739, 5)\nif not frame.status & 4:\n    frame = _movement_move(state, frame, 'target_x', 172, 16)\n    frame = _deployment_menu_call_fields(state, frame, 32906, 121580)\n    frame = _duel_menu_write_word_fields(state, frame, 4294944248, 65535)\n    frame = _deployment_menu_call_fields(state, frame, 121636, 121590)\n    frame = _deployment_menu_call_fields(state, frame, 121952, 121594)\n    frame = _duel_menu_write_word_fields(state, frame, 4294964754, 1032)\n    frame = _duel_menu_write_word_fields(state, frame, 4294964066, 0, True)\n    return _duel_menu_write_word_fields(state, frame, 4294964982, 1)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964739, 4)\nif not frame.status & 4:\n    frame = _duel_menu_write_word_fields(state, frame, 4294944248, 65535)\n    frame = _duel_menu_write_word_fields(state, frame, 4294964066, 0, True)\nreturn frame"}})

DECLARATIONS.update({'commit_duel_city_order_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 121636)\nframe = first_replace(frame, scratch=state.table_at(16722944))\nframe = _movement_move(state, frame, 'target_x', state.read(4294964134, 2), 16)\nframe = _duel_commit_shift_fields(state, frame, 'target_x', 2)\nfor source, displacement in ((4294964062, 0), (4294964064, 2)):\n    frame = _movement_move(state, frame, 'unit', state.read(source, 2), 16)\n    frame = _movement_add_word(state, frame, 'unit', 8)\n    frame = _settlement_store_word_fields(state, frame, frame.scratch, low16(frame.target_x), low16(frame.unit), displacement)\nframe = _deployment_menu_call_fields(state, frame, 107576, 121678)\nframe = first_replace(frame, candidates=state.table_at(4294943056).cursor())\nframe = _movement_move(state, frame, 'target_y', frame.candidates.word(low16(frame.target_x)), 16)\nframe = _duel_commit_shift_fields(state, frame, 'target_y', 7, True)\nframe = _movement_move(state, frame, 'unit', frame.candidates.word(low16(frame.target_x), 2), 16)\nframe = _duel_commit_shift_fields(state, frame, 'unit', 7, True)\nframe, terrain = _deployment_terrain_lookup(BattlePolicyMemory(state), frame, low16(frame.target_y), low16(frame.unit), continuation=121700)\nframe = _movement_compare(state, frame, low8(frame.target_x), 6, 8)\nif frame.status & 4:\n    return commit_duel_city_order_alternate_fields(state, frame)\nframe = _movement_move(state, frame, 'choice', state.read(4294964134, 2), 16)\nframe = _deployment_menu_call_fields(state, frame, 122026, 121716)\nreturn _recruitment_carry(state, frame, False)"}})

DECLARATIONS.update({'commit_duel_city_order_alternate_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "from .services import _movement_save_longs, _movement_restore_longs\nframe = _resource_cost_frame(state, frame, 121724)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964874, 2), 16)\nframe = _duel_commit_shift_fields(state, frame, 'target_x', 3)\nframe = first_replace(frame, roster=state.table_at(713138).cursor())\nframe = _movement_move(state, frame, 'offset_x', frame.roster.word(low16(frame.target_x)), 16)\nframe = _movement_add_word(state, frame, 'offset_x', 3968)\nframe = _movement_move(state, frame, 'offset_y', frame.roster.word(low16(frame.target_x), 4), 16)\nframe = _movement_add_word(state, frame, 'offset_y', 3968)\nframe = _movement_save_longs(state, frame, ('offset_x', 'offset_y'))\nframe = _movement_move(state, frame, 'target_y', state.read(4294964134, 2), 16)\nframe = _movement_move(state, frame, 'choice', low16(frame.target_y), 16)\nframe = _duel_commit_shift_fields(state, frame, 'target_y', 2)\nframe = _deployment_menu_call_fields(state, frame, 122042, 121768)\nframe = _movement_restore_longs(state, frame, ('offset_x', 'offset_y'))\nreturn _deployment_menu_call_fields(state, frame, 121778, 121776)"}})

DECLARATIONS.update({'offset_duel_city_anchor_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 121778)\nframe = _duel_vector_sector_fields(state, frame, 'count', 'distance', 'target_x')\nframe = _duel_commit_shift_fields(state, frame, 'target_x', 2)\nframe = first_replace(frame, roster=state.table_at(121856).cursor())\nframe = _movement_add_word(state, frame, 'offset_x', frame.roster.word(low16(frame.target_x)))\nreturn _movement_add_word(state, frame, 'offset_y', frame.roster.word(low16(frame.target_x), 2))"}})

DECLARATIONS.update({'mark_committed_duel_member_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 121952)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964134, 2), 16)\nframe = _movement_move(state, frame, 'target_y', state.read(4294964950, 2), 16)\nframe = _movement_move(state, frame, 'target_y', low16(frame.target_y) & 2, 16)\nframe = _duel_commit_shift_fields(state, frame, 'target_y', 1)\npointer = state.read(u32(121944 + s16(low16(frame.target_y))), 4)\nframe = first_replace(frame, auxiliary=state.table_at(pointer), opponent=state.table_at(4294946344))\nwhile True:\n    member = frame.auxiliary.word()\n    frame = first_replace(frame, auxiliary=frame.auxiliary.advance(2))\n    frame = _movement_move(state, frame, 'target_y', member, 16)\n    frame = _movement_compare(state, frame, low16(frame.target_y), low16(frame.target_x), 16)\n    if frame.status & 4:\n        break\nold = frame.auxiliary.word(0, -2)\nframe = _settlement_store_word_fields(state, frame, frame.auxiliary, 0, old | 16384, -2)\nframe = _settlement_write_byte_fields(state, frame, frame.opponent, 1, low16(frame.target_y))\nframe = first_replace(frame, roster=state.table_at(16726978).cursor())\nreturn _settlement_write_byte_fields(state, frame, frame.roster, 0, low16(frame.target_x), clear=True)"}})

DECLARATIONS.update({'cancel_duel_city_order_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': 'frame = _resource_cost_frame(state, frame, 122004)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964739, 5)\nif not frame.status & 4:\n    frame = _duel_menu_write_word_fields(state, frame, 4294964754, 1032)\n    frame = _duel_menu_write_word_fields(state, frame, 4294964066, 0, True)\nreturn frame'}})

DECLARATIONS.update({'advance_both_duel_motion_rosters_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 122240)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964874, 2), 16)\nframe = _duel_commit_shift_fields(state, frame, 'target_x', 3)\nframe = first_replace(frame, auxiliary=state.table_at(713138).advance(s16(low16(frame.target_x))), candidates=state.table_at(4294943056).cursor(), controller=state.table_at(4294945120), scan=state.table_at(4294946344).cursor(), opponent=state.table_at(16722944))\nframe = _duel_commit_bit_fields(state, frame, 'distance', 31, -1)\nframe = first_replace(frame, roster=state.table_at(4294944080).cursor())\nframe = _deployment_menu_call_fields(state, frame, 122302, 122284)\nframe = _duel_commit_bit_fields(state, frame, 'distance', 31, 1)\nframe = first_replace(frame, roster=state.table_at(4294944164).cursor())\nframe = _deployment_menu_call_fields(state, frame, 122302, 122296)\nreturn _deployment_menu_call_fields(state, frame, 123110, 122300)"}})

DECLARATIONS.update({'step_duel_motion_roster_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 122302)\nframe = _movement_move(state, frame, 'count', 0, 16)\nwhile True:\n    member = frame.roster.word()\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _movement_move(state, frame, 'target_x', member, 16)\n    if frame.status & 8:\n        return frame\n    frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 255, 16)\n    frame = _movement_compare(state, frame, frame.scan.byte(low16(frame.target_x)), 1, 8)\n    if not frame.status & 4:\n        continue\n    frame = first_replace(frame, scratch=state.table_at(4294954670))\n    frame = _movement_test(state, frame, frame.scratch.byte(low16(frame.target_x)), 8)\n    if not frame.status & 4:\n        continue\n    frame = _duel_commit_shift_fields(state, frame, 'target_x', 2)\n    frame = _movement_move(state, frame, 'target_y', frame.candidates.word(low16(frame.target_x)), 16)\n    frame = _movement_move(state, frame, 'unit', frame.candidates.word(low16(frame.target_x), 2), 16)\n    frame = _movement_move(state, frame, 'offset_y', frame.controller.word(low16(frame.target_x)), 16)\n    frame = _movement_move(state, frame, 'choice', frame.controller.word(low16(frame.target_x), 2), 16)\n    frame = _deployment_menu_call_fields(state, frame, 122958, 122354)\n    frame = _movement_compare(state, frame, low16(frame.distance), 6, 16)\n    if frame.status & 4:\n        frame = _deployment_menu_call_fields(state, frame, 122540, 122426)\n        frame = _duel_vector_sector_fields(state, frame, 'offset_y', 'choice', 'target_y')\n        frame = _movement_move(state, frame, 'unit', state.read(4294964874, 2), 16)\n        frame = _duel_commit_shift_fields(state, frame, 'unit', 3)\n        frame = first_replace(frame, scratch=state.table_at(713138))\n        frame = _movement_move(state, frame, 'offset_x', frame.scratch.word(low16(frame.unit)), 16)\n        frame = _movement_add_word(state, frame, 'offset_x', 3968)\n        frame = _movement_move(state, frame, 'offset_y', frame.scratch.word(low16(frame.unit), 4), 16)\n        frame = _movement_add_word(state, frame, 'offset_y', 3968)\n        frame = _duel_commit_shift_fields(state, frame, 'target_y', 2)\n        frame = first_replace(frame, scratch=state.table_at(121856))\n        frame = _movement_add_word(state, frame, 'offset_x', frame.scratch.word(low16(frame.target_y)))\n        frame = _settlement_store_word_fields(state, frame, frame.candidates, low16(frame.target_x), low16(frame.offset_x))\n        frame = _movement_add_word(state, frame, 'offset_y', frame.scratch.word(low16(frame.target_y), 2))\n        frame = _settlement_store_word_fields(state, frame, frame.candidates, low16(frame.target_x), low16(frame.offset_y), 2)\n    else:\n        frame = _movement_add_word(state, frame, 'target_y', low16(frame.offset_y))\n        frame = _movement_compare(state, frame, low16(frame.target_y), 1024, 16)\n        valid = not bool(frame.status & 1)\n        if valid:\n            frame = _movement_compare(state, frame, low16(frame.target_y), 27648, 16)\n            valid = bool(frame.status & 5)\n        if valid:\n            frame = _movement_add_word(state, frame, 'unit', low16(frame.choice))\n            frame = _movement_compare(state, frame, low16(frame.unit), 1024, 16)\n            valid = not bool(frame.status & 1)\n        if valid:\n            frame = _movement_compare(state, frame, low16(frame.unit), 39936, 16)\n            valid = bool(frame.status & 5)\n        if valid:\n            frame = _settlement_store_word_fields(state, frame, frame.candidates, low16(frame.target_x), low16(frame.target_y))\n            frame = _settlement_store_word_fields(state, frame, frame.candidates, low16(frame.target_x), low16(frame.unit), 2)\n            frame = _deployment_menu_call_fields(state, frame, 122656, 122408)\n            if not frame.status & 1:\n                frame = _deployment_menu_call_fields(state, frame, 122588, 122416)\n    frame = _movement_adjust_word(state, frame, 'count', 1)"}})

DECLARATIONS.update({'read_duel_relative_target_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "from .services import _movement_save_longs, _movement_restore_longs\nframe = _resource_cost_frame(state, frame, 122540)\nframe = _movement_save_longs(state, frame, ('target_y', 'roster', 'candidates'))\nframe = first_replace(frame, roster=state.table_at(16722944).cursor(), candidates=state.table_at(713462).cursor())\nframe = _movement_move(state, frame, 'target_y', state.read(4294964874, 2), 16)\nframe = _duel_commit_shift_fields(state, frame, 'target_y', 2)\nfor carrier, displacement in (('offset_y', 0), ('choice', 2)):\n    frame = _movement_move(state, frame, carrier, frame.roster.word(low16(frame.target_x), displacement), 16)\n    frame = _duel_commit_shift_fields(state, frame, carrier, 7)\n    frame = _duel_commit_sub_word_fields(state, frame, carrier, frame.candidates.word(low16(frame.target_y), displacement))\nreturn _movement_restore_longs(state, frame, ('target_y', 'roster', 'candidates'))"}})

DECLARATIONS.update({'snap_duel_arrival_coordinate_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 122588)\nfor carrier, displacement in (('target_y', 0), ('unit', 2)):\n    frame = _duel_commit_shift_fields(state, frame, carrier, 7, True)\n    frame = _duel_commit_sub_word_fields(state, frame, carrier, frame.opponent.word(low16(frame.target_x), displacement))\n    frame = _movement_add_word(state, frame, carrier, 1)\n    frame = _movement_compare(state, frame, low16(frame.carrier(carrier)), 2, 16)\n    if not frame.status & 5:\n        return frame\nfor carrier, displacement in (('target_y', 0), ('unit', 2)):\n    frame = _movement_move(state, frame, carrier, frame.opponent.word(low16(frame.target_x), displacement), 16)\n    frame = _duel_commit_shift_fields(state, frame, carrier, 7)\n    frame = _settlement_store_word_fields(state, frame, frame.candidates, low16(frame.target_x), low16(frame.carrier(carrier)), displacement)\nreturn _duel_clear_motion_fields(state, frame)"}})

DECLARATIONS.update({'test_duel_arrival_rectangle_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 122656)\nfor carrier, first, second in (('target_y', 0, 2), ('unit', 4, 6)):\n    frame = _movement_compare(state, frame, low16(frame.carrier(carrier)), frame.auxiliary.word(0, first), 16)\n    if frame.status & 5:\n        return _recruitment_carry(state, frame, False)\n    frame = _movement_compare(state, frame, low16(frame.carrier(carrier)), frame.auxiliary.word(0, second), 16)\n    if not frame.status & 1:\n        return _recruitment_carry(state, frame, False)\nframe = _deployment_menu_call_fields(state, frame, 122822, 122686)\nframe = _movement_test_long(state, frame, frame.distance)\nif frame.status & 8:\n    frame = _deployment_menu_call_fields(state, frame, 122720, 122694)\nframe = _duel_clear_motion_fields(state, frame)\nreturn _recruitment_carry(state, frame, True)"}})

DECLARATIONS.update({'place_duel_alternate_side_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 122720)\nframe = _movement_move(state, frame, 'distance', frame.auxiliary.word(), 16)\nframe = _movement_add_word(state, frame, 'distance', 2944)\nframe = _movement_move(state, frame, 'offset_y', frame.auxiliary.word(0, 4), 16)\nframe = _movement_add_word(state, frame, 'offset_y', 2944)\nframe = _deployment_menu_call_fields(state, frame, 122776, 122738)\nif frame.status & 1:\n    return frame\nframe = _movement_add_word(state, frame, 'offset_y', 2048)\nframe = _deployment_menu_call_fields(state, frame, 122776, 122750)\nif frame.status & 1:\n    return frame\nframe = _movement_add_word(state, frame, 'distance', 2048)\nframe = _deployment_menu_call_fields(state, frame, 122776, 122762)\nif frame.status & 1:\n    return frame\nframe = _duel_commit_sub_word_fields(state, frame, 'offset_y', 2048)\nreturn _deployment_menu_call_fields(state, frame, 122776, 122774)"}})

DECLARATIONS.update({'test_duel_alternate_corner_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 122776)\nframe = first_replace(frame, scratch=state.table_at(4294944164))\nwhile True:\n    member = frame.scratch.word()\n    frame = first_replace(frame, scratch=frame.scratch.advance(2))\n    frame = _movement_move(state, frame, 'offset_x', member, 16)\n    if frame.status & 8:\n        frame = _settlement_store_word_fields(state, frame, frame.candidates, low16(frame.target_x), low16(frame.distance))\n        frame = _settlement_store_word_fields(state, frame, frame.candidates, low16(frame.target_x), low16(frame.offset_y), 2)\n        return _recruitment_carry(state, frame, True)\n    frame = _duel_commit_shift_fields(state, frame, 'offset_x', 2)\n    frame = _movement_compare(state, frame, low16(frame.distance), frame.candidates.word(low16(frame.offset_x)), 16)\n    if not frame.status & 4:\n        continue\n    frame = _movement_compare(state, frame, low16(frame.offset_y), frame.candidates.word(low16(frame.offset_x), 2), 16)\n    if frame.status & 4:\n        return _recruitment_carry(state, frame, False)"}})

DECLARATIONS.update({'move_duel_to_nearest_border_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "from .services import _movement_save_longs, _movement_restore_longs\nframe = _resource_cost_frame(state, frame, 122822)\nframe = _movement_save_longs(state, frame, ('count', 'distance', 'offset_x', 'offset_y'))\nframe = _duel_nearest_border_fields(state, frame, 'target_y', 'count', 'distance', 0, 2, 12544)\nframe = _duel_nearest_border_fields(state, frame, 'unit', 'offset_x', 'offset_y', 4, 6, 7936)\nframe = _movement_compare(state, frame, low16(frame.offset_x), low16(frame.count), 16)\nif not frame.status & 5:\n    frame = _movement_move(state, frame, 'target_y', low16(frame.distance), 16)\n    frame = _settlement_store_word_fields(state, frame, frame.candidates, low16(frame.target_x), low16(frame.distance))\nelse:\n    frame = _movement_move(state, frame, 'unit', low16(frame.offset_y), 16)\n    frame = _settlement_store_word_fields(state, frame, frame.candidates, low16(frame.target_x), low16(frame.unit), 2)\nreturn _movement_restore_longs(state, frame, ('count', 'distance', 'offset_x', 'offset_y'))"}})

DECLARATIONS.update({'scale_duel_velocity_by_terrain_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 122958)\nstack = frame.stack_cursor.advance(-4)\nstack.set_long(0, frame.distance)\nframe = first_replace(frame, stack_cursor=stack)\nframe = _movement_test_long(state, frame, frame.distance)\nframe = _movement_move(state, frame, 'distance', state.read(4294964874, 2), 16)\nframe = _movement_multiply_word(state, frame, 'distance', 2240)\nframe = first_replace(frame, scratch=state.table_at(u32(607720 + frame.distance)))\nrestored = frame.stack_cursor.long()\nframe = first_replace(frame, stack_cursor=frame.stack_cursor.advance(4))\nframe = _movement_move_long(state, frame, 'distance', restored)\nframe = _movement_move(state, frame, 'distance', low16(frame.target_y), 16)\nframe = _duel_commit_shift_fields(state, frame, 'distance', 7, True)\nframe = _movement_move(state, frame, 'distance', low16(frame.distance) & 248, 16)\nframe = _movement_move(state, frame, 'offset_x', low16(frame.distance), 16)\nframe = _duel_commit_shift_fields(state, frame, 'distance', 2)\nframe = _movement_add_word(state, frame, 'distance', low16(frame.offset_x))\nframe = _movement_move(state, frame, 'offset_x', low16(frame.unit), 16)\nframe = _duel_commit_shift_fields(state, frame, 'offset_x', 7, True)\nframe = _duel_commit_shift_fields(state, frame, 'offset_x', 3, True)\nframe = _movement_add_word(state, frame, 'distance', low16(frame.offset_x))\nframe = _duel_commit_shift_fields(state, frame, 'distance', 1)\nframe = _movement_move(state, frame, 'offset_x', frame.scratch.word(low16(frame.distance)), 16)\nframe = _movement_move(state, frame, 'offset_x', low16(frame.offset_x) & 1023, 16)\nframe = first_replace(frame, scratch=state.table_at(442548))\nframe = _movement_move(state, frame, 'offset_x', frame.scratch.byte(low16(frame.offset_x)), 8)\nframe = _movement_move(state, frame, 'offset_x', low16(frame.offset_x) & 255, 16)\nframe = _movement_move(state, frame, 'distance', low16(frame.offset_x), 16)\nframe = _duel_commit_shift_fields(state, frame, 'offset_x', 1)\nrelative = state.read(u32(123038 + s16(low16(frame.offset_x))), 2)\nframe = _movement_move(state, frame, 'offset_x', relative, 16)\nreturn _deployment_menu_call_fields(state, frame, u32(123054 + s16(relative)), 123036)"}})

DECLARATIONS.update({'preserve_duel_terrain_velocity_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': 'return _resource_cost_frame(state, frame, 123054)'}})

DECLARATIONS.update({'halve_duel_terrain_velocity_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 123056)\nframe = _duel_velocity_asr_fields(state, frame, 'offset_y', 1)\nreturn _duel_velocity_asr_fields(state, frame, 'choice', 1)"}})

