DECLARATIONS.update({'stop_duel_terrain_velocity_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 123098)\nframe = _movement_move(state, frame, 'offset_y', 0, 16)\nreturn _movement_move(state, frame, 'choice', 0, 16)"}})

DECLARATIONS.update({'stop_duel_terrain_velocity_alternate_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': 'frame = _resource_cost_frame(state, frame, 123104)\nreturn stop_duel_terrain_velocity_fields(state, frame)'}})

DECLARATIONS.update({'decrement_duel_member_cooldowns_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 123110)\nframe = first_replace(frame, roster=state.table_at(4294954670).cursor())\nframe = _movement_move(state, frame, 'target_x', 255, 16)\nwhile True:\n    value = frame.roster.byte()\n    frame = first_replace(frame, roster=frame.roster.advance(1))\n    frame = _movement_test(state, frame, value, 8)\n    if not frame.status & 4:\n        old = frame.roster.byte(0, -1)\n        frame, value = _movement_binary_flags(state, frame, old, 1, 8, True)\n        frame.roster.set_byte(0, value, -1)\n    remaining = u16(low16(frame.target_x) - 1)\n    frame = first_replace(frame, target_x=replace_word(frame.target_x, remaining))\n    if remaining == 65535:\n        return frame"}})

DECLARATIONS.update({'initialize_duel_input_word_packets_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 102926)\nframe = first_replace(frame, roster=state.table_at(4294955264).advance(s16(state.read(4294963994, 2))).cursor())\nframe = _movement_move(state, frame, 'target_x', 7, 16)\nframe = _movement_move(state, frame, 'target_y', 49978, 16)\nwhile True:\n    for value in (6, low16(frame.target_y)):\n        frame.roster.set_word(0, value)\n        frame = first_replace(frame, roster=frame.roster.advance(2))\n        frame = _movement_test(state, frame, value, 16)\n    frame = _movement_add_word(state, frame, 'target_y', 128)\n    frame = _movement_move(state, frame, 'unit', 2, 16)\n    while True:\n        frame.roster.long()\n        frame.roster.set_long(0, 0)\n        frame = first_replace(frame, roster=frame.roster.advance(4))\n        frame = _movement_test_long(state, frame, 0)\n        remaining = u16(low16(frame.unit) - 1)\n        frame = first_replace(frame, unit=replace_word(frame.unit, remaining))\n        if remaining == 65535:\n            break\n    remaining = u16(low16(frame.target_x) - 1)\n    frame = first_replace(frame, target_x=replace_word(frame.target_x, remaining))\n    if remaining == 65535:\n        break\nframe = _settlement_store_word_fields(state, frame, frame.roster, 0, 0, clear=True)\nold = state.read(4294963994, 2)\nframe, value = _movement_binary_flags(state, frame, old, 128, 16)\nstate.write(4294963994, 2, value)\nold = state.read(4294964133, 1)\nstatus = frame.status & 27 | (0 if old & 4 else 4)\nstate.sr = state.sr & 65504 | status\nframe = first_replace(frame, status=status)\nstate.write(4294964133, 1, old & 251)\nreturn _duel_menu_write_word_fields(state, frame, 4294964818, 0, True)"}})

DECLARATIONS.update({'switch_duel_selection_command_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': 'frame = _resource_cost_frame(state, frame, 125156)\nframe = _duel_menu_write_word_fields(state, frame, 4294964754, 1028)\nreturn _duel_menu_write_word_fields(state, frame, 4294964074, 0, True)'}})

DECLARATIONS.update({'move_duel_menu_cursor_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 125792)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964738, 1), 8)\nframe = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 15, 16)\nif frame.status & 4:\n    return frame\nfor negative, positive, address, step, maximum in ((0, 1, 4294964062, 2, 208), (2, 3, 4294964064, 3, 304)):\n    frame = _duel_commit_bit_fields(state, frame, 'target_x', negative)\n    if not frame.status & 4:\n        frame = _movement_test(state, frame, state.read(address, 2), 16)\n        if frame.status & 4:\n            continue\n        old = state.read(address, 2)\n        frame, value = _movement_binary_flags(state, frame, old, step, 16, True)\n        state.write(address, 2, value)\n        if frame.status & 1:\n            frame = _duel_menu_write_word_fields(state, frame, address, 0, True)\n    else:\n        frame = _duel_commit_bit_fields(state, frame, 'target_x', positive)\n        if frame.status & 4:\n            continue\n        frame = _movement_compare(state, frame, state.read(address, 2), maximum, 16)\n        if not frame.status & 1:\n            continue\n        old = state.read(address, 2)\n        frame, value = _movement_binary_flags(state, frame, old, step, 16)\n        state.write(address, 2, value)\n        frame = _movement_compare(state, frame, state.read(address, 2), maximum, 16)\n        if not frame.status & 5:\n            frame = _duel_menu_write_word_fields(state, frame, address, maximum)\nreturn frame"}})

DECLARATIONS.update({'draw_duel_menu_cursor_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 125942)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964001, 3)\nif not frame.status & 4:\n    return frame\nframe = _movement_move(state, frame, 'target_x', state.read(4294964062, 2), 16)\nframe = _movement_move(state, frame, 'target_y', state.read(4294964064, 2), 16)\nframe = _movement_move(state, frame, 'unit', 0, 16)\nframe = first_replace(frame, roster=state.table_at(125976).cursor())\nreturn _battle_command_call_fields(state, frame, 44040, 125974)"}})

