DECLARATIONS.update({'_settlement_carry_packet_tail_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, roles: tuple, destination_name: str, displacement: int, copy_width: int', 'returns': 'FirstDeploymentFrame', 'flow': "from ..high_level_main_flows.business_movement_support import _movement_address_carrier\nif (roles, destination_name, displacement, copy_width) not in ((('unit', 'count', 'distance'), 'controller', 1, 16), (('target_y', 'unit', 'count'), 'scan', 0, 8)):\n    raise ValueError('actual original packet insertion roles required')\ncarry_name, count_name, scratch_name = roles\nwhile True:\n    carried = frame.carrier(carry_name)\n    value = low16(carried) if copy_width == 16 else low8(carried)\n    frame = _movement_move(state, frame, count_name, value, copy_width)\n    frame = _movement_move(state, frame, count_name, low16(frame.carrier(count_name)) & 15, 16)\n    if frame.status & 4:\n        break\n    frame = _movement_add_word(state, frame, count_name, 12)\n    while True:\n        destination = _movement_address_carrier(frame, destination_name)\n        frame = _movement_move(state, frame, scratch_name, destination.byte(0, displacement), 8)\n        frame = _settlement_write_byte_fields(state, frame, destination, low8(frame.carrier(carry_name)), displacement=displacement)\n        if displacement == 0:\n            frame = first_replace(frame, **{destination_name: destination.advance(1)})\n        frame = _movement_move(state, frame, carry_name, low8(frame.carrier(scratch_name)), 8)\n        if displacement == 1:\n            frame = first_replace(frame, **{destination_name: destination.advance(1)})\n        frame = first_replace(frame, **{count_name: replace_word(frame.carrier(count_name), u16(low16(frame.carrier(count_name)) - 1))})\n        if low16(frame.carrier(count_name)) == 65535:\n            break\ndestination = _movement_address_carrier(frame, destination_name)\nreturn _settlement_write_byte_fields(state, frame, destination, 0, displacement=displacement, clear=True)"}})

DECLARATIONS.update({'_settlement_insert_transferred_member_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _movement_fixed_shift_word(state, frame, 'target_y', 1, True)\nframe = first_replace(frame, controller=frame.roster.advance(s16(low16(frame.target_x)) + 13))\nframe = _movement_move(state, frame, 'unit', frame.controller.byte(), 8)\nframe = _settlement_carry_packet_tail_fields(state, frame, ('unit', 'count', 'distance'), 'controller', 1, 16)\nframe = _settlement_write_byte_fields(state, frame, frame.roster, low8(frame.target_y), low16(frame.target_x), 13)\nframe = _settlement_change_header_byte_fields(state, frame, frame.roster, False)\nframe = _first_compare_long(frame, frame.candidates.base, frame.roster.base)\nstate.sr = state.sr & 65504 | frame.status\nif not frame.status & 1:\n    source = frame.candidates.base\n    frame, low_pointer = _movement_binary_flags(state, frame, low16(source), 1, 16)\n    frame = first_replace(frame, candidates=state.table_at(replace_word(source, low_pointer)).cursor())\nreturn frame"}})

DECLARATIONS.update({'_settlement_relabel_active_member_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, replacement: int | str, skip_negative: bool | None', 'returns': 'FirstDeploymentFrame', 'flow': "if type(replacement) is str and replacement not in ('distance', 'target_y'):\n    raise ValueError('actual replacement member carrier required')\nif skip_negative not in (True, False, None):\n    raise ValueError('original active-record header policy required')\nwhile True:\n    if skip_negative is not None:\n        header = frame.roster.byte()\n        frame = first_replace(frame, roster=frame.roster.advance(1))\n        frame = _movement_test(state, frame, header, 8)\n        if header & 128:\n            if skip_negative:\n                continue\n            return frame\n        member = frame.roster.byte()\n        frame = first_replace(frame, roster=frame.roster.advance(1))\n        destination_displacement = -1\n    else:\n        member = frame.roster.byte(0, 1)\n        destination_displacement = 1\n    frame = _movement_compare(state, frame, low8(frame.target_x), member, 8)\n    if frame.status & 4:\n        value = low8(frame.carrier(replacement)) if type(replacement) is str else state.read(replacement, 1)\n        return _settlement_write_byte_fields(state, frame, frame.roster, value, displacement=destination_displacement)\n    if skip_negative is None:\n        frame = first_replace(frame, roster=frame.roster.advance(1))\n    while True:\n        token = frame.roster.byte()\n        frame = first_replace(frame, roster=frame.roster.advance(1))\n        frame = _movement_test(state, frame, token, 8)\n        if token == 0:\n            break"}})

