DECLARATIONS.update({'collect_siege_first_side_neighbors_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 123314)\nwhile True:\n    member = frame.roster.word()\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _movement_move(state, frame, 'target_x', member, 16)\n    if frame.status & 8:\n        return frame\n    frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 255, 16)\n    frame = _movement_compare(state, frame, frame.opponent.byte(low16(frame.target_x)), 85, 8)\n    if not frame.status & 1:\n        continue\n    frame = _movement_move(state, frame, 'target_y', low16(frame.target_x), 16)\n    frame = _movement_fixed_shift_word(state, frame, 'target_y', 2)\n    frame = _movement_move(state, frame, 'unit', frame.controller.word(low16(frame.target_y)), 16)\n    frame = _movement_move(state, frame, 'count', low16(frame.unit), 16)\n    frame, lower_x = _movement_binary_flags(state, frame, low16(frame.unit), 2048, 16, True)\n    frame = first_replace(frame, unit=replace_word(frame.unit, lower_x))\n    if frame.status & 1:\n        frame = _movement_move(state, frame, 'unit', 0, 16)\n    frame = _movement_add_word(state, frame, 'count', 2048)\n    frame = _movement_move(state, frame, 'distance', frame.controller.word(low16(frame.target_y), 2), 16)\n    frame = _movement_move(state, frame, 'offset_x', low16(frame.distance), 16)\n    frame, lower_y = _movement_binary_flags(state, frame, low16(frame.distance), 2048, 16, True)\n    frame = first_replace(frame, distance=replace_word(frame.distance, lower_y))\n    if frame.status & 1:\n        frame = _movement_move(state, frame, 'distance', 0, 16)\n    frame = _movement_add_word(state, frame, 'offset_x', 2048)\n    frame = _movement_fixed_shift_word(state, frame, 'target_x', 8)\n    frame = first_replace(frame, scan=state.table_at(4294944164).cursor())\n    frame = _deployment_menu_call_fields(state, frame, 123386, 123382)"}})

DECLARATIONS.update({'collect_siege_second_side_neighbors_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 123386)\nwhile True:\n    member = frame.scan.word()\n    frame = first_replace(frame, scan=frame.scan.advance(2))\n    frame = _movement_move(state, frame, 'target_y', member, 16)\n    if frame.status & 8:\n        return frame\n    frame = _movement_move(state, frame, 'target_y', low16(frame.target_y) & 255, 16)\n    frame = _movement_compare(state, frame, frame.opponent.byte(low16(frame.target_y)), 85, 8)\n    if not frame.status & 1:\n        continue\n    frame = _movement_move(state, frame, 'offset_y', low16(frame.target_y), 16)\n    frame = _movement_fixed_shift_word(state, frame, 'offset_y', 2)\n    frame = _movement_move(state, frame, 'choice', frame.controller.word(low16(frame.offset_y)), 16)\n    frame = _movement_compare(state, frame, low16(frame.choice), low16(frame.unit), 16)\n    if frame.status & 1:\n        continue\n    frame = _movement_compare(state, frame, low16(frame.choice), low16(frame.count), 16)\n    if not frame.status & 1 and (not frame.status & 4):\n        continue\n    frame = _movement_move(state, frame, 'choice', frame.controller.word(low16(frame.offset_y), 2), 16)\n    frame = _movement_compare(state, frame, low16(frame.choice), low16(frame.distance), 16)\n    if frame.status & 1:\n        continue\n    frame = _movement_compare(state, frame, low16(frame.choice), low16(frame.offset_x), 16)\n    if not frame.status & 1 and (not frame.status & 4):\n        continue\n    frame = _movement_move(state, frame, 'target_x', low8(frame.target_y), 8)\n    frame = _settlement_store_word_fields(state, frame, frame.candidates, 0, low16(frame.target_x))\n    frame = first_replace(frame, candidates=frame.candidates.advance(2))"}})

DECLARATIONS.update({'confirm_siege_reserve_action_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 123764)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964738, 1), 8)\nframe = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 48, 16)\nif frame.status & 4:\n    return frame\nframe = _duel_menu_write_word_fields(state, frame, 4294965106, 2)\nframe = _duel_menu_write_word_fields(state, frame, 4294964754, 1031)\nframe = _duel_menu_write_word_fields(state, frame, 4294964066, 3)\nframe = _duel_menu_write_word_fields(state, frame, 4294964050, 0, True)\nreturn _deployment_menu_call_fields(state, frame, 123802, 123800)"}})

DECLARATIONS.update({'dispatch_siege_status_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 123438)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964066, 2), 16)\nframe = _movement_fixed_shift_word(state, frame, 'target_x', 1)\nrelative = state.read(u32(123454 + s16(low16(frame.target_x))), 2)\nframe = _movement_move(state, frame, 'target_x', relative, 16)\nreturn _deployment_menu_call_fields(state, frame, u32(123468 + s16(relative)), 123452)"}})

