DECLARATIONS.update({'mark_siege_first_side_member_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 123802)\nfrom ..high_level_gameplay_flow.business_battle import _postbattle_bit_fields\nframe = first_replace(frame, roster=state.table_at(4294944080).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964210, 2), 16)\nwhile True:\n    member = frame.roster.word()\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _movement_move(state, frame, 'target_y', member, 16)\n    frame = _movement_move(state, frame, 'target_y', low16(frame.target_y) & 255, 16)\n    frame = _movement_compare(state, frame, low16(frame.target_y), low16(frame.target_x), 16)\n    if frame.status & 4:\n        break\nprevious = frame.roster.byte(0, -2)\nframe = _postbattle_bit_fields(frame, bool(previous & 64))\nstate.sr = state.sr & 65504 | frame.status\nframe.roster.set_byte(0, previous | 64, -2)\nreturn frame"}})

DECLARATIONS.update({'mark_siege_selected_roster_member_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 124370)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964950, 2), 16)\nframe = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 2, 16)\nframe = _movement_fixed_shift_word(state, frame, 'target_x', 1)\npointer = state.read(u32(124406 + s16(low16(frame.target_x))), 4)\nframe = first_replace(frame, roster=state.table_at(pointer).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964134, 2), 16)\nframe = _movement_move(state, frame, 'target_y', 0, 16)\nwhile True:\n    frame = _movement_adjust_word(state, frame, 'target_y', 1)\n    member = frame.roster.word()\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _movement_compare(state, frame, low16(frame.target_x), member, 16)\n    if frame.status & 4:\n        break\nprevious = frame.roster.word(0, -2)\nmarked = previous | 16384\nframe.roster.set_word(0, marked, -2)\nframe = _movement_test(state, frame, marked, 16)\nreturn _movement_adjust_word(state, frame, 'target_y', -1)"}})

DECLARATIONS.update({'prepare_siege_reserve_message_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 123866)\nframe = _duel_menu_change_word_fields(state, frame, 4294964066, 1)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964874, 2), 16)\nframe = _movement_fixed_shift_word(state, frame, 'target_x', 2)\nframe = first_replace(frame, roster=state.table_at(4294960540).cursor())\nreserve = frame.roster.long(low16(frame.target_x))\nstate.write(4294964168, 4, reserve)\nfrom ..high_level_main_flows.business_movement_support import _movement_test_long\nframe = _movement_test_long(state, frame, reserve)\nframe = _movement_move(state, frame, 'target_x', 275, 16)\nframe = _duel_menu_write_word_fields(state, frame, 4294946688, low16(frame.target_x))\nframe = _deployment_menu_call_fields(state, frame, 423666, 123900)\nframe = _duel_menu_write_word_fields(state, frame, 4294964134, state.read(4294964210, 2))\nreturn _deployment_menu_call_fields(state, frame, 124370, 123912)"}})

