DECLARATIONS.update({'_engagement_menu_dispatch_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, city_menu: bool', 'returns': 'FirstDeploymentFrame', 'flow': "if type(city_menu) is not bool:\n    raise ValueError('closed secondary/city engagement menu role required')\ntable, base, continuation = (124528, 124560, 124526) if city_menu else (124146, 124152, 124144)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964066, 2), 16)\nframe = _movement_fixed_shift_word(state, frame, 'target_x', 1)\nrelative = state.read(u32(table + s16(low16(frame.target_x))), 2)\nframe = _movement_move(state, frame, 'target_x', relative, 16)\nreturn _deployment_menu_call_fields(state, frame, u32(base + s16(relative)), continuation)"}})

DECLARATIONS.update({'_engagement_relationship_bit_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, carrier: str, selector: str, clear: bool=False', 'returns': 'FirstDeploymentFrame', 'flow': "if (carrier, selector) not in (('unit', 'target_y'), ('unit', 'target_x'), ('distance', 'unit')) or type(clear) is not bool:\n    raise ValueError('closed engagement relationship bit role required')\nvalue = frame.carrier(carrier)\nmask = 1 << (frame.carrier(selector) & 31)\nstatus = frame.status & 27 | (0 if value & mask else 4)\nstate.sr = state.sr & 65504 | status\nreturn first_replace(frame, status=status, **{carrier: value & ~mask if clear else value})"}})

