DECLARATIONS.update({'build_secondary_engagement_roster_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 124152)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964950, 2), 16)\nframe = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 2, 16)\nframe = _movement_fixed_shift_word(state, frame, 'target_x', 1)\naddress = state.read(u32(124262 + s16(low16(frame.target_x))), 4)\nframe = first_replace(frame, roster=state.table_at(address).cursor(), candidates=state.table_at(4294944248).cursor(), controller=state.table_at(4294944340).cursor(), scan=state.table_at(16727234).cursor())\nwhile True:\n    member = frame.roster.word()\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _movement_move(state, frame, 'target_x', member, 16)\n    if member & 32768:\n        break\n    frame = _movement_compare(state, frame, member, 256, 16)\n    if member >= 256:\n        continue\n    assignment = frame.controller.byte(s16(low16(frame.target_x)))\n    frame = _movement_test(state, frame, assignment, 8)\n    if assignment & 128:\n        continue\n    task = frame.scan.byte(s16(low16(frame.target_x)))\n    frame = _movement_test(state, frame, task, 8)\n    if task:\n        continue\n    frame = _settlement_store_word_fields(state, frame, frame.candidates, 0, low16(frame.target_x))\n    frame = first_replace(frame, candidates=frame.candidates.advance(2))\nframe = _settlement_store_word_fields(state, frame, frame.candidates, 0, 65535)\nframe = _duel_menu_write_word_fields(state, frame, 4294964754, 1034)\nframe = _duel_menu_write_word_fields(state, frame, 4294964066, 1)\nframe = _duel_menu_write_word_fields(state, frame, 4294964106, 1036)\nframe = _duel_menu_write_word_fields(state, frame, 4294964144, 1)\nframe = _movement_move(state, frame, 'target_x', 260, 16)\nframe = _duel_menu_write_word_fields(state, frame, 4294946688, low16(frame.target_x))\nframe = _deployment_menu_call_fields(state, frame, 423666, 124248)\nframe = _duel_menu_write_word_fields(state, frame, 4294964062, 104)\nreturn _duel_menu_write_word_fields(state, frame, 4294964064, 152)"}})

DECLARATIONS.update({'confirm_secondary_engagement_member_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 124270)\nselected = state.read(4294964134, 2)\nframe = _movement_test(state, frame, selected, 16)\nif not selected & 32768:\n    frame = _duel_menu_change_word_fields(state, frame, 4294964066, 1)\n    frame = _duel_menu_write_word_fields(state, frame, 4294964176, state.read(4294964134, 2))\n    frame = _movement_move(state, frame, 'target_x', 273, 16)\n    frame = _duel_menu_write_word_fields(state, frame, 4294946688, low16(frame.target_x))\n    frame = _deployment_menu_call_fields(state, frame, 423666, 124302)\n    return _duel_menu_write_word_fields(state, frame, 4294964818, 1)\nframe = _duel_menu_write_word_fields(state, frame, 4294964754, 1032)\nreturn _duel_menu_write_word_fields(state, frame, 4294964066, 0, True)"}})

DECLARATIONS.update({'cancel_secondary_engagement_menu_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': 'frame = _resource_cost_frame(state, frame, 124324)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964739, 5)\nif frame.status & 4:\n    return frame\nframe = _deployment_menu_call_fields(state, frame, 124370, 124338)\nframe = _deployment_menu_call_fields(state, frame, 124414, 124342)\nframe = _deployment_menu_call_fields(state, frame, 124428, 124346)\nframe = _duel_menu_write_word_fields(state, frame, 4294964754, 1032)\nframe = _duel_menu_write_word_fields(state, frame, 4294964066, 0, True)\nframe = _duel_menu_write_word_fields(state, frame, 4294964982, 1)\nreturn _duel_menu_write_word_fields(state, frame, 4294944248, 65535)'}})

DECLARATIONS.update({'clear_selected_member_engagement_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 124414)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964134, 2), 16)\nframe = first_replace(frame, roster=state.table_at(4294946344).cursor())\nreturn _settlement_write_byte_fields(state, frame, frame.roster, 0, s16(low16(frame.target_x)), clear=True)"}})

DECLARATIONS.update({'mark_weak_member_on_defensive_terrain_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 124428)\nframe = _deployment_menu_call_fields(state, frame, 107576, 124434)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964134, 2), 16)\nframe = _movement_fixed_shift_word(state, frame, 'target_x', 2)\nframe = first_replace(frame, candidates=state.table_at(4294952960).cursor())\nstrength = frame.candidates.long(s16(low16(frame.target_x)))\nframe = first_replace(frame, status=_first_compare_long(frame, strength, 5000).status)\nstate.sr = state.sr & 65504 | frame.status\nif strength > 5000:\n    return frame\nframe = first_replace(frame, candidates=state.table_at(4294943056).cursor())\nframe = _movement_move(state, frame, 'target_y', frame.candidates.word(s16(low16(frame.target_x))), 16)\nframe = _duel_commit_shift_fields(state, frame, 'target_y', 7, True)\nframe = _movement_move(state, frame, 'unit', frame.candidates.word(s16(low16(frame.target_x)), 2), 16)\nframe = _duel_commit_shift_fields(state, frame, 'unit', 7, True)\nframe, terrain = _deployment_terrain_lookup(BattlePolicyMemory(state), frame, low16(frame.target_y), low16(frame.unit), 124478)\nframe = _movement_compare(state, frame, low8(frame.target_x), 3, 8)\nif low8(frame.target_x) != 3:\n    frame = _movement_compare(state, frame, low8(frame.target_x), 8, 8)\n    if low8(frame.target_x) != 8:\n        return frame\nframe = _movement_move(state, frame, 'target_x', state.read(4294964134, 2), 16)\nframe = first_replace(frame, roster=state.table_at(16726978).cursor())\nreturn _settlement_write_byte_fields(state, frame, frame.roster, 1, s16(low16(frame.target_x)))"}})

