DECLARATIONS.update({'initialize_city_engagement_menu_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': 'frame = _resource_cost_frame(state, frame, 124560)\nframe = _duel_menu_write_word_fields(state, frame, 4294944122, 65535)\nframe = _duel_menu_write_word_fields(state, frame, 4294944206, 65535)\nframe = _duel_menu_write_word_fields(state, frame, 4294964106, state.read(4294964754, 2))\nframe = _duel_menu_write_word_fields(state, frame, 4294964144, 1)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964951, 1)\nif not frame.status & 4:\n    frame = _duel_menu_write_word_fields(state, frame, 4294964144, 10)\nframe = _duel_menu_write_word_fields(state, frame, 4294964754, 1026)\nframe = _duel_menu_write_word_fields(state, frame, 4294964066, 0, True)\nframe = _duel_menu_write_word_fields(state, frame, 4294964736, 136)\nframe = _deployment_menu_call_fields(state, frame, 124630, 124620)\nframe = _deployment_menu_call_fields(state, frame, 125018, 124624)\nreturn _deployment_menu_call_fields(state, frame, 124714, 124628)'}})

DECLARATIONS.update({'clear_city_engagement_assignments_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "from .services import _movement_save_longs, _movement_restore_longs\nframe = _resource_cost_frame(state, frame, 124630)\nframe = _movement_save_longs(state, frame, ('target_y', 'candidates'))\nframe = _movement_move(state, frame, 'target_x', state.read(4294964874, 2), 16)\nframe = _movement_fixed_shift_word(state, frame, 'target_x', 1)\nframe = _movement_add_word(state, frame, 'target_x', state.read(4294964874, 2))\nframe = _movement_fixed_shift_word(state, frame, 'target_x', 2)\nframe = first_replace(frame, roster=state.table_at(4294961164).cursor(), candidates=state.table_at(4294954240).cursor())\nfor displacement in (0, 4, 8):\n    member = frame.roster.word(s16(low16(frame.target_x)), displacement)\n    frame = _movement_move(state, frame, 'target_y', member, 16)\n    if member & 32768:\n        continue\n    frame = _settlement_write_byte_fields(state, frame, frame.candidates, 0, s16(member), clear=True)\n    frame = _settlement_store_word_fields(state, frame, frame.roster, s16(low16(frame.target_x)), 65535, displacement)\nreturn _movement_restore_longs(state, frame, ('target_y', 'candidates'))"}})

DECLARATIONS.update({'remove_engagement_pair_packet_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 124782)\nframe = _movement_move(state, frame, 'unit', low16(frame.target_x), 16)\nframe = _movement_move(state, frame, 'count', low16(frame.target_y), 16)\nframe = _movement_fixed_shift_word(state, frame, 'unit', 2)\nframe = _movement_move(state, frame, 'distance', 0, 16)\nframe = _movement_move(state, frame, 'distance', frame.roster.byte(s16(low16(frame.unit))), 8)\nif frame.status & 4:\n    return frame\nowner = frame.candidates.byte(s16(low16(frame.distance)))\nframe = _movement_compare(state, frame, low8(frame.count), owner, 8)\nif not frame.status & 4:\n    return frame\nframe = _movement_move(state, frame, 'distance', 0, 16)\nframe = _movement_move(state, frame, 'distance', frame.roster.byte(s16(low16(frame.unit)), 1), 8)\nframe = _movement_fixed_shift_word(state, frame, 'distance', 2)\nframe = _engagement_clear_long_fields(state, frame, frame.controller, s16(low16(frame.distance)))\nframe = _engagement_clear_long_fields(state, frame, frame.roster, s16(low16(frame.unit)))\nframe = _movement_move(state, frame, 'distance', state.read(4294960896, 2), 16)\nframe = _movement_fixed_shift_word(state, frame, 'unit', 2, True)\nframe = _engagement_relationship_bit_fields(state, frame, 'distance', 'unit', True)\nreturn _duel_menu_write_word_fields(state, frame, 4294960896, low16(frame.distance))"}})

DECLARATIONS.update({'remove_city_engagement_links_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 124714)\nframe = first_replace(frame, roster=state.table_at(4294960912).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964876, 2), 16)\nframe = _movement_fixed_shift_word(state, frame, 'target_x', 1)\nframe = _movement_move(state, frame, 'target_y', state.read(4294964878, 2), 16)\nframe = _movement_move(state, frame, 'unit', frame.roster.word(s16(low16(frame.target_x))), 16)\nframe = _engagement_relationship_bit_fields(state, frame, 'unit', 'target_y')\nif frame.status & 4:\n    return frame\nframe = _engagement_relationship_bit_fields(state, frame, 'unit', 'target_y', True)\nframe = _settlement_store_word_fields(state, frame, frame.roster, s16(low16(frame.target_x)), low16(frame.unit))\nframe = _deployment_menu_call_fields(state, frame, 124836, 124748)\nframe = _movement_fixed_shift_word(state, frame, 'target_x', 1, True)\nframe = _movement_fixed_shift_word(state, frame, 'target_y', 1)\nframe = _movement_move(state, frame, 'unit', frame.roster.word(s16(low16(frame.target_y))), 16)\nframe = _engagement_relationship_bit_fields(state, frame, 'unit', 'target_x', True)\nframe = _settlement_store_word_fields(state, frame, frame.roster, s16(low16(frame.target_y)), low16(frame.unit))\nframe = _movement_fixed_shift_word(state, frame, 'target_y', 1, True)\nframe = first_replace(frame, roster=state.table_at(4294961656).cursor(), candidates=state.table_at(4294964263).cursor(), controller=state.table_at(4294960732).cursor())\nframe = _deployment_menu_call_fields(state, frame, 124782, 124780)\nframe = first_replace(frame, target_x=frame.target_y, target_y=frame.target_x)\nreturn remove_engagement_pair_packet_fields(state, frame)"}})

DECLARATIONS.update({'debit_engagement_city_loyalty_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "from .services import _movement_save_longs, _movement_restore_longs\nframe = _resource_cost_frame(state, frame, 124836)\nsaved = ('target_x', 'target_y', 'roster')\nframe = _movement_save_longs(state, frame, saved)\nframe = sample_battle_action_random_fields(BattlePolicyMemory(state), frame, 124846)\nframe = _movement_move_long(state, frame, 'target_x', low16(frame.target_x))\nframe = _movement_move_long(state, frame, 'target_y', frame.target_x)\nframe = _special_action_shift_long(state, frame, 'target_x', 1)\nframe = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y)\nframe = _special_action_shift_long(state, frame, 'target_x', 1)\nframe = _special_action_swap(state, frame, 'target_x')\nframe = _movement_add_word(state, frame, 'target_x', 5)\nframe = first_replace(frame, roster=state.table_at(4294960704).cursor())\nframe = _movement_move(state, frame, 'target_y', state.read(4294964876, 2), 16)\nframe = _movement_fixed_shift_word(state, frame, 'target_y', 1)\nframe = _movement_move(state, frame, 'target_y', frame.roster.word(s16(low16(frame.target_y))), 16)\nframe = first_replace(frame, roster=state.table_at(4294951424).cursor())\nold = frame.roster.byte(s16(low16(frame.target_y)))\nframe, changed = _movement_binary_flags(state, frame, old, low8(frame.target_x), 8, True)\nframe.roster.set_byte(s16(low16(frame.target_y)), changed)\nif frame.status & 1:\n    frame = _settlement_write_byte_fields(state, frame, frame.roster, 0, s16(low16(frame.target_y)), clear=True)\nreturn _movement_restore_longs(state, frame, saved)"}})

DECLARATIONS.update({'choose_city_engagement_visibility_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 124900)\nframe = first_replace(frame, roster=state.table_at(4294942719).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964874, 2), 16)\nframe = _movement_test(state, frame, frame.roster.byte(s16(low16(frame.target_x))), 8)\nblocked = not bool(frame.status & 4)\nif not blocked:\n    frame = first_replace(frame, roster=state.table_at(4294963114).cursor())\n    frame = _movement_adjust_word(state, frame, 'target_x', -1)\n    frame = _movement_move(state, frame, 'target_y', low16(frame.target_x), 16)\n    frame = _movement_fixed_shift_word(state, frame, 'target_x', 3, True)\n    value = frame.roster.byte(s16(low16(frame.target_x)))\n    mask = 1 << (frame.target_y & 7)\n    status = frame.status & 27 | (0 if value & mask else 4)\n    state.sr = state.sr & 65504 | status\n    frame = first_replace(frame, status=status)\n    blocked = not bool(frame.status & 4)\nif blocked:\n    frame = _duel_menu_write_word_fields(state, frame, 4294964736, 216)\n    return _duel_menu_write_word_fields(state, frame, 4294964066, 15)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964876, 2), 16)\nvisible = False\nfor address in (4294964858, 4294964860, 4294964862):\n    frame = _movement_compare(state, frame, low16(frame.target_x), state.read(address, 2), 16)\n    if frame.status & 4:\n        visible = True\n        break\nif not visible:\n    frame = _duel_menu_write_word_fields(state, frame, 4294964066, 15)\n    return _duel_menu_write_word_fields(state, frame, 4294964736, 184)\nframe = _duel_menu_change_word_fields(state, frame, 4294964066, 1)\nframe = _movement_move(state, frame, 'target_x', 256, 16)\nframe = _duel_menu_write_word_fields(state, frame, 4294946688, low16(frame.target_x))\nframe = _deployment_menu_call_fields(state, frame, 423666, 124996)\nreturn _duel_menu_write_word_fields(state, frame, 4294964934, 0, True)"}})

DECLARATIONS.update({'reset_city_engagement_tables_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 125018)\nframe = first_replace(frame, roster=state.table_at(4294944340).cursor(), candidates=state.table_at(4294944596).cursor(), controller=state.table_at(4294946344).cursor(), scan=state.table_at(4294954670).cursor())\nframe = _movement_move(state, frame, 'target_x', 63, 16)\nwhile True:\n    for name, view in (('roster', frame.roster), ('candidates', frame.candidates), ('controller', frame.controller), ('scan', frame.scan)):\n        frame = _engagement_clear_long_fields(state, frame, view)\n        frame = first_replace(frame, **{name: view.advance(4)})\n    counter = low16(frame.target_x)\n    frame = first_replace(frame, target_x=replace_word(frame.target_x, u16(counter - 1)))\n    if counter == 0:\n        break\nfor address in (4294964968, 4294964970, 4294964972, 4294964974):\n    frame = _duel_menu_write_word_fields(state, frame, address, 65535)\nframe = _duel_menu_write_word_fields(state, frame, 4294964936, 0, True)\nreturn _duel_menu_write_word_fields(state, frame, 4294964984, 0, True)"}})

DECLARATIONS.update({'open_city_engagement_confirmation_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': 'frame = _resource_cost_frame(state, frame, 125084)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964739, 5)\nif frame.status & 4:\n    return frame\nframe = _duel_menu_write_word_fields(state, frame, 4294964162, state.read(4294964754, 2))\nframe = _duel_menu_write_word_fields(state, frame, 4294964164, 3)\nframe = _deployment_menu_call_fields(state, frame, 125126, 125108)\nframe = _duel_menu_write_word_fields(state, frame, 4294964062, 104)\nframe = _duel_menu_write_word_fields(state, frame, 4294964064, 152)\nreturn _deployment_menu_call_fields(state, frame, 125156, 125124)'}})

DECLARATIONS.update({'copy_city_engagement_confirmation_packet_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 125126)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964874, 2), 16)\nframe = _first_shift_word(frame, 'target_x', low16(frame.target_x), 5)\nstate.sr = state.sr & 65504 | frame.status\nframe = first_replace(frame, roster=state.table_at(u32(703914 + s16(low16(frame.target_x)))).cursor(), candidates=state.table_at(4294946730).cursor())\nframe = _movement_move(state, frame, 'target_y', 15, 16)\nwhile True:\n    value = frame.roster.word()\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _settlement_store_word_fields(state, frame, frame.candidates, 0, value)\n    frame = first_replace(frame, candidates=frame.candidates.advance(2))\n    counter = low16(frame.target_y)\n    frame = first_replace(frame, target_y=replace_word(frame.target_y, u16(counter - 1)))\n    if counter == 0:\n        return frame"}})

