DECLARATIONS.update({'_city_order_alternate_view_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, phase: int, continuation: int', 'returns': 'FirstDeploymentFrame', 'flow': "if (phase, continuation) not in ((8, 125742), (14, 126498)):\n    raise ValueError('closed city marker-view handoff required')\nframe = _duel_menu_write_word_fields(state, frame, 4294964162, state.read(4294964754, 2))\nframe = _duel_menu_write_word_fields(state, frame, 4294964164, phase)\nreturn _deployment_menu_call_fields(state, frame, 125156, continuation)"}})

DECLARATIONS.update({'_city_order_commit_marker_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, sound_return: int', 'returns': 'FirstDeploymentFrame', 'flow': "if sound_return not in (126154, 126692):\n    raise ValueError('closed city marker commit return required')\nprevious = frame.roster.byte()\nframe = _settlement_write_byte_fields(state, frame, frame.roster, previous | 128)\nframe = first_replace(frame, candidates=state.table_at(4294964480).cursor())\nframe = _movement_move(state, frame, 'count', state.read(4294964088, 2), 16)\nframe = _movement_fixed_shift_word(state, frame, 'count', 1)\nframe = _movement_move(state, frame, 'distance', frame.candidates.word(low16(frame.count)), 16)\nprevious = frame.candidates.word(low16(frame.count))\nframe = _settlement_store_word_fields(state, frame, frame.candidates, low16(frame.count), previous | 16384)\nframe = first_replace(frame, controller=state.table_at(4294943056))\nframe = _movement_fixed_shift_word(state, frame, 'distance', 2)\nframe = _movement_move(state, frame, 'target_x', frame.roster.byte(), 8)\nframe = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 127, 16)\nframe = _movement_fixed_shift_word(state, frame, 'target_x', 3)\nframe = _movement_fixed_shift_word(state, frame, 'target_x', 7)\nframe = _settlement_store_word_fields(state, frame, frame.controller, low16(frame.distance), low16(frame.target_x))\nframe = _movement_move(state, frame, 'target_x', 0, 16)\nframe = _movement_move(state, frame, 'target_x', frame.roster.byte(0, 1), 8)\nframe = _movement_fixed_shift_word(state, frame, 'target_x', 3)\nframe = _movement_fixed_shift_word(state, frame, 'target_x', 7)\nframe = _settlement_store_word_fields(state, frame, frame.controller, low16(frame.distance), low16(frame.target_x), 2)\nframe = _movement_move(state, frame, 'target_x', 172, 16)\nframe = _deployment_menu_call_fields(state, frame, 32906, sound_return)\nprevious = state.read(4294964944, 2)\nframe, remaining = _movement_binary_flags(state, frame, previous, 1, 16, True)\nstate.write(4294964944, 2, remaining)\nreturn frame"}})

DECLARATIONS.update({'_city_order_finish_defender_positions_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': 'frame = _duel_menu_write_word_fields(state, frame, 4294964950, 0, True)\nframe = _duel_menu_write_word_fields(state, frame, 4294944248, 65535)\nframe, reserved = _city_order_reserved_city_fields(state, frame)\nif reserved:\n    return _duel_menu_write_word_fields(state, frame, 4294964066, 1)\nframe = _duel_menu_write_word_fields(state, frame, 4294964066, 15)\nreturn _duel_menu_write_word_fields(state, frame, 4294964736, 184)'}})

DECLARATIONS.update({'_city_order_forced_side_message_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _duel_menu_write_word_fields(state, frame, 4294964066, 4)\nframe = _movement_move(state, frame, 'target_x', 156, 16)\nframe = _deployment_menu_call_fields(state, frame, 423666, 127164)\nframe = _movement_move(state, frame, 'target_x', state.read(4294963064, 2), 16)\nframe = first_replace(frame, roster=state.table_at(4294953984).cursor())\nframe = _movement_move(state, frame, 'target_x', frame.roster.byte(low16(frame.target_x)), 8)\nframe = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 63, 16)\nframe = first_replace(frame, roster=state.table_at(4294964263).cursor())\nframe = _movement_move(state, frame, 'target_x', frame.roster.byte(low16(frame.target_x)), 8)\nframe = _movement_move(state, frame, 'target_y', 0, 16)\nframe = _movement_compare(state, frame, low16(frame.target_x), state.read(4294964876, 2), 16)\nif not frame.status & 4:\n    from ..high_level_gameplay_flow.business_battle import _postbattle_bit_fields\n    frame = _postbattle_bit_fields(frame, bool(frame.target_y & 2))\n    state.sr = state.sr & 65504 | frame.status\n    frame = first_replace(frame, target_y=frame.target_y | 2)\nreturn _duel_menu_write_word_fields(state, frame, 4294964950, low16(frame.target_y))"}})

DECLARATIONS.update({'_city_order_interaction_bit_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, address: int, bit: int', 'returns': 'FirstDeploymentFrame', 'flow': "if not (address in (4294964739, 4294964741) and bit in (5, 6, 7) or (address == 4294964984 and bit in (0, 1, 2, 3))):\n    raise ValueError('closed city interaction BYTE bit required')\nfrom ..high_level_gameplay_flow.business_battle import _postbattle_bit_fields\nframe = _postbattle_bit_fields(frame, bool(state.read(address, 1) & 1 << bit))\nstate.sr = state.sr & 65504 | frame.status\nreturn frame"}})

