DECLARATIONS.update({'_city_order_interaction_display_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, draw_markers: bool=True', 'returns': 'FirstDeploymentFrame', 'flow': "if type(draw_markers) is not bool:\n    raise ValueError('closed original display-tail entry required')\nif draw_markers:\n    frame = _deployment_menu_call_fields(state, frame, 129618, 127278)\nframe = _deployment_menu_call_fields(state, frame, 127292, 127282)\nframe = _deployment_menu_call_fields(state, frame, 131298, 127286)\nreturn _deployment_menu_call_fields(state, frame, 131208, 127290)"}})

