DECLARATIONS.update({'_city_order_marker_cell_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, stop_on_zero_neighbor: bool', 'returns': 'tuple', 'flow': "if type(stop_on_zero_neighbor) is not bool:\n    raise ValueError('closed marker neighbor gate required')\nframe = _movement_move(state, frame, 'target_x', state.read(4294964062, 2), 16)\nframe = _movement_add_word(state, frame, 'target_x', 12)\nframe = _movement_fixed_shift_word(state, frame, 'target_x', 3, True)\nframe = _movement_move(state, frame, 'target_y', low16(frame.target_x), 16)\nframe = _movement_adjust_word(state, frame, 'target_x', -1)\nif stop_on_zero_neighbor and frame.status & 4:\n    return (frame, False)\nframe = _movement_move(state, frame, 'unit', state.read(4294964064, 2), 16)\nframe = _movement_add_word(state, frame, 'unit', 12)\nframe = _movement_fixed_shift_word(state, frame, 'unit', 3, True)\nframe = _movement_move(state, frame, 'count', low16(frame.unit), 16)\nframe = _movement_adjust_word(state, frame, 'unit', -1)\nif stop_on_zero_neighbor and frame.status & 4:\n    return (frame, False)\nframe = first_replace(frame, roster=state.table_at(4294946730).cursor())\nframe = _movement_move(state, frame, 'distance', 0, 16)\nwhile True:\n    frame = _movement_compare(state, frame, low8(frame.target_x), frame.roster.byte(), 8)\n    match_x = bool(frame.status & 4)\n    if not match_x:\n        frame = _movement_compare(state, frame, low8(frame.target_y), frame.roster.byte(), 8)\n        match_x = bool(frame.status & 4)\n    matched = False\n    if match_x:\n        frame = _movement_compare(state, frame, low8(frame.unit), frame.roster.byte(0, 1), 8)\n        matched = bool(frame.status & 4)\n        if not matched:\n            frame = _movement_compare(state, frame, low8(frame.count), frame.roster.byte(0, 1), 8)\n            matched = bool(frame.status & 4)\n    if matched:\n        return (frame, True)\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _movement_adjust_word(state, frame, 'distance', 1)\n    frame = _movement_compare(state, frame, low16(frame.distance), 16, 16)\n    if not frame.status & 1:\n        return (frame, False)"}})

DECLARATIONS.update({'_city_order_remainder_member_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, phase: int', 'returns': 'FirstDeploymentFrame', 'flow': "if phase not in (7, 13):\n    raise ValueError('closed remainder-member phase required')\nframe = _movement_move(state, frame, 'target_x', state.read(4294964088, 2), 16)\nframe = _movement_fixed_shift_word(state, frame, 'target_x', 1)\nframe = first_replace(frame, candidates=state.table_at(4294964480).cursor())\nframe = _movement_move(state, frame, 'target_y', frame.candidates.word(low16(frame.target_x)), 16)\nframe = _duel_menu_write_word_fields(state, frame, 4294964942, low16(frame.target_x))\nframe = _duel_menu_write_word_fields(state, frame, 4294964106, state.read(4294964754, 2))\nframe = _duel_menu_write_word_fields(state, frame, 4294964144, phase)\nframe = _duel_menu_write_word_fields(state, frame, 4294964754, 1030)\nreturn _duel_menu_write_word_fields(state, frame, 4294964074, 0, True)"}})

DECLARATIONS.update({'_city_order_reserved_city_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'tuple', 'flow': "frame = _movement_move(state, frame, 'target_x', state.read(4294964876, 2), 16)\nfor address in (4294964858, 4294964860, 4294964862):\n    frame = _movement_compare(state, frame, low16(frame.target_x), state.read(address, 2), 16)\n    if frame.status & 4:\n        return (frame, True)\nreturn (frame, False)"}})

DECLARATIONS.update({'_city_order_second_member_message_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, phase: int, continuation: int', 'returns': 'FirstDeploymentFrame', 'flow': "if (phase, continuation) not in ((6, 125676), (12, 126432)):\n    raise ValueError('closed second-member message phase required')\nframe = _duel_menu_write_word_fields(state, frame, 4294964106, state.read(4294964754, 2))\nframe = _duel_menu_write_word_fields(state, frame, 4294964144, phase)\nframe = _duel_menu_write_word_fields(state, frame, 4294964754, 1029)\nframe = _duel_menu_write_word_fields(state, frame, 4294964066, 0, True)\nframe = _movement_move(state, frame, 'target_x', 258, 16)\nframe = _duel_menu_write_word_fields(state, frame, 4294946688, low16(frame.target_x))\nframe = _deployment_menu_call_fields(state, frame, 423666, continuation)\nreturn _duel_menu_write_word_fields(state, frame, 4294964946, 2)"}})

