DECLARATIONS.update({'confirm_city_order_defender_marker_view_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': 'frame = _resource_cost_frame(state, frame, 126500)\nframe = _deployment_menu_call_fields(state, frame, 125792, 126504)\nframe = _deployment_menu_call_fields(state, frame, 125942, 126508)\nframe = _deployment_menu_call_fields(state, frame, 107508, 126514)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964739, 5)\nif not frame.status & 4:\n    return _deployment_menu_call_fields(state, frame, 126548, 126526)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964739, 4)\nif not frame.status & 4:\n    frame = _duel_menu_write_word_fields(state, frame, 4294964066, 11)\n    frame = _duel_menu_write_word_fields(state, frame, 4294964074, 0, True)\nreturn frame'}})

