DECLARATIONS.update({'copy_city_order_defender_tail_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 126328)\nframe = first_replace(frame, roster=state.table_at(4294964480).cursor(), candidates=state.table_at(4294944166).cursor())\nframe = _movement_move(state, frame, 'target_y', 0, 16)\nwhile True:\n    member = frame.candidates.word()\n    frame = first_replace(frame, candidates=frame.candidates.advance(2))\n    frame = _movement_move(state, frame, 'unit', member, 16)\n    if frame.status & 8:\n        break\n    frame = _settlement_store_word_fields(state, frame, frame.roster, 0, low16(frame.unit))\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _movement_adjust_word(state, frame, 'target_y', 1)\nframe = _settlement_store_word_fields(state, frame, frame.roster, 0, 65535)\nframe = first_replace(frame, roster=frame.roster.advance(2))\nframe = _duel_menu_write_word_fields(state, frame, 4294964790, low16(frame.target_y))\nreturn _duel_menu_write_word_fields(state, frame, 4294964944, low16(frame.target_y))"}})

DECLARATIONS.update({'copy_city_order_position_markers_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 126362)\nframe = first_replace(frame, roster=state.table_at(705196).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964874, 2), 16)\nframe = _movement_fixed_shift_word(state, frame, 'target_x', 5)\nframe = first_replace(frame, roster=frame.roster.advance(s16(low16(frame.target_x))), candidates=state.table_at(4294946730).cursor())\nframe = _settlement_store_word_fields(state, frame, frame.candidates, 0, 65535)\nframe = first_replace(frame, candidates=frame.candidates.advance(2))\nframe = _movement_move(state, frame, 'target_x', 14, 16)\nwhile True:\n    pair = frame.roster.word()\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _settlement_store_word_fields(state, frame, frame.candidates, 0, pair)\n    frame = first_replace(frame, candidates=frame.candidates.advance(2), target_x=replace_word(frame.target_x, u16(low16(frame.target_x) - 1)))\n    if low16(frame.target_x) == 65535:\n        return frame"}})

