DECLARATIONS.update({'combine_city_engagement_button_masks_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 127816)\ndef matches(carrier, address):\n    nonlocal frame\n    frame = _movement_compare(state, frame, low16(frame.carrier(carrier)), state.read(address, 2), 16)\n    return bool(frame.status & 4)\nframe = _movement_move(state, frame, 'target_x', 0, 16)\nframe = _movement_move(state, frame, 'target_y', state.read(4294964876, 2), 16)\nframe = _movement_move(state, frame, 'unit', state.read(4294964878, 2), 16)\nfirst = False\nif matches('target_y', 4294964858):\n    first = True\nelif matches('unit', 4294964858):\n    first = True\nelif matches('target_y', 4294964862):\n    first = matches('unit', 4294964860)\nelif matches('unit', 4294964862):\n    first = matches('target_y', 4294964860)\nif first:\n    frame = _movement_move(state, frame, 'target_x', state.read(4294964738, 2), 16)\nsecond = False\nif matches('target_y', 4294964860):\n    second = True\nelif matches('unit', 4294964860):\n    second = True\nelif matches('target_y', 4294964862):\n    second = not matches('unit', 4294964860)\nelif matches('unit', 4294964862):\n    second = not matches('target_y', 4294964860)\nelse:\n    second = True\nif second:\n    mask = state.read(4294964740, 2)\n    frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) | mask, 16)\nreturn frame"}})

