DECLARATIONS.update({'_city_order_tick_byte_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, carrier: str, status_reset: bool=False', 'returns': 'FirstDeploymentFrame', 'flow': "if carrier not in ('roster', 'candidates') or type(status_reset) is not bool:\n    raise ValueError('closed original counter view required')\nview = frame.roster if carrier == 'roster' else frame.candidates\nframe = _movement_move(state, frame, 'target_x', view.byte(), 8)\nif not frame.status & 4:\n    frame, value = _movement_binary_flags(state, frame, low8(frame.target_x), 1, 8, True)\n    frame = first_replace(frame, target_x=replace_byte(frame.target_x, value))\n    if status_reset and frame.status & 8:\n        frame = _movement_compare(state, frame, low8(frame.target_x), 128, 8)\n        if frame.status & 4:\n            frame = _movement_move(state, frame, 'target_x', 0, 8)\nframe = _settlement_write_byte_fields(state, frame, view, low8(frame.target_x))\nreturn first_replace(frame, **{carrier: view.advance(1)})"}})

DECLARATIONS.update({'advance_city_order_day_progress_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 129618)\nframe = _movement_move(state, frame, 'target_x', state.read(4294965002, 2), 16)\nframe = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 3, 16)\nframe = _movement_fixed_shift_word(state, frame, 'target_x', 1)\npace = state.read(u32(129696 + s16(low16(frame.target_x))), 2)\nframe = _movement_move(state, frame, 'target_x', pace, 16)\nframe, advanced = _movement_binary_flags(state, frame, state.read(4294964986, 2), low16(frame.target_x), 16)\nstate.write(4294964986, 2, advanced)\nframe = _movement_compare(state, frame, state.read(4294964986, 2), 2400, 16)\nif frame.status & 1:\n    return frame\nframe = _duel_menu_write_word_fields(state, frame, 4294964984, 0, True)\nframe = _duel_menu_write_word_fields(state, frame, 4294964986, 0, True)\nframe, advanced = _movement_binary_flags(state, frame, state.read(4294964936, 2), 1, 16)\nstate.write(4294964936, 2, advanced)\nframe = _movement_compare(state, frame, state.read(4294964936, 2), 29, 16)\nif not frame.status & 5:\n    frame = _duel_menu_write_word_fields(state, frame, 4294964754, 1043)\n    return _duel_menu_write_word_fields(state, frame, 4294964066, 0, True)\nframe = _deployment_menu_call_fields(state, frame, 107102, 129684)\nframe = _deployment_menu_call_fields(state, frame, 129704, 129688)\nreturn _duel_menu_write_word_fields(state, frame, 4294964736, 188)"}})

