DECLARATIONS.update({'tick_city_order_counters_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 127292)\nframe = first_replace(frame, roster=state.table_at(16727234).cursor())\nframe = _movement_move(state, frame, 'target_y', 255, 16)\nwhile True:\n    frame = _city_order_tick_byte_fields(state, frame, 'roster')\n    frame = first_replace(frame, target_y=replace_word(frame.target_y, u16(low16(frame.target_y) - 1)))\n    if low16(frame.target_y) == 65535:\n        return frame"}})

DECLARATIONS.update({'tick_city_order_status_counters_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 129704)\nframe = first_replace(frame, roster=state.table_at(4294944340).cursor(), candidates=state.table_at(16727490).cursor())\nframe = _movement_move(state, frame, 'target_y', 255, 16)\nwhile True:\n    frame = _city_order_tick_byte_fields(state, frame, 'roster', True)\n    frame = _city_order_tick_byte_fields(state, frame, 'candidates')\n    frame = first_replace(frame, target_y=replace_word(frame.target_y, u16(low16(frame.target_y) - 1)))\n    if low16(frame.target_y) == 65535:\n        break\nframe = first_replace(frame, roster=state.table_at(4294944596).cursor())\nframe = _movement_move(state, frame, 'target_y', 255, 16)\nwhile True:\n    frame = _city_order_tick_byte_fields(state, frame, 'roster')\n    frame = first_replace(frame, target_y=replace_word(frame.target_y, u16(low16(frame.target_y) - 1)))\n    if low16(frame.target_y) == 65535:\n        return frame"}})

