DECLARATIONS.update({'append_city_order_day_packet_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 107102)\nframe = _movement_move_long(state, frame, 'target_x', 0)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964936, 2), 16)\nframe = _movement_adjust_word(state, frame, 'target_x', 1)\nframe = _movement_move(state, frame, 'target_y', 50272, 16)\nframe = _movement_move(state, frame, 'unit', 32768, 16)\nframe = first_replace(frame, auxiliary=state.table_at(4294955776).cursor())\nframe = _deployment_menu_call_fields(state, frame, 75530, 107128)\nframe = first_replace(frame, roster=state.table_at(4294955264).cursor())\nframe = first_replace(frame, roster=frame.roster.advance(s16(state.read(4294963994, 2))))\nfor tile in (4, 49350):\n    frame = _settlement_store_word_fields(state, frame, frame.roster, 0, tile)\n    frame = first_replace(frame, roster=frame.roster.advance(2))\nframe = _movement_compare(state, frame, state.read(4294955784, 2), 32768, 16)\nif frame.status & 4:\n    frame = _settlement_store_word_fields(state, frame, frame.roster, 0, 32768)\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _settlement_store_word_fields(state, frame, frame.roster, 0, 50282)\n    frame = first_replace(frame, roster=frame.roster.advance(2))\nelse:\n    frame = _settlement_store_word_fields(state, frame, frame.roster, 0, 50282)\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _settlement_store_word_fields(state, frame, frame.roster, 0, state.read(4294955784, 2))\n    frame = first_replace(frame, roster=frame.roster.advance(2))\nframe = _settlement_store_word_fields(state, frame, frame.roster, 0, state.read(4294955786, 2))\nframe = first_replace(frame, roster=frame.roster.advance(2))\nframe = _settlement_store_word_fields(state, frame, frame.roster, 0, 50283)\nframe = first_replace(frame, roster=frame.roster.advance(2))\nframe = _settlement_store_word_fields(state, frame, frame.roster, 0, 0, clear=True)\nframe, advanced = _movement_binary_flags(state, frame, state.read(4294963994, 2), 12, 16)\nstate.write(4294963994, 2, advanced)\nreturn frame"}})

