DECLARATIONS.update({'city_select_live_state_42': {'signature': 'state: SceneState, inputs: CitySelectLiveState42Input', 'returns': 'CitySelectLiveState42Result', 'flow': "checked_state(state)\nif type(inputs) is not CitySelectLiveState42Input:\n    raise ValueError('function-specific historical duel-commit input required')\ninputs.validate(state)\nconditions = int(inputs.carry) | (2 if inputs.overflow else 0) | (4 if inputs.zero else 0) | (8 if inputs.negative else 0)\nstate.sr = state.sr & 65520 | conditions\nframe = first_replace(FirstDeploymentFrame.unobserved())\nframe = select_city_encounter_first_player_phase_fields(state, frame)\nreturn CitySelectLiveState42Result(carry=bool(state.sr & 1), zero=bool(state.sr & 4), negative=bool(state.sr & 8), overflow=bool(state.sr & 2)).validate(state)"}})

DECLARATIONS.update({'_city_encounter_shift_word_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, carrier: str, amount: int, right: bool=False', 'returns': 'FirstDeploymentFrame', 'flow': "from .business_highbank import _position_order_shift\nif amount not in (1, 2, 6, 7, 8):\n    raise ValueError('actual encounter WORD shift required')\nframe = _position_order_shift(frame, carrier, amount, right)\nstate.sr = state.sr & 65504 | frame.status\nreturn frame"}})

DECLARATIONS.update({'_city_encounter_bit_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, value, bit: int', 'returns': 'FirstDeploymentFrame', 'flow': "uint(value, 32)\nif bit not in (5, 6):\n    raise ValueError('closed encounter flag bit required')\nstatus = frame.status & 27 | (0 if value & 1 << bit else 4)\nstate.sr = state.sr & 65504 | status\nreturn first_replace(frame, status=status)"}})

DECLARATIONS.update({'_city_encounter_random_increment_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, continuation: int, multiplier: int, base: int', 'returns': 'FirstDeploymentFrame', 'flow': "if (multiplier, base) not in ((6, 5), (5, 1), (11, 10)):\n    raise ValueError('actual encounter random scale required')\nframe = sample_battle_action_random_fields(BattlePolicyMemory(state), frame, continuation)\nframe = _movement_move_long(state, frame, 'target_x', frame.target_x & 65535)\nframe = _movement_move_long(state, frame, 'target_y', frame.target_x)\nframe = _special_action_shift_long(state, frame, 'target_x', 1 if multiplier == 6 else 2)\nframe = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y)\nif multiplier != 5:\n    frame = _special_action_shift_long(state, frame, 'target_x', 1)\n    if multiplier == 11:\n        frame = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y)\nframe = _special_action_swap(state, frame, 'target_x')\nreturn _movement_add_word(state, frame, 'target_x', base)"}})

DECLARATIONS.update({'_city_encounter_debit_attribute_byte_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, view, index: int, carrier: str', 'returns': 'FirstDeploymentFrame', 'flow': 'frame = _movement_move(state, frame, carrier, view.byte(index), 8)\nframe, value = _movement_binary_flags(state, frame, low8(frame.carrier(carrier)), low8(frame.target_x), 8, True)\nframe = first_replace(frame, **{carrier: replace_byte(frame.carrier(carrier), value)})\nif frame.status & 1:\n    frame = _movement_move(state, frame, carrier, 0, 8)\nreturn _settlement_write_byte_fields(state, frame, view, low8(frame.carrier(carrier)), index)'}})

DECLARATIONS.update({'process_city_encounter_pending_pairs_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 128094)\nframe = sample_battle_action_random_fields(BattlePolicyMemory(state), frame, 128100)\nframe = first_replace(frame, roster=state.table_at(4294946144).cursor(), candidates=state.table_at(4294944248).cursor(), controller=state.table_at(16726978).cursor())\nwhile True:\n    pair = frame.roster.word()\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _movement_move(state, frame, 'target_x', pair, 16)\n    if not frame.status & 4:\n        break\nframe = _movement_compare(state, frame, low16(frame.target_x), 65535, 16)\nif not frame.status & 4:\n    frame = _movement_move(state, frame, 'target_y', 0, 16)\n    frame = _movement_move(state, frame, 'target_y', low8(frame.target_x), 8)\n    frame = _city_encounter_shift_word_fields(state, frame, 'target_x', 8, True)\n    frame = _duel_menu_write_word_fields(state, frame, 4294964994, low16(frame.target_x))\n    frame = _movement_move(state, frame, 'unit', low16(frame.target_x), 16)\n    frame = _movement_move(state, frame, 'count', low16(frame.target_y), 16)\n    frame = _deployment_menu_call_fields(state, frame, 128170, 128144)\n    frame = _settlement_store_word_fields(state, frame, frame.candidates, 0, low16(frame.target_x))\n    frame = first_replace(frame, candidates=frame.candidates.advance(2))\n    frame = _duel_menu_write_word_fields(state, frame, 4294964998, low16(frame.target_y))\n    frame = _movement_move(state, frame, 'unit', low16(frame.target_y), 16)\n    frame = _movement_move(state, frame, 'count', low16(frame.target_x), 16)\n    frame = _deployment_menu_call_fields(state, frame, 128170, 128158)\n    frame = _settlement_store_word_fields(state, frame, frame.candidates, 0, low16(frame.target_y))\n    frame = first_replace(frame, candidates=frame.candidates.advance(2))\n    frame = _settlement_store_word_fields(state, frame, frame.roster, 0, 0, -2, True)\nreturn _settlement_store_word_fields(state, frame, frame.candidates, 0, 65535)"}})

DECLARATIONS.update({'resolve_city_encounter_pair_activity_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "from .services import _movement_save_longs, _movement_restore_longs\nframe = _resource_cost_frame(state, frame, 128170)\nactivity = frame.controller.byte(s16(low16(frame.unit)))\nframe = _movement_test(state, frame, activity, 8)\nif frame.status & 4:\n    frame = _duel_menu_write_word_fields(state, frame, 4294965094, 65535)\n    state.sr &= 65534\n    return first_replace(frame, status=state.sr & 31)\nframe = _duel_menu_write_word_fields(state, frame, 4294965094, low16(frame.unit))\nframe = _duel_menu_write_word_fields(state, frame, 4294964176, low16(frame.count))\nframe = _movement_move_long(state, frame, 'distance', 0)\nframe = _movement_move(state, frame, 'distance', state.read(4294964764, 2), 16)\nframe = _movement_multiply_word(state, frame, 'distance', 100)\nframe = _special_action_swap(state, frame, 'distance')\nframe = first_replace(frame, scan=state.table_at(4294948352).cursor())\nframe = _city_encounter_shift_word_fields(state, frame, 'count', 1)\nframe = _movement_move(state, frame, 'offset_x', frame.scan.word(s16(low16(frame.count))), 16)\nframe = _city_encounter_shift_word_fields(state, frame, 'offset_x', 1, True)\nframe = _movement_compare(state, frame, low16(frame.distance), low16(frame.offset_x), 16)\nif frame.status & 5:\n    frame = _settlement_write_byte_fields(state, frame, frame.controller, 0, s16(low16(frame.unit)), clear=True)\n    frame = _movement_save_longs(state, frame, ('target_x', 'target_y'))\n    frame = _deployment_menu_call_fields(state, frame, 128274, 128228)\n    frame = _deployment_menu_call_fields(state, frame, 128382, 128232)\n    frame = first_replace(frame, scan=state.table_at(16727234).cursor())\n    frame = _settlement_write_byte_fields(state, frame, frame.scan, 180, s16(low16(frame.unit)))\n    frame = _movement_restore_longs(state, frame, ('target_x', 'target_y'))\n    value = state.read(4294965094, 1)\n    frame = _city_encounter_bit_fields(state, frame, value, 6)\n    state.write(4294965094, 1, value | 64)\nstate.sr |= 1\nreturn first_replace(frame, status=state.sr & 31)"}})

DECLARATIONS.update({'award_city_encounter_pair_attributes_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 128274)\nframe = _city_encounter_random_increment_fields(state, frame, 128280, 6, 5)\nframe = first_replace(frame, scan=state.table_at(4294950912).cursor())\nframe = _special_action_add_capped_word(state, frame, frame.scan, s16(low16(frame.count)), 'distance', low16(frame.target_x))\nframe = _city_encounter_random_increment_fields(state, frame, 128332, 11, 10)\nframe = first_replace(frame, scan=state.table_at(4294950400).cursor())\nreturn _special_action_add_capped_word(state, frame, frame.scan, s16(low16(frame.count)), 'distance', low16(frame.target_x))"}})

DECLARATIONS.update({'debit_city_encounter_pair_attribute_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 128382)\nframe = _city_encounter_random_increment_fields(state, frame, 128388, 6, 5)\nframe = first_replace(frame, scan=state.table_at(4294952192).cursor())\nreturn _city_encounter_debit_attribute_byte_fields(state, frame, frame.scan, s16(low16(frame.unit)), 'distance')"}})

DECLARATIONS.update({'transfer_city_encounter_member_capacity_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 128430)\nframe = _city_encounter_random_increment_fields(state, frame, 128436, 5, 1)\nframe = _movement_move(state, frame, 'unit', state.read(4294944248, 2), 16)\nframe = _city_encounter_shift_word_fields(state, frame, 'unit', 2)\nframe = first_replace(frame, roster=state.table_at(4294952960).cursor())\nframe = _movement_move_long(state, frame, 'count', frame.roster.long(s16(low16(frame.unit))))\nframe = _movement_move_long(state, frame, 'distance', frame.count)\nframe = _movement_multiply_word(state, frame, 'count', low16(frame.target_x))\nframe = _movement_divu_word(state, frame, 'count', 10, 128470)\nframe = _special_action_sub_word(state, frame, 'distance', low16(frame.count))\nframe.roster.set_long(s16(low16(frame.unit)), frame.distance)\nframe = _movement_test_long(state, frame, frame.distance)\nframe = _movement_divu_word(state, frame, 'count', 60, 128480)\nframe = first_replace(frame, roster=state.table_at(4294950912).cursor())\nframe = _movement_move(state, frame, 'distance', state.read(4294965094, 2), 16)\nframe = _city_encounter_shift_word_fields(state, frame, 'distance', 1)\nframe = _special_action_add_capped_word(state, frame, frame.roster, s16(low16(frame.distance)), 'offset_x', low16(frame.count))\nframe = _city_encounter_random_increment_fields(state, frame, 128522, 11, 10)\nframe = first_replace(frame, roster=state.table_at(4294950400).cursor())\nframe = _special_action_add_capped_word(state, frame, frame.roster, s16(low16(frame.distance)), 'offset_x', low16(frame.target_x))\nframe = _city_encounter_random_increment_fields(state, frame, 128576, 11, 10)\nframe = first_replace(frame, roster=state.table_at(4294952192).cursor())\nframe = _movement_move(state, frame, 'unit', state.read(4294944248, 2), 16)\nframe = _city_encounter_debit_attribute_byte_fields(state, frame, frame.roster, s16(low16(frame.unit)), 'count')\nframe = _movement_move(state, frame, 'target_x', state.read(4294965094, 2), 16)\nframe = first_replace(frame, roster=state.table_at(16726978).cursor())\nreturn _settlement_write_byte_fields(state, frame, frame.roster, 0, s16(low16(frame.target_x)), clear=True)"}})

DECLARATIONS.update({'select_city_encounter_message_side_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 128638)\nframe = _duel_menu_write_word_fields(state, frame, 4294964950, 0, True)\nframe = _movement_move(state, frame, 'target_x', state.read(4294965094, 2), 16)\nframe = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 255, 16)\nframe = first_replace(frame, roster=state.table_at(4294944164).cursor())\nwhile True:\n    member = frame.roster.word()\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _movement_move(state, frame, 'target_y', member, 16)\n    if frame.status & 8:\n        return frame\n    frame = _movement_compare(state, frame, low16(frame.target_y), low16(frame.target_x), 16)\n    if frame.status & 4:\n        return _duel_menu_write_word_fields(state, frame, 4294964950, 2)"}})

DECLARATIONS.update({'process_city_encounter_pending_order_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 127940)\nframe = _deployment_menu_call_fields(state, frame, 128094, 127944)\nframe = _movement_compare(state, frame, state.read(4294944248, 2), 65535, 16)\nif frame.status & 4:\n    return _duel_menu_write_word_fields(state, frame, 4294964066, 0, True)\nframe = _movement_test(state, frame, state.read(4294965094, 2), 16)\nif frame.status & 8:\n    frame = _duel_menu_change_word_fields(state, frame, 4294964066, 1)\n    frame = _movement_move(state, frame, 'target_x', state.read(4294964994, 2), 16)\n    frame = _movement_move(state, frame, 'target_y', state.read(4294964998, 2), 16)\n    frame = _movement_move(state, frame, 'unit', state.read(4294964876, 2), 16)\n    matched = False\n    for address in (4294964858, 4294964860, 4294964862):\n        frame = _movement_compare(state, frame, low16(frame.unit), state.read(address, 2), 16)\n        if frame.status & 4:\n            matched = True\n            break\n    if not matched:\n        frame = first_replace(frame, target_x=frame.target_y, target_y=frame.target_x)\n    frame = _duel_menu_write_word_fields(state, frame, 4294964176, low16(frame.target_x))\n    frame = _duel_menu_write_word_fields(state, frame, 4294964178, low16(frame.target_y))\n    frame = _movement_move(state, frame, 'target_x', 276, 16)\n    frame = _duel_menu_write_word_fields(state, frame, 4294946688, low16(frame.target_x))\n    frame = _deployment_menu_call_fields(state, frame, 423666, 128026)\n    frame = _duel_menu_write_word_fields(state, frame, 4294964996, 65535)\n    return _duel_menu_write_word_fields(state, frame, 4294965000, 65535)\nframe = _city_encounter_bit_fields(state, frame, state.read(4294965094, 1), 6)\nif frame.status & 4:\n    frame = _deployment_menu_call_fields(state, frame, 128430, 128064)\n    frame = _movement_move(state, frame, 'target_x', 305, 16)\nelse:\n    frame = _movement_move(state, frame, 'target_x', 306, 16)\nframe = _duel_menu_write_word_fields(state, frame, 4294964066, 6)\nframe = _deployment_menu_call_fields(state, frame, 423666, 128088)\nreturn _deployment_menu_call_fields(state, frame, 128638, 128092)"}})

DECLARATIONS.update({'test_city_encounter_confirmation_buttons_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 128704)\ndef matches(carrier, address):\n    nonlocal frame\n    frame = _movement_compare(state, frame, low16(frame.carrier(carrier)), state.read(address, 2), 16)\n    return bool(frame.status & 4)\nframe = _movement_move(state, frame, 'unit', 0, 16)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964876, 2), 16)\nframe = _movement_move(state, frame, 'target_y', state.read(4294964878, 2), 16)\nfirst = False\nif matches('target_x', 4294964858):\n    first = True\nelif matches('target_y', 4294964858):\n    first = True\nelif matches('target_x', 4294964860):\n    first = matches('target_x', 4294964862) or matches('target_y', 4294964862)\nelif matches('target_y', 4294964860):\n    first = matches('target_x', 4294964862) or matches('target_y', 4294964862)\nif first:\n    frame = _movement_move(state, frame, 'unit', state.read(4294964738, 2), 16)\nsecond = False\nif matches('target_x', 4294964860):\n    second = True\nelif matches('target_y', 4294964860):\n    second = True\nelif matches('target_x', 4294964862):\n    second = True\nelif matches('target_y', 4294964862):\n    second = True\nif second:\n    frame = _movement_move(state, frame, 'unit', low16(frame.unit) | state.read(4294964740, 2), 16)\nreturn _city_encounter_bit_fields(state, frame, frame.unit, 5)"}})

DECLARATIONS.update({'confirm_city_encounter_launch_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 128672)\nframe = _deployment_menu_call_fields(state, frame, 128704, 128676)\nif frame.status & 4:\n    return frame\nframe = _duel_menu_change_word_fields(state, frame, 4294964066, 1)\nframe = _duel_menu_write_word_fields(state, frame, 4294965106, 1)\nframe = _duel_menu_write_word_fields(state, frame, 4294964050, 0, True)\nframe = _movement_move(state, frame, 'target_x', 172, 16)\nreturn _deployment_menu_call_fields(state, frame, 32906, 128702)"}})

DECLARATIONS.update({'stage_city_encounter_launch_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 128808)\nframe = _movement_compare(state, frame, state.read(4294964050, 2), 16, 16)\nif frame.status & 1:\n    frame = _movement_move(state, frame, 'target_x', state.read(4294964050, 2), 16)\n    frame = _movement_move(state, frame, 'target_y', 64, 16)\n    frame = first_replace(frame, roster=state.table_at(4294966144).cursor())\n    frame = _deployment_menu_call_fields(state, frame, 56998, 128836)\n    frame = _movement_move(state, frame, 'target_x', state.read(4294964000, 2), 16)\n    frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 1, 16)\n    if frame.status & 4:\n        value = state.read(4294964050, 2)\n        frame, value = _movement_binary_flags(state, frame, value, 1, 16)\n        state.write(4294964050, 2, value)\n    return frame\nframe = _duel_menu_write_word_fields(state, frame, 4294964106, 1040)\nframe = _duel_menu_write_word_fields(state, frame, 4294964144, 0, True)\nframe = _movement_move(state, frame, 'target_x', 2047, 16)\nframe = first_replace(frame, roster=state.table_at(16740352).cursor())\nwhile True:\n    frame.roster.long()\n    frame.roster.set_long(0, 0)\n    frame = first_replace(frame, roster=frame.roster.advance(4))\n    frame = _movement_test_long(state, frame, 0)\n    frame = first_replace(frame, target_x=replace_word(frame.target_x, u16(low16(frame.target_x) - 1)))\n    if low16(frame.target_x) == 65535:\n        break\nframe = _deployment_menu_call_fields(state, frame, 128898, 128886)\nframe = _duel_menu_write_word_fields(state, frame, 4294964754, 0, True)\nreturn _duel_menu_write_word_fields(state, frame, 4294964736, 196)"}})

DECLARATIONS.update({'read_city_encounter_average_terrain_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 129158)\nframe = _deployment_menu_call_fields(state, frame, 107576, 129164)\nframe = first_replace(frame, candidates=state.table_at(4294943056).cursor())\nframe = _movement_move(state, frame, 'count', state.read(4294964994, 2), 16)\nframe = _city_encounter_shift_word_fields(state, frame, 'count', 2)\nframe = _movement_move(state, frame, 'distance', state.read(4294964998, 2), 16)\nframe = _city_encounter_shift_word_fields(state, frame, 'distance', 2)\nframe = _movement_move(state, frame, 'target_y', frame.candidates.word(s16(low16(frame.count))), 16)\nframe = _city_encounter_shift_word_fields(state, frame, 'target_y', 7, True)\nframe = _movement_move(state, frame, 'target_x', frame.candidates.word(s16(low16(frame.distance))), 16)\nframe = _city_encounter_shift_word_fields(state, frame, 'target_x', 7, True)\nframe = _movement_add_word(state, frame, 'target_y', low16(frame.target_x))\nframe = _city_encounter_shift_word_fields(state, frame, 'target_y', 1, True)\nframe = _movement_move(state, frame, 'unit', frame.candidates.word(s16(low16(frame.count)), 2), 16)\nframe = _city_encounter_shift_word_fields(state, frame, 'unit', 7, True)\nframe = _movement_move(state, frame, 'target_x', frame.candidates.word(s16(low16(frame.distance)), 2), 16)\nframe = _city_encounter_shift_word_fields(state, frame, 'target_x', 7, True)\nframe = _movement_add_word(state, frame, 'unit', low16(frame.target_x))\nframe = _city_encounter_shift_word_fields(state, frame, 'unit', 1, True)\nframe, terrain = _deployment_terrain_lookup(BattlePolicyMemory(state), frame, low16(frame.target_y), low16(frame.unit), continuation=129218)\nframe = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 255, 16)\nvalue = state.read(u32(129228 + s16(low16(frame.target_x))), 1)\nreturn _movement_move(state, frame, 'target_x', value, 8)"}})

DECLARATIONS.update({'_city_encounter_layout_player_index_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, player: int, step: int', 'returns': 'FirstDeploymentFrame', 'flow': "if (player, step) not in ((4294964876, 8), (4294964878, 2)):\n    raise ValueError('actual two-side layout index required')\nframe = _movement_move(state, frame, 'target_x', state.read(player, 2), 16)\nfor address in (4294964858, 4294964860, 4294964862):\n    frame = _movement_compare(state, frame, low16(frame.target_x), state.read(address, 2), 16)\n    if frame.status & 4:\n        break\n    frame = _movement_add_word(state, frame, 'target_y', step)\nreturn frame"}})

DECLARATIONS.update({'initialize_city_encounter_player_layout_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 129308)\nframe = _movement_move(state, frame, 'target_y', 0, 16)\nframe = _city_encounter_layout_player_index_fields(state, frame, 4294964876, 8)\nframe = _city_encounter_layout_player_index_fields(state, frame, 4294964878, 2)\nframe = first_replace(frame, roster=state.table_at(129406).cursor())\nvalue = frame.roster.byte(s16(low16(frame.target_y)))\nframe = _settlement_write_byte_fields(state, frame, state.table_at(4294934746), value)\nframe = _settlement_write_byte_fields(state, frame, state.table_at(4294934820), 0, clear=True)\nvalue = frame.roster.byte(s16(low16(frame.target_y)), 1)\nreturn _settlement_write_byte_fields(state, frame, state.table_at(4294934821), value)"}})

DECLARATIONS.update({'_city_encounter_packet_member_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, carrier: str', 'returns': 'FirstDeploymentFrame', 'flow': "if carrier == 'offset_y':\n    marker, attribute, maximum, first, second, third, capacity, continuation = (4294934752, 4294934785, 4294934792, 4294934788, 4294934796, 4294934800, 4294934756, 129032)\nelif carrier == 'choice':\n    marker, attribute, maximum, first, second, third, capacity, continuation = (4294934754, 4294934787, 4294934794, 4294934790, 4294934798, 4294934802, 4294934758, 129094)\nelse:\n    raise ValueError('original two encounter packet members required')\nframe = _duel_menu_write_word_fields(state, frame, marker, low16(frame.carrier(carrier)))\nvalue = frame.candidates.byte(s16(low16(frame.carrier(carrier))))\nframe = _settlement_write_byte_fields(state, frame, state.table_at(attribute), value)\nframe = _movement_move(state, frame, 'target_x', low16(frame.carrier(carrier)), 16)\nframe = _deployment_menu_call_fields(state, frame, 129236, continuation)\nframe = _duel_menu_write_word_fields(state, frame, maximum, low16(frame.count))\nframe = _city_encounter_shift_word_fields(state, frame, carrier, 1)\nindex = s16(low16(frame.carrier(carrier)))\nframe = _duel_menu_write_word_fields(state, frame, first, frame.controller.word(index))\nframe = _duel_menu_write_word_fields(state, frame, second, frame.scan.word(index))\nframe = _duel_menu_write_word_fields(state, frame, third, frame.opponent.word(index))\nframe = _city_encounter_shift_word_fields(state, frame, carrier, 1)\nreturn _duel_menu_write_word_fields(state, frame, capacity, frame.roster.word(s16(low16(frame.carrier(carrier))), 2))"}})

