DECLARATIONS.update({'_battle_result_count_bit_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, bit: int, set_bit: bool=False', 'returns': 'FirstDeploymentFrame', 'flow': "if bit not in (0, 1) or type(set_bit) is not bool:\n    raise ValueError('original pair spacing bit required')\nfrom ..high_level_gameplay_flow.business_battle import _postbattle_bit_fields\nvalue = frame.count\nframe = _postbattle_bit_fields(frame, bool(value & 1 << bit))\nstate.sr = state.sr & 65504 | frame.status\nif set_bit:\n    frame = first_replace(frame, count=value | 1 << bit)\nreturn frame"}})

DECLARATIONS.update({'_battle_result_delete_relation_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, source_member: bool', 'returns': 'FirstDeploymentFrame', 'flow': "if type(source_member) is not bool:\n    raise ValueError('original relation endpoint required')\nframe = first_replace(frame, roster=state.table_at(4294946144).cursor())\nwhile True:\n    frame = _movement_move(state, frame, 'target_y', frame.roster.word(), 16)\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    if frame.status & 4:\n        continue\n    frame = _movement_compare(state, frame, low16(frame.target_y), 65535, 16)\n    if frame.status & 4:\n        return frame\n    if source_member:\n        frame = _movement_fixed_shift_word(state, frame, 'target_y', 8, True)\n    else:\n        frame = _movement_move(state, frame, 'target_y', low16(frame.target_y) & 255, 16)\n    frame = _movement_compare(state, frame, low16(frame.target_y), low16(frame.target_x), 16)\n    if frame.status & 4:\n        frame = _settlement_store_word_fields(state, frame, frame.roster, 0, 0, -2, clear=True)"}})

DECLARATIONS.update({'_battle_result_stationary_retreat_axis_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, coordinate: str, displacement: int, maximum: int', 'returns': 'FirstDeploymentFrame', 'flow': "if (coordinate, displacement, maximum) not in (('unit', 0, 25600), ('count', 2, 37888)):\n    raise ValueError('original retreat coordinate axis required')\nframe = _movement_compare(state, frame, low16(frame.carrier(coordinate)), frame.opponent.word(low16(frame.distance), displacement), 16)\ngreater = not bool(frame.status & 5)\nif greater:\n    frame = _movement_add_word(state, frame, coordinate, 8400)\n    clamped = bool(frame.status & 1)\n    if not clamped:\n        frame = _movement_compare(state, frame, low16(frame.carrier(coordinate)), maximum, 16)\n        clamped = not bool(frame.status & 5) if displacement == 2 else not bool(frame.status & 1)\n    if clamped:\n        frame = _movement_move(state, frame, coordinate, maximum, 16)\nelse:\n    frame = _duel_commit_sub_word_fields(state, frame, coordinate, 8400)\n    clamped = bool(frame.status & 1)\n    if not clamped:\n        frame = _movement_compare(state, frame, low16(frame.carrier(coordinate)), 3072, 16)\n        clamped = bool(frame.status & 1) if displacement == 2 else bool(frame.status & 5)\n    if clamped:\n        frame = _movement_move(state, frame, coordinate, 3072, 16)\nframe = _duel_commit_shift_fields(state, frame, coordinate, 7, True)\nreturn _settlement_store_word_fields(state, frame, frame.scan, low16(frame.target_y), low16(frame.carrier(coordinate)), displacement)"}})

DECLARATIONS.update({'_battle_result_velocity_retreat_axis_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, coordinate: str, displacement: int, maximum: int', 'returns': 'FirstDeploymentFrame', 'flow': "if (coordinate, displacement, maximum) not in (('unit', 0, 25600), ('count', 2, 37888)):\n    raise ValueError('original retreat coordinate axis required')\nframe = _movement_move(state, frame, 'distance', frame.controller.word(low16(frame.target_y), displacement), 16)\nframe = _duel_commit_sub_word_fields(state, frame, 'distance', 0, True)\nframe = _movement_move_long(state, frame, 'distance', u32(s16(low16(frame.distance)) * 1200))\nnegative = bool(frame.status & 8)\nframe = _movement_add_word(state, frame, coordinate, low16(frame.distance))\nif negative:\n    low = not bool(frame.status & 1)\n    if not low:\n        frame = _movement_compare(state, frame, low16(frame.carrier(coordinate)), 3072, 16)\n        low = bool(frame.status & 1)\n    if low:\n        frame = _movement_move(state, frame, coordinate, 3072, 16)\nelse:\n    high = bool(frame.status & 1)\n    if not high:\n        frame = _movement_compare(state, frame, low16(frame.carrier(coordinate)), maximum, 16)\n        high = not bool(frame.status & 5)\n    if high:\n        frame = _movement_move(state, frame, coordinate, maximum, 16)\nframe = _duel_commit_shift_fields(state, frame, coordinate, 7, True)\nreturn _settlement_store_word_fields(state, frame, frame.scan, low16(frame.target_y), low16(frame.carrier(coordinate)), displacement)"}})

DECLARATIONS.update({'adjust_battle_result_pair_spacing_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 130004)\nframe = _movement_compare(state, frame, low16(frame.target_x), state.read(4294964994, 2), 16)\nframe = _movement_move(state, frame, 'target_y', state.read(4294964998 if frame.status & 4 else 4294964994, 2), 16)\nframe = first_replace(frame, controller=state.table_at(4294943056))\nframe = _movement_move(state, frame, 'unit', low16(frame.target_x), 16)\nframe = _movement_fixed_shift_word(state, frame, 'target_y', 2)\nframe = _movement_fixed_shift_word(state, frame, 'unit', 2)\nframe = _movement_move(state, frame, 'count', 0, 16)\nfor coordinate, displacement, bit in (('distance', 0, 0), ('offset_x', 2, 1)):\n    frame = _movement_move(state, frame, coordinate, frame.controller.word(low16(frame.unit), displacement), 16)\n    frame = _duel_commit_sub_word_fields(state, frame, coordinate, frame.controller.word(low16(frame.target_y), displacement))\n    if frame.status & 1:\n        frame = _duel_commit_sub_word_fields(state, frame, coordinate, 0, True)\n        frame = _battle_result_count_bit_fields(state, frame, bit, True)\n    frame = _duel_commit_sub_word_fields(state, frame, coordinate, 2304)\n    if not frame.status & 1:\n        return frame\nframe = _movement_compare(state, frame, low16(frame.offset_x), low16(frame.distance), 16)\nvertical = not bool(frame.status & 5)\ncoordinate, displacement, bit = ('offset_x', 2, 1) if vertical else ('distance', 0, 0)\nframe = _battle_result_count_bit_fields(state, frame, bit)\nif frame.status & 4:\n    frame = _duel_commit_sub_word_fields(state, frame, coordinate, 0, True)\nframe, moved = _movement_binary_flags(state, frame, frame.controller.word(low16(frame.unit), displacement), low16(frame.carrier(coordinate)), 16)\nframe.controller.set_word(low16(frame.unit), moved, displacement)\nreturn frame"}})

DECLARATIONS.update({'advance_battle_result_order_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': 'frame = _resource_cost_frame(state, frame, 129800)\nframe = _duel_menu_change_word_fields(state, frame, 4294964066, 1)\nreturn _deployment_menu_call_fields(state, frame, 129810, 129808)'}})

DECLARATIONS.update({'assign_battle_result_retreat_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 130442)\nframe = _movement_move(state, frame, 'target_y', low16(frame.target_x), 16)\nframe = _movement_fixed_shift_word(state, frame, 'target_y', 2)\nframe = first_replace(frame, controller=state.table_at(4294943056))\nframe = _movement_move(state, frame, 'unit', frame.controller.word(low16(frame.target_y)), 16)\nframe = _movement_move(state, frame, 'count', frame.controller.word(low16(frame.target_y), 2), 16)\nframe = first_replace(frame, controller=state.table_at(4294945120), scan=state.table_at(16722944).cursor())\nframe = _movement_move(state, frame, 'distance', frame.controller.word(low16(frame.target_y)), 16)\nframe = _movement_move(state, frame, 'distance', low16(frame.distance) | frame.controller.word(low16(frame.target_y), 2), 16)\nmoving = not bool(frame.status & 4)\nif not moving:\n    frame = _movement_compare(state, frame, low16(frame.target_x), state.read(4294964994, 2), 16)\n    frame = _movement_move(state, frame, 'distance', state.read(4294964998 if frame.status & 4 else 4294964994, 2), 16)\n    frame = first_replace(frame, opponent=state.table_at(4294943056))\n    frame = _movement_fixed_shift_word(state, frame, 'distance', 2)\nfor coordinate, displacement, maximum in (('unit', 0, 25600), ('count', 2, 37888)):\n    if moving:\n        frame = _battle_result_velocity_retreat_axis_fields(state, frame, coordinate, displacement, maximum)\n    else:\n        frame = _battle_result_stationary_retreat_axis_fields(state, frame, coordinate, displacement, maximum)\nframe = first_replace(frame, controller=state.table_at(16727490))\nframe = _settlement_write_byte_fields(state, frame, frame.controller, 2, low16(frame.target_x))\nframe = first_replace(frame, controller=state.table_at(4294946344))\nframe = _settlement_write_byte_fields(state, frame, frame.controller, 1, low16(frame.target_x))\nframe = _movement_move(state, frame, 'choice', low16(frame.target_x), 16)\nreturn _deployment_menu_call_fields(state, frame, 122026, 130776)"}})

DECLARATIONS.update({'battle_result_pair_removed_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 130128)\nframe = first_replace(frame, roster=state.table_at(4294953984).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964994, 2), 16)\nframe = _movement_compare(state, frame, frame.roster.byte(low16(frame.target_x)), 255, 8)\nremoved = bool(frame.status & 4)\nif not removed:\n    frame = _movement_move(state, frame, 'target_x', state.read(4294964998, 2), 16)\n    frame = _movement_compare(state, frame, frame.roster.byte(low16(frame.target_x)), 255, 8)\n    removed = bool(frame.status & 4)\nstatus = frame.status | 1 if removed else frame.status & 30\nstate.sr = state.sr & 65504 | status\nreturn first_replace(frame, status=status)"}})

DECLARATIONS.update({'battle_result_selected_roster_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 130174)\nframe = _movement_move(state, frame, 'unit', frame.candidates.word(), 16)\nframe = first_replace(frame, controller=state.table_at(4294944164).cursor())\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964951, 1)\nif frame.status & 4:\n    frame = first_replace(frame, controller=state.table_at(4294944080).cursor())\nwhile True:\n    frame = _movement_move(state, frame, 'count', frame.controller.word(), 16)\n    frame = first_replace(frame, controller=frame.controller.advance(2))\n    if frame.status & 8:\n        status = frame.status | 1\n        break\n    frame = _movement_compare(state, frame, low16(frame.count), low16(frame.unit), 16)\n    if frame.status & 4:\n        status = frame.status & 30\n        break\nstate.sr = state.sr & 65504 | status\nreturn first_replace(frame, status=status)"}})

