DECLARATIONS.update({'resolve_battle_result_pair_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 129894)\nframe = first_replace(frame, roster=state.table_at(4294964994).cursor(), candidates=state.table_at(4294964998).cursor())\nframe = _movement_move(state, frame, 'target_y', state.read(4294964878, 2), 16)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964951, 1)\nif frame.status & 4:\n    frame = first_replace(frame, roster=frame.candidates, candidates=frame.roster)\n    frame = _movement_move(state, frame, 'target_y', state.read(4294964876, 2), 16)\nframe = first_replace(frame, controller=state.table_at(4294954670))\nframe = _movement_move(state, frame, 'target_x', frame.roster.word(), 16)\nframe = _settlement_write_byte_fields(state, frame, frame.controller, 100, low16(frame.target_x))\nframe = _deployment_menu_call_fields(state, frame, 130128, 129938)\nif not frame.status & 1:\n    frame = _deployment_menu_call_fields(state, frame, 130174, 129946)\n    if not frame.status & 1:\n        frame = _deployment_menu_call_fields(state, frame, 130218, 129954)\n        for address in (4294964858, 4294964860, 4294964862):\n            frame = _movement_compare(state, frame, low16(frame.target_y), state.read(address, 2), 16)\n            if frame.status & 4:\n                return _duel_menu_change_word_fields(state, frame, 4294964066, 1)\n        frame = _movement_move(state, frame, 'target_x', frame.candidates.word(), 16)\n        frame = _deployment_menu_call_fields(state, frame, 130004, 129984)\n        frame = _deployment_menu_call_fields(state, frame, 130442, 129988)\nreturn _duel_menu_write_word_fields(state, frame, 4294964066, 5)"}})

