DECLARATIONS.update({'separate_battle_result_pair_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 130218)\nfrom ..high_level_main_flows.business_movement_support import _movement_save_longs, _movement_restore_longs\nsaved = ('target_x', 'target_y', 'unit', 'count', 'distance', 'offset_x', 'offset_y', 'roster', 'candidates')\nframe = _movement_save_longs(state, frame, saved)\nframe = first_replace(frame, roster=state.table_at(4294943056).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964994, 2), 16)\nframe = _movement_move(state, frame, 'target_y', state.read(4294964998, 2), 16)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964951, 1)\nif not frame.status & 4:\n    frame = first_replace(frame, target_x=frame.target_y, target_y=frame.target_x)\nframe = _movement_fixed_shift_word(state, frame, 'target_x', 2)\nframe = _movement_fixed_shift_word(state, frame, 'target_y', 2)\nwhile True:\n    for size, correction, displacement in (('count', 'offset_x', 0), ('distance', 'offset_y', 2)):\n        frame = _movement_move(state, frame, 'unit', frame.roster.word(low16(frame.target_x), displacement), 16)\n        frame = _duel_commit_sub_word_fields(state, frame, 'unit', frame.roster.word(low16(frame.target_y), displacement))\n        if not frame.status & 1:\n            frame = _movement_move(state, frame, size, 2048, 16)\n            frame = _duel_commit_sub_word_fields(state, frame, size, low16(frame.unit))\n            if frame.status & 1:\n                frame = _movement_move(state, frame, size, 0, 16)\n            frame = _movement_move(state, frame, correction, low16(frame.carrier(size)), 16)\n        else:\n            frame = _duel_commit_sub_word_fields(state, frame, 'unit', 63488)\n            if frame.status & 1:\n                if displacement == 0:\n                    frame = _movement_move(state, frame, 'unit', 0, 16)\n                else:\n                    frame = first_replace(frame, status=frame.status & 30)\n                    state.sr = state.sr & 65504 | frame.status\n            frame = _movement_move(state, frame, size, low16(frame.unit), 16)\n            frame = _movement_move(state, frame, correction, low16(frame.unit), 16)\n            frame = _duel_commit_sub_word_fields(state, frame, correction, 0, True)\n    frame = _movement_compare(state, frame, low16(frame.distance), low16(frame.count), 16)\n    if frame.status & 1:\n        frame = _movement_move(state, frame, 'count', frame.roster.word(low16(frame.target_x)), 16)\n        frame = _movement_move(state, frame, 'unit', frame.roster.word(low16(frame.target_x), 2), 16)\n        frame = _movement_add_word(state, frame, 'unit', low16(frame.offset_y))\n        frame = _movement_move(state, frame, 'distance', low16(frame.unit), 16)\n    else:\n        frame = _movement_move(state, frame, 'unit', frame.roster.word(low16(frame.target_x)), 16)\n        frame = _movement_add_word(state, frame, 'unit', low16(frame.offset_x))\n        frame = _movement_move(state, frame, 'count', low16(frame.unit), 16)\n        frame = _movement_move(state, frame, 'distance', frame.roster.word(low16(frame.target_x), 2), 16)\n    frame = first_replace(frame, candidates=state.table_at(713138).cursor())\n    frame = _movement_move(state, frame, 'unit', state.read(4294964874, 2), 16)\n    frame = _movement_fixed_shift_word(state, frame, 'unit', 3)\n    interior = True\n    for coordinate, displacement, minimum in (('count', 0, True), ('count', 2, False), ('distance', 4, True), ('distance', 6, False)):\n        frame = _movement_compare(state, frame, low16(frame.carrier(coordinate)), frame.candidates.word(low16(frame.unit), displacement), 16)\n        if frame.status & 5 if minimum else not frame.status & 1:\n            interior = False\n            break\n    if not interior:\n        break\n    frame = first_replace(frame, target_x=frame.target_y, target_y=frame.target_x)\nframe = _settlement_store_word_fields(state, frame, frame.roster, low16(frame.target_x), low16(frame.count))\nframe = _settlement_store_word_fields(state, frame, frame.roster, low16(frame.target_x), low16(frame.distance), 2)\nreturn _movement_restore_longs(state, frame, saved)"}})

