DECLARATIONS.update({'_city_description_change_word_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, address: int, step: int', 'returns': 'FirstDeploymentFrame', 'flow': "if address not in (4294964088, 4294964744, 4294964944, 4294964948, 4294964074, 4294964066, 4294954962) or step not in (-1, 1):\n    raise ValueError('original selection counter and step required')\nframe, changed = _movement_binary_flags(state, frame, state.read(address, 2), 1, 16, step < 0)\nstate.write(address, 2, changed)\nreturn frame"}})

