DECLARATIONS.update({'_city_primary_description_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, alternate: bool', 'returns': 'FirstDeploymentFrame', 'flow': "if type(alternate) is not bool:\n    raise ValueError('original194DA or194FA entry required')\nframe = _resource_cost_frame(state, frame, 103674 if alternate else 103642)\nif not alternate:\n    frame, draw = _city_description_refresh_gate_fields(state, frame)\n    if not draw:\n        return frame\nframe = first_replace(frame, roster=state.table_at(103712).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964088, 2), 16)\nframe = _duel_commit_sub_word_fields(state, frame, 'target_x', state.read(4294964824, 2))\nframe = _movement_move(state, frame, 'target_y', low16(frame.target_x), 16)\nframe = _movement_fixed_shift_word(state, frame, 'target_x', 1)\nframe = _movement_add_word(state, frame, 'target_x', low16(frame.target_y))\nframe = _movement_fixed_shift_word(state, frame, 'target_x', 3)\nframe = _movement_add_word(state, frame, 'target_x', 16)\nframe = _movement_move(state, frame, 'target_y', 224, 16)\nframe = _movement_move(state, frame, 'unit', 0, 16)\nreturn _battle_command_call_fields(state, frame, 44040, 103710)"}})

