DECLARATIONS.update({'build_city_unassigned_roster_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 105630)\nframe = _duel_menu_write_word_fields(state, frame, 4294964106, state.read(4294964754, 2))\nframe = _duel_menu_write_word_fields(state, frame, 4294964144, 5)\nframe = _duel_menu_write_word_fields(state, frame, 4294964754, 1034)\nframe = _duel_menu_write_word_fields(state, frame, 4294964066, 0, clear=True)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964950, 2), 16)\nframe = _movement_fixed_shift_word(state, frame, 'target_x', 1)\npointer = state.read(u32(105622 + s16(low16(frame.target_x))), 4)\nframe = first_replace(frame, roster=state.table_at(pointer).cursor(), candidates=state.table_at(4294944248).cursor(), controller=state.table_at(4294944596).cursor(), scan=state.table_at(16727234).cursor())\nwhile True:\n    member = frame.roster.word()\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _movement_move(state, frame, 'target_x', member, 16)\n    if frame.status & 8:\n        break\n    frame = _movement_compare(state, frame, low16(frame.target_x), 256, 16)\n    if not frame.status & 1:\n        continue\n    frame = _movement_test(state, frame, frame.controller.byte(low16(frame.target_x)), 8)\n    if not frame.status & 4:\n        continue\n    frame = _movement_test(state, frame, frame.scan.byte(low16(frame.target_x)), 8)\n    if not frame.status & 4:\n        continue\n    frame = _settlement_store_word_fields(state, frame, frame.candidates, 0, low16(frame.target_x))\n    frame = first_replace(frame, candidates=frame.candidates.advance(2))\nframe = _settlement_store_word_fields(state, frame, frame.candidates, 0, 65535)\nreturn first_replace(frame, candidates=frame.candidates.advance(2))"}})

