DECLARATIONS.update({'_city_action_find_city_owner_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = first_replace(frame, roster=state.table_at(4294942800).cursor())\nframe = _movement_move(state, frame, 'target_y', 255, 16)\nwhile True:\n    frame = _movement_compare(state, frame, low8(frame.target_x), frame.roster.byte(low16(frame.target_y)), 8)\n    if frame.status & 4:\n        return frame\n    remaining = u16(low16(frame.target_y) - 1)\n    frame = first_replace(frame, target_y=replace_word(frame.target_y, remaining))\n    if remaining == 65535:\n        return frame"}})

DECLARATIONS.update({'_city_action_mark_side_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "from ..high_level_gameplay_flow.business_battle import _postbattle_bit_fields\nbit = low16(frame.target_x)\nif bit not in (0, 1, 2, 3):\n    raise ValueError('actual masked city side bit required')\nold = state.read(4294964984, 1)\nframe = _postbattle_bit_fields(frame, bool(old & 1 << bit))\nstate.sr = state.sr & 65504 | frame.status\nstate.write(4294964984, 1, old | 1 << bit)\nreturn frame"}})

