DECLARATIONS.update({'build_city_troop_number_packet_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 107296)\nframe = first_replace(frame, controller=state.table_at(107434).cursor(), scan=state.table_at(4294956032).cursor())\nframe = _settlement_store_word_fields(state, frame, frame.scan, 0, 65528)\nframe = first_replace(frame, scan=frame.scan.advance(2))\nframe = _settlement_store_word_fields(state, frame, frame.scan, 0, frame.controller.word(low16(frame.distance)))\nframe = first_replace(frame, scan=frame.scan.advance(2))\nframe = _settlement_store_word_fields(state, frame, frame.scan, 0, 20472)\nframe = first_replace(frame, scan=frame.scan.advance(2), controller=state.table_at(4294952960).cursor())\nframe = _movement_move_long(state, frame, 'offset_x', frame.controller.long(low16(frame.count)))\nframe = _movement_compare(state, frame, low16(frame.offset_x), 1000, 16)\nif not frame.status & 1:\n    frame = _movement_move(state, frame, 'offset_y', 0, 16)\n    while True:\n        frame = _duel_commit_sub_word_fields(state, frame, 'offset_x', 10000)\n        if frame.status & 1:\n            break\n        frame = _movement_adjust_word(state, frame, 'offset_y', 1)\n    frame = _movement_add_word(state, frame, 'offset_x', 10000)\n    frame = _movement_test(state, frame, low16(frame.offset_y), 16)\n    if frame.status & 4:\n        frame = _movement_move(state, frame, 'offset_y', 17409, 16)\n    else:\n        frame = _movement_add_word(state, frame, 'offset_y', 17286)\n    for value in (0, low16(frame.offset_y), 4088):\n        frame = _settlement_store_word_fields(state, frame, frame.scan, 0, value)\n        frame = first_replace(frame, scan=frame.scan.advance(2))\n    if frame.offset_x // 1000 <= 65535:\n        frame = _movement_divu_word(state, frame, 'offset_x', 1000, 107376)\n    frame = _movement_add_word(state, frame, 'offset_x', 17286)\nelse:\n    for value in (0, 17285, 4088):\n        frame = _settlement_store_word_fields(state, frame, frame.scan, 0, value)\n        frame = first_replace(frame, scan=frame.scan.advance(2))\n    if frame.offset_x // 100 <= 65535:\n        frame = _movement_divu_word(state, frame, 'offset_x', 100, 107410)\n    frame = _movement_add_word(state, frame, 'offset_x', 17286)\nfor value in (0, low16(frame.offset_x), 0):\n    frame = _settlement_store_word_fields(state, frame, frame.scan, 0, value)\n    frame = first_replace(frame, scan=frame.scan.advance(2))\nreturn _settlement_store_word_fields(state, frame, frame.scan, 0, 32768)"}})

