DECLARATIONS.update({'dispatch_city_notice_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 106406)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964066, 2), 16)\nframe = _movement_fixed_shift_word(state, frame, 'target_x', 1)\nrelative = state.read(u32(106428 + s16(low16(frame.target_x))), 2)\nframe = _movement_move(state, frame, 'target_x', relative, 16)\nframe = _deployment_menu_call_fields(state, frame, u32(106434 + s16(relative)), 106420)\nreturn _deployment_menu_call_fields(state, frame, 41946, 106426)"}})

DECLARATIONS.update({'draw_city_order_map_marker_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 107008)\nframe = _movement_compare(state, frame, state.read(4294964932, 2), 1, 16)\nif not frame.status & 4:\n    return frame\nframe = _movement_move(state, frame, 'unit', state.read(4294964874, 2), 16)\nframe = first_replace(frame, roster=state.table_at(4294942719).cursor())\nframe = _movement_move(state, frame, 'target_y', 0, 16)\nframe = _movement_move(state, frame, 'target_y', frame.roster.byte(low16(frame.unit)), 8)\nif frame.status & 4:\n    return frame\nframe = _movement_fixed_shift_word(state, frame, 'target_y', 1)\nframe = _first_shift_word(frame, 'unit', low16(frame.unit), 5)\nstate.sr = state.sr & 65504 | frame.status\nframe = _movement_add_word(state, frame, 'unit', low16(frame.target_y))\nframe = first_replace(frame, candidates=state.table_at(703912).cursor())\nframe = _movement_move(state, frame, 'target_x', 0, 16)\nframe = _movement_move(state, frame, 'target_x', frame.candidates.byte(low16(frame.unit)), 8)\nframe = _movement_fixed_shift_word(state, frame, 'target_x', 3)\nframe = _movement_move(state, frame, 'target_y', 0, 16)\nframe = _movement_move(state, frame, 'target_y', frame.candidates.byte(low16(frame.unit), 1), 8)\nframe = _movement_fixed_shift_word(state, frame, 'target_y', 3)\nframe = _movement_move(state, frame, 'unit', 0, 16)\nframe = first_replace(frame, roster=state.table_at(107076).cursor())\nreturn _deployment_menu_call_fields(state, frame, 44040, 107074)"}})

DECLARATIONS.update({'draw_city_side_troop_rosters_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 107192)\nframe = first_replace(frame, opponent=state.table_at(16726978), candidates=state.table_at(4294944080).cursor())\nframe = _movement_move(state, frame, 'distance', 0, 16)\nframe = _deployment_menu_call_fields(state, frame, 107222, 107208)\nframe = first_replace(frame, candidates=state.table_at(4294944164).cursor())\nframe = _movement_move(state, frame, 'distance', 2, 16)\nreturn _deployment_menu_call_fields(state, frame, 107222, 107220)"}})

DECLARATIONS.update({'draw_city_troop_roster_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 107222)\nwhile True:\n    member = frame.candidates.word()\n    frame = first_replace(frame, candidates=frame.candidates.advance(2))\n    frame = _movement_move(state, frame, 'count', member, 16)\n    if frame.status & 8:\n        return frame\n    frame = _movement_move(state, frame, 'count', low16(frame.count) & 255, 16)\n    frame = _movement_move(state, frame, 'offset_x', low16(frame.count), 16)\n    frame = _movement_fixed_shift_word(state, frame, 'count', 2)\n    frame = first_replace(frame, controller=state.table_at(4294943056).cursor())\n    frame = _movement_move(state, frame, 'target_x', frame.controller.word(low16(frame.count)), 16)\n    if frame.status & 4:\n        continue\n    frame = _duel_commit_shift_fields(state, frame, 'target_x', 7, True)\n    frame = _movement_move(state, frame, 'target_y', frame.controller.word(low16(frame.count), 2), 16)\n    frame = _duel_commit_shift_fields(state, frame, 'target_y', 7, True)\n    frame = _deployment_menu_call_fields(state, frame, 107468, 107258)\n    if frame.status & 1:\n        continue\n    frame = _deployment_menu_call_fields(state, frame, 107442, 107264)\n    if frame.status & 1:\n        frame = _duel_menu_byte_bit_fields(state, frame, 4294964001, 3)\n        if not frame.status & 4:\n            continue\n    frame = _deployment_menu_call_fields(state, frame, 107296, 107280)\n    frame = first_replace(frame, roster=state.table_at(4294956032).cursor())\n    frame = _movement_move(state, frame, 'unit', 0, 16)\n    frame = _deployment_menu_call_fields(state, frame, 44040, 107292)"}})

