DECLARATIONS.update({'step_queued_object_route_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 92056)\nframe = _movement_move(state, frame, 'target_x', state.read(4294954656, 2), 16)\nframe = _movement_fixed_shift_word(state, frame, 'target_x', 2)\nframe = first_replace(frame, auxiliary=state.table_at(u32(4294954496 + s16(low16(frame.target_x)))))\naddress = frame.auxiliary.address()\nframe = _group_route_store_fields(state, frame, address, state.read(address, 1) & 131, 1)\nframe = _movement_move(state, frame, 'target_x', state.read(4294954660, 2), 16)\nframe = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 15, 16)\naligned = bool(frame.status & 4)\nif aligned:\n    frame = _movement_move(state, frame, 'target_x', state.read(4294954662, 2), 16)\n    frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 15, 16)\n    aligned = bool(frame.status & 4)\nif aligned:\n    frame = _movement_move(state, frame, 'target_x', state.read(4294954660, 2), 16)\n    frame = _movement_fixed_shift_word(state, frame, 'target_x', 4, True)\n    frame = _group_route_store_fields(state, frame, frame.auxiliary.address(0, 1), low8(frame.target_x), 1)\n    frame = _movement_move(state, frame, 'target_x', state.read(4294954662, 2), 16)\n    frame = _movement_fixed_shift_word(state, frame, 'target_x', 4, True)\n    frame = _group_route_store_fields(state, frame, frame.auxiliary.address(0, 2), low8(frame.target_x), 1)\n    arrived = False\n    for target, token in ((92276, 92116), (92450, 92124), (92486, 92132)):\n        frame = _group_route_call_fields(state, frame, target, token)\n        if frame.status & 1:\n            arrived = True\n            break\n    if arrived:\n        frame = _group_route_memory_delta_fields(state, frame, 4294954656, 1)\n        return _group_route_store_fields(state, frame, 4294964066, 0, 2, True)\n    frame = _movement_move(state, frame, 'target_x', state.read(4294954660, 2), 16)\n    frame = _movement_move(state, frame, 'target_y', state.read(4294954662, 2), 16)\n    frame = _group_route_call_fields(state, frame, 82580, 92150)\n    frame = _movement_compare(state, frame, low8(frame.unit), 4, 8)\n    if not frame.status & 4:\n        frame = _movement_move(state, frame, 'target_x', 164, 16)\n        frame = _group_route_call_fields(state, frame, 32906, 92168)\nframe = _movement_move(state, frame, 'target_x', state.read(4294954660, 2), 16)\nframe = _movement_compare(state, frame, low16(frame.target_x), state.read(4294954664, 2), 16)\nif not frame.status & 4:\n    frame = _group_route_memory_delta_fields(state, frame, 4294954660, 1 if frame.status & 1 else -1)\nelse:\n    frame = _movement_move(state, frame, 'target_x', state.read(4294954662, 2), 16)\n    frame = _movement_compare(state, frame, low16(frame.target_x), state.read(4294954666, 2), 16)\n    if not frame.status & 1 and (not frame.status & 4):\n        frame = _group_route_store_fields(state, frame, address, state.read(address, 1) & 127, 1)\n        frame = _group_route_memory_delta_fields(state, frame, 4294954662, -1)\n    else:\n        frame = _group_route_memory_delta_fields(state, frame, 4294954662, 1)\n        frame = _group_route_store_fields(state, frame, address, state.read(address, 1) | 128, 1)\nframe = _movement_move(state, frame, 'target_y', state.read(4294954660, 2), 16)\nframe = _group_route_register_delta_fields(state, frame, 'target_y', -104)\nif frame.status & 1:\n    frame = _movement_move(state, frame, 'target_y', 0, 16)\nframe = _movement_move(state, frame, 'unit', state.read(4294954662, 2), 16)\nframe = _group_route_register_delta_fields(state, frame, 'unit', -152)\nif frame.status & 1:\n    frame = _movement_move(state, frame, 'unit', 0, 16)\nreturn _group_route_call_fields(state, frame, 85348, 92274)"}})
DECLARATIONS.update({'step_group_action_choice_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': 'frame = _resource_cost_frame(state, frame, 88672)\nframe = _group_route_call_fields(state, frame, 88780, 88676)\nframe = _group_route_call_fields(state, frame, 88810, 88680)\nframe = _movement_test(state, frame, state.read(4294954962, 2), 16)\ncheck_secondary_button = True\nif not frame.status & 4:\n    frame = _group_route_memory_delta_fields(state, frame, 4294954962, -1)\n    frame = _movement_compare(state, frame, state.read(4294954962, 2), 8, 16)\n    if not frame.status & 1 and (not frame.status & 4):\n        frame = _group_route_store_fields(state, frame, 4294954962, 8)\nelse:\n    frame = _group_route_bit_fields(state, frame, state.read(4294964739, 1), 5)\n    if not frame.status & 4:\n        frame = _group_route_call_fields(state, frame, 49334, 88726)\n        for address, value in ((4294964754, 520), (4294964066, 3), (4294964074, 18)):\n            frame = _group_route_store_fields(state, frame, address, value)\n        check_secondary_button = False\nif check_secondary_button:\n    frame = _group_route_bit_fields(state, frame, state.read(4294964739, 1), 4)\n    if not frame.status & 4:\n        for address, value in ((4294964754, 520), (4294964066, 2), (4294964074, 18)):\n            frame = _group_route_store_fields(state, frame, address, value)\nreturn _group_route_call_fields(state, frame, 41304, 88778)'}})

