DECLARATIONS.update({'_city_result_owner_match_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, owner_addresses: tuple[int, int, int]', 'returns': 'tuple[FirstDeploymentFrame, bool]', 'flow': "if owner_addresses not in ((4294964859, 4294964861, 4294964863), (4294964858, 4294964860, 4294964862)):\n    raise ValueError('original packed-result owner BYTEs required')\nwidth = 1 if owner_addresses[0] == 4294964859 else 2\nfor address in owner_addresses:\n    value = low8(frame.target_x) if width == 1 else low16(frame.target_x)\n    frame = _movement_compare(state, frame, value, state.read(address, width), width * 8)\n    if frame.status & 4:\n        return (frame, True)\nreturn (frame, False)"}})

