DECLARATIONS.update({'_append_city_decimal_tail_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, include_hundreds: bool, include_thousands: bool=False, include_ten_thousands: bool=False', 'returns': 'FirstDeploymentFrame', 'flow': "if include_thousands and (not include_hundreds):\n    raise ValueError('actual1273C thousands tail also includes hundreds')\nif include_ten_thousands and (not (include_thousands and include_hundreds)):\n    raise ValueError('actual12734 tail includes thousands and hundreds')\nframe = _resource_cost_frame(state, frame, 75572 if include_ten_thousands else 75580 if include_thousands else 75588 if include_hundreds else 75596)\nfrom ..high_level_player_commands.business_budget import _decimal_value_place_fields\nfrom ..high_level_player_commands.contexts_numeric import DecimalMemory\nnumeric = DecimalMemory(state, frame.stack_cursor)\ndestination = state.table_at(frame.auxiliary.base).cursor()\ndigit_tile = low16(frame.target_y)\nplaces = ((100, 75596), (10, 75604)) if include_hundreds else ((10, 75604),)\nif include_thousands:\n    places = ((1000, 75588),) + places\nif include_ten_thousands:\n    places = ((10000, 75580),) + places\nfor divisor, continuation in places:\n    frame = _movement_move(state, frame, 'count', divisor, 16)\n    numeric.enter_call(continuation)\n    result = _decimal_value_place_fields(numeric, frame.target_x, divisor, digit_tile, low16(frame.unit), low16(frame.distance), destination)\n    numeric.leave_call(continuation)\n    frame = first_replace(frame, target_x=result.remainder, distance=replace_word(frame.distance, result.started), offset_x=replace_word(frame.offset_x, result.glyph), stack_cursor=numeric.stack_cursor)\nframe = _movement_move(state, frame, 'offset_x', 0, 16)\nframe = _movement_move(state, frame, 'offset_x', numeric.glyph(low16(frame.target_x)), 8)\nframe = _movement_add_word(state, frame, 'offset_x', digit_tile)\ndestination.append_word(low16(frame.offset_x))\nframe = first_replace(frame, auxiliary=destination, stack_cursor=numeric.stack_cursor)\nreturn _movement_test(state, frame, low16(frame.offset_x), 16)"}, 'append_city_five_place_decimal_tail_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': 'return _append_city_decimal_tail_fields(state, frame, True, True, True)'}})

